pragma ComponentBehavior: Bound

import QtQuick
import Quickshell
import Quickshell.Io
import qs.services
import qs.modules.controlcenter
import qs.components.icons
import qs.components.controls

/**
 * 更 UPDATES sub-surface: a terminal-free face for the Ricelin update engine. It
 * never touches git itself; it shells out to the python engine at
 * ~/.config/hypr/scripts/ricelin-update.py, which prints one JSON object, and
 * renders that. `check` is a safe dry-run that reports how far behind the install
 * is, the changelog, and any protected file whose local edits clash with upstream;
 * `apply` performs the update, taking upstream wholesale only for the conflicting
 * files the user explicitly opted to overwrite.
 *
 * The engine owns every policy decision (devmode detection, on-demand cloning,
 * three-way merges); this surface is a thin reader of its contract. On a dev or
 * symlinked-worktree install the engine answers "devmode" and the surface shows a
 * calm note that updates run through plain git instead, with no buttons. Reached
 * from the settings index and morphs back to it on an empty click or the back
 * chevron.
 */
SettingsSurface {
    id: root

    backSurface: "settings"
    implicitHeight: content.implicitHeight
    rows: []

    readonly property string engine: Quickshell.env("HOME") + "/.config/hypr/scripts/ricelin-update.py"

    property string status: ""
    property string version: ""
    property int behindCount: 0
    property string fromDate: ""
    property string toDate: ""
    property var changelog: []
    property var conflicts: []
    property string errorText: ""

    property bool checking: false
    property bool applying: false
    property bool restartNeeded: false

    /** Target short sha, split off the engine's "<sha> <date>" version string. */
    readonly property string targetShort: version.split(" ")[0]

    /**
     * Short sha of the installed rice, read from the engine's manifest since the
     * check result only names the target. Empty until a first apply recorded one.
     */
    property string installedShort: ""

    function readManifest() {
        try {
            root.installedShort = (JSON.parse(manifestFile.text()).syncedSha || "").slice(0, 7);
        } catch (e) {
            root.installedShort = "";
        }
    }

    /** Conflicting rel-paths the user chose to overwrite with upstream on the next apply. */
    property var takePaths: ({})

    /** Core packages this update needs that aren't installed yet: [{id, name, desc, group}]. */
    property var missingDeps: []

    /**
     * Packages the last apply couldn't bring in: [{id, error}]. A cancelled password
     * prompt, an AUR build that needs a terminal, or a repo miss all land here so a
     * failed or skipped install is never silent. Held until the next check.
     */
    property var depFailures: []

    /** Per-dep install choice, keyed by id. Absent means default ON, false means opted out. */
    property var installDeps: ({})

    /** A dep is installed on apply unless the user explicitly turned its toggle off. */
    function depChosen(id) {
        return root.installDeps[id] !== false;
    }

    /** Title-case the package id into a readable label, e.g. noto-fonts-cjk -> Noto Fonts Cjk. */
    function prettyDep(id) {
        return id.split("-").map(function (w) {
            return w.length > 0 ? w.charAt(0).toUpperCase() + w.slice(1) : w;
        }).join(" ");
    }

    readonly property bool busy: checking || applying
    readonly property bool behind: status === "ok" && behindCount > 0
    readonly property bool upToDate: status === "ok" && behindCount === 0

    /** rel-path -> human label for the protected files the engine can three-way merge. */
    readonly property var friendlyName: ({
        "hypr/modules/binds.lua": "Keybinds",
        "hypr/modules/decoration.lua": "Look",
        "hypr/modules/monitors.lua": "Display",
        "hypr/modules/input.lua": "Input",
        "hypr/modules/env.lua": "Environment",
        "hypr/modules/autostart.lua": "Autostart",
        "hypr/modules/animations.lua": "Animations",
        "hypr/hypridle.conf": "Idle & Lock"
    })

    function labelFor(rel) {
        return friendlyName[rel] !== undefined ? friendlyName[rel] : rel;
    }

    readonly property string statusKind: applying ? "applying"
        : checking ? "checking"
        : restartNeeded ? "applied"
        : status === "devmode" ? "devmode"
        : status === "offline" ? "offline"
        : status === "noclone" ? "noclone"
        : status === "error" ? "error"
        : behind ? "behind"
        : upToDate ? "ok"
        : "idle"

    readonly property bool spinning: checking || applying

    readonly property string badgeIcon: statusKind === "behind" ? "arrow-up"
        : statusKind === "error" || statusKind === "offline" ? "close"
        : statusKind === "devmode" ? "bolt"
        : statusKind === "noclone" ? "download"
        : "check"

    readonly property color badgeTint: statusKind === "error" || statusKind === "offline" ? Theme.dim
        : statusKind === "checking" || statusKind === "applying" || statusKind === "idle" || statusKind === "noclone" ? Theme.subtle
        : Theme.vermLit

    readonly property string headline: statusKind === "applying" ? "Updating…"
        : statusKind === "checking" ? "Checking…"
        : statusKind === "applied" ? "Updated"
        : statusKind === "devmode" ? "Developer install"
        : statusKind === "offline" ? "Couldn't reach the server"
        : statusKind === "noclone" ? "Ready to set up"
        : statusKind === "error" ? "Check failed"
        : statusKind === "behind" ? (behindCount + " update" + (behindCount === 1 ? "" : "s") + " available")
        : statusKind === "ok" ? "Up to date"
        : "Updates"

    /** A line beneath the headline that orients each state, dropped when empty. */
    readonly property string subline: statusKind === "devmode" ? "This is a clone or symlinked work-tree, so updates run through plain git. In-app updating is off here."
        : statusKind === "noclone" ? "The rice copy didn't land yet. Check for updates to fetch it, then updates show up here."
        : statusKind === "error" ? errorText
        : statusKind === "behind" ? (fromDate.length > 0 ? fromDate + " → " + toDate : "")
        : ""

    onActiveChanged: {
        if (active) {
            startCheck();
        } else {
            checking = false;
            applying = false;
            focusRowItem = null;
            kbIndex = -1;
        }
    }

    function resetResult() {
        status = "";
        behindCount = 0;
        fromDate = "";
        toDate = "";
        changelog = [];
        conflicts = [];
        missingDeps = [];
        installDeps = ({});
        depFailures = [];
        errorText = "";
        takePaths = ({});
    }

    /** Drop the behind-driven sections so they vanish once an apply has landed. */
    function clearPending() {
        behindCount = 0;
        changelog = [];
        conflicts = [];
        missingDeps = [];
        installDeps = ({});
        takePaths = ({});
    }

    /**
     * The body for the post-restart toast, composed before clearPending wipes the
     * changelog. The version line confirms what landed, and the top change names
     * what is new with a count when more rode along.
     */
    function updatedBody() {
        var v = root.version.replace(" ", " · ");
        if (root.changelog.length > 0) {
            var more = root.changelog.length > 1
                ? "  (+" + (root.changelog.length - 1) + " more)" : "";
            return "Now on " + v + "\n" + root.changelog[0] + more;
        }
        return "Now on " + v;
    }

    function ingest(data) {
        root.status = data.status || "error";
        root.behindCount = data.behind || 0;
        root.fromDate = data.fromDate || "";
        root.toDate = data.toDate || "";
        root.changelog = data.changelog || [];
        root.conflicts = data.conflicts || [];
        root.missingDeps = data.missingDeps || [];
        root.depFailures = data.depFailures || [];
        root.errorText = data.error || "";
        if (data.version && data.version.length > 0)
            root.version = data.version;
        if (data.applied)
            root.restartNeeded = data.restartNeeded === true;
    }

    function startCheck() {
        if (root.busy)
            return;
        root.checking = true;
        root.restartNeeded = false;
        resetResult();
        checkProc.running = true;
    }

    function startApply() {
        if (root.busy)
            return;
        root.applying = true;
        var take = [];
        for (var rel in root.takePaths)
            if (root.takePaths[rel])
                take.push(rel);
        applyProc.takeArg = take.length > 0 ? take.join(",") : "";
        var deps = [];
        for (var i = 0; i < root.missingDeps.length; i++) {
            var id = root.missingDeps[i].id;
            if (root.depChosen(id))
                deps.push(id);
        }
        applyProc.installArg = deps.length > 0 ? deps.join(",") : "";
        applyProc.running = true;
    }

    FileView {
        id: manifestFile
        path: (Quickshell.env("XDG_STATE_HOME") || (Quickshell.env("HOME") + "/.local/state")) + "/ricelin/update.json"
        watchChanges: true
        printErrors: false
        onLoaded: root.readManifest()
        onFileChanged: reload()
    }

    Process {
        id: checkProc
        command: ["python3", root.engine, "check"]
        stdout: StdioCollector {
            onStreamFinished: {
                root.checking = false;
                try {
                    root.ingest(JSON.parse(this.text));
                } catch (e) {
                    root.status = "error";
                    root.errorText = "The updater returned something unexpected.";
                }
            }
        }
    }

    Process {
        id: applyProc
        property string takeArg: ""
        property string installArg: ""
        command: {
            var c = ["python3", root.engine, "apply"];
            if (takeArg.length > 0)
                c = c.concat(["--take", takeArg]);
            if (installArg.length > 0)
                c = c.concat(["--install-deps", installArg]);
            return c;
        }
        stdout: StdioCollector {
            onStreamFinished: {
                root.applying = false;
                try {
                    root.ingest(JSON.parse(this.text));
                } catch (e) {
                    root.resetResult();
                    root.status = "error";
                    root.errorText = "The updater returned something unexpected.";
                }
                /**
                 * Hold the auto-restart while any install failed: a restart wipes
                 * this surface, so the user would never see what didn't install. The
                 * code is already written to disk and lands on the next manual
                 * restart or check; the failure notice stays put until then.
                 */
                if (root.restartNeeded && root.depFailures.length === 0) {
                    markerProc.body = root.updatedBody();
                    markerProc.running = true;
                    root.clearPending();
                    restartTimer.start();
                }
            }
        }
    }

    /**
     * New code only takes effect once the shell reloads, so do it for the user
     * instead of asking. The brief delay lets the "Updated" line register first.
     */
    Timer {
        id: restartTimer
        interval: 1200
        onTriggered: restartProc.running = true
    }

    /**
     * Relaunch the pill on its own. setsid detaches the relaunch so it outlives the
     * instance it kills, and the guard skips a second spawn if the watchdog already
     * brought it back. Settings persist through flags.json, so it returns as it was.
     */
    Process {
        id: restartProc
        command: ["setsid", "sh", "-c",
            "qs -c pill kill; sleep 0.4; qs -c pill ipc show >/dev/null 2>&1 || qs -c pill -d"]
    }

    /**
     * Drop a one-shot marker the restarted shell reads to toast what landed, since
     * the relaunch wipes this surface before any inline confirmation can stick. The
     * body rides in as a positional arg so the value is never re-parsed by the shell.
     */
    Process {
        id: markerProc
        property string body: ""
        command: ["sh", "-c",
            "d=\"${XDG_STATE_HOME:-$HOME/.local/state}/ricelin\"; mkdir -p \"$d\"; printf '%s' \"$1\" > \"$d/updated\"",
            "sh", body]
    }

    Column {
        id: content
        anchors.top: parent.top
        anchors.left: parent.left
        anchors.right: parent.right
        spacing: 0

        SettingsHeader {
            s: root.s
            glyph: "更"
            title: "UPDATES"
            showBack: true
        }

        Item { width: 1; height: 14 * root.s }

        Row {
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.leftMargin: 14 * root.s
            anchors.rightMargin: 14 * root.s
            spacing: 12 * root.s

            Rectangle {
                anchors.verticalCenter: parent.verticalCenter
                width: 34 * root.s
                height: 34 * root.s
                radius: width / 2
                color: Qt.alpha(root.badgeTint, 0.16)

                GlyphIcon {
                    anchors.centerIn: parent
                    visible: !root.spinning
                    width: 17 * root.s
                    height: 17 * root.s
                    name: root.badgeIcon
                    color: root.badgeTint
                    stroke: 2.2
                }

                GlyphIcon {
                    anchors.centerIn: parent
                    visible: root.spinning
                    width: 16 * root.s
                    height: 16 * root.s
                    name: "reboot"
                    color: root.badgeTint
                    stroke: 2

                    RotationAnimation on rotation {
                        running: root.spinning
                        loops: Animation.Infinite
                        from: 0
                        to: 360
                        duration: 900
                    }
                }
            }

            Column {
                anchors.verticalCenter: parent.verticalCenter
                width: parent.width - 34 * root.s - 12 * root.s
                spacing: 3 * root.s

                Text {
                    text: root.headline
                    color: Theme.cream
                    font.family: Theme.font
                    font.pixelSize: 14.5 * root.s
                    font.weight: Font.Bold
                }

                Text {
                    width: parent.width
                    visible: root.subline.length > 0
                    text: root.subline
                    color: Theme.subtle
                    font.family: Theme.font
                    font.pixelSize: 10.5 * root.s
                    font.weight: Font.Medium
                    wrapMode: Text.WordWrap
                    lineHeight: 1.2
                    font.features: { "tnum": 1 }
                }

                Text {
                    visible: root.version.length > 0
                    text: root.behind && root.installedShort.length > 0 && root.installedShort !== root.targetShort
                        ? root.installedShort + " → " + root.targetShort
                        : root.version.replace(" ", " · ")
                    color: Theme.faint
                    font.family: Theme.font
                    font.pixelSize: 10.5 * root.s
                    font.weight: Font.Medium
                    font.features: { "tnum": 1 }
                }
            }
        }

        Item { width: 1; height: 15 * root.s }

        /**
         * The changelog is the centrepiece when an update waits: each entry is a
         * short row with a small marker, the list scrolls when it outgrows its
         * cap. Hidden in every other state so up-to-date and devmode stay calm.
         */
        Column {
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.leftMargin: 14 * root.s
            anchors.rightMargin: 14 * root.s
            spacing: 8 * root.s
            visible: root.behind

            Text {
                text: "WHAT'S NEW"
                color: Theme.faint
                font.family: Theme.font
                font.pixelSize: 9 * root.s
                font.weight: Font.Bold
                font.capitalization: Font.AllUppercase
                font.letterSpacing: 1.4 * root.s
            }

            Text {
                width: parent.width
                visible: root.changelog.length === 0
                text: "No highlights noted"
                color: Theme.dim
                font.family: Theme.font
                font.pixelSize: 11 * root.s
                font.weight: Font.Medium
                font.italic: true
            }

            ListView {
                id: logList
                width: parent.width
                height: visible ? Math.min(contentHeight, 168 * root.s) : 0
                visible: root.changelog.length > 0
                clip: true
                boundsBehavior: Flickable.StopAtBounds
                model: root.changelog

                delegate: Row {
                    required property var modelData
                    width: ListView.view.width
                    spacing: 9 * root.s
                    topPadding: 3 * root.s
                    bottomPadding: 3 * root.s

                    Rectangle {
                        anchors.top: parent.top
                        anchors.topMargin: 9 * root.s
                        width: 4 * root.s
                        height: 4 * root.s
                        radius: width / 2
                        color: Theme.vermLit
                    }

                    Text {
                        width: parent.width - 13 * root.s
                        text: parent.modelData
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 11.5 * root.s
                        font.weight: Font.Medium
                        wrapMode: Text.WordWrap
                        lineHeight: 1.2
                    }
                }

                WheelScroller {
                    anchors.fill: parent
                    s: root.s
                    flick: logList
                }
            }
        }

        Item { width: 1; height: root.behind ? 14 * root.s : 0 }

        /**
         * Conflicts: every protected file whose local edits overlap an upstream
         * change. Each lists by friendly name with a two-way choice, "Keep mine"
         * the default and "Take new" overwriting wholesale on apply.
         */
        Column {
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.leftMargin: 14 * root.s
            anchors.rightMargin: 14 * root.s
            spacing: 9 * root.s
            visible: root.conflicts.length > 0

            Text {
                width: parent.width
                text: "Your edits clash with " + root.conflicts.length + " file" + (root.conflicts.length === 1 ? "" : "s")
                color: Theme.subtle
                font.family: Theme.font
                font.pixelSize: 10.5 * root.s
                font.weight: Font.DemiBold
                wrapMode: Text.WordWrap
            }

            Repeater {
                model: root.conflicts

                Item {
                    id: confRow
                    required property var modelData
                    readonly property string rel: modelData
                    readonly property bool takeNew: root.takePaths[rel] === true

                    width: parent.width
                    height: 30 * root.s

                    Text {
                        anchors.left: parent.left
                        anchors.verticalCenter: parent.verticalCenter
                        text: root.labelFor(confRow.rel)
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 11.5 * root.s
                        font.weight: Font.DemiBold
                    }

                    Row {
                        id: choice
                        anchors.right: parent.right
                        anchors.verticalCenter: parent.verticalCenter
                        spacing: 0

                        component Seg: Rectangle {
                            id: seg
                            property string label: ""
                            property bool on: false
                            property int corner: 0
                            width: segText.implicitWidth + 18 * root.s
                            height: 24 * root.s
                            radius: 7 * root.s
                            topLeftRadius: corner === -1 ? radius : 0
                            bottomLeftRadius: corner === -1 ? radius : 0
                            topRightRadius: corner === 1 ? radius : 0
                            bottomRightRadius: corner === 1 ? radius : 0
                            color: seg.on ? Qt.alpha(Theme.vermLit, 0.20) : Theme.frameBg
                            border.width: 1
                            border.color: seg.on ? Qt.alpha(Theme.vermLit, 0.55) : Theme.hairSoft
                            Behavior on color { ColorAnimation { duration: Motion.fast } }
                            Behavior on border.color { ColorAnimation { duration: Motion.fast } }

                            Text {
                                id: segText
                                anchors.centerIn: parent
                                text: seg.label
                                color: seg.on ? Theme.bright : Theme.dim
                                font.family: Theme.font
                                font.pixelSize: 10 * root.s
                                font.weight: seg.on ? Font.DemiBold : Font.Medium
                            }
                        }

                        Seg {
                            label: "Keep mine"
                            on: !confRow.takeNew
                            corner: -1
                            MouseArea {
                                anchors.fill: parent
                                cursorShape: Qt.PointingHandCursor
                                onClicked: root.takePaths = Object.assign({}, root.takePaths, { [confRow.rel]: false })
                            }
                        }

                        Seg {
                            label: "Take new"
                            on: confRow.takeNew
                            corner: 1
                            MouseArea {
                                anchors.fill: parent
                                cursorShape: Qt.PointingHandCursor
                                onClicked: root.takePaths = Object.assign({}, root.takePaths, { [confRow.rel]: true })
                            }
                        }
                    }
                }
            }
        }

        Item { width: 1; height: root.conflicts.length > 0 ? 14 * root.s : 0 }

        /**
         * Missing packages: core packages the rice needs that aren't installed yet,
         * whether this update introduced them or they were never there. Each is a row
         * with the package label, its one-line purpose, and a toggle that defaults ON,
         * so a plain "Update now" brings the rice and its packages over together. The
         * chosen ids ride along as --install-deps and the engine batches the repo ones
         * into a single pkexec install.
         */
        Column {
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.leftMargin: 14 * root.s
            anchors.rightMargin: 14 * root.s
            spacing: 9 * root.s
            visible: root.behind && root.missingDeps.length > 0

            Text {
                width: parent.width
                text: "Needs " + root.missingDeps.length + " package" + (root.missingDeps.length === 1 ? "" : "s")
                color: Theme.subtle
                font.family: Theme.font
                font.pixelSize: 10.5 * root.s
                font.weight: Font.DemiBold
                wrapMode: Text.WordWrap
            }

            Repeater {
                model: root.missingDeps

                Item {
                    id: depRow
                    required property var modelData
                    readonly property string depId: modelData.id

                    width: parent.width
                    height: depCol.implicitHeight + 12 * root.s

                    Column {
                        id: depCol
                        anchors.left: parent.left
                        anchors.right: depToggle.left
                        anchors.rightMargin: 12 * root.s
                        anchors.verticalCenter: parent.verticalCenter
                        spacing: 2 * root.s

                        Text {
                            text: root.prettyDep(depRow.depId)
                            color: Theme.cream
                            font.family: Theme.font
                            font.pixelSize: 11.5 * root.s
                            font.weight: Font.DemiBold
                        }

                        Text {
                            width: parent.width
                            visible: depRow.modelData.desc.length > 0
                            text: depRow.modelData.desc
                            color: Theme.faint
                            font.family: Theme.font
                            font.pixelSize: 10 * root.s
                            font.weight: Font.Medium
                            wrapMode: Text.WordWrap
                            lineHeight: 1.15
                        }
                    }

                    LinkToggle {
                        id: depToggle
                        anchors.right: parent.right
                        anchors.verticalCenter: parent.verticalCenter
                        s: root.s
                        on: root.depChosen(depRow.depId)
                        onToggled: root.installDeps = Object.assign({}, root.installDeps, { [depRow.depId]: !root.depChosen(depRow.depId) })
                    }
                }
            }
        }

        Item { width: 1; height: (root.behind && root.missingDeps.length > 0) ? 14 * root.s : 0 }

        /**
         * Install failures: any chosen package the last apply couldn't bring in. The
         * engine already folds the manual command into each reason for the deps it
         * can't drive headless (AUR, fallback-only), so a row is package plus the
         * exact why. Shown until the next check, independent of the behind state, so a
         * cancelled prompt or a build that needs a terminal never reads as success.
         */
        Column {
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.leftMargin: 14 * root.s
            anchors.rightMargin: 14 * root.s
            spacing: 9 * root.s
            visible: root.depFailures.length > 0

            Text {
                width: parent.width
                text: "Couldn't install " + root.depFailures.length + " package" + (root.depFailures.length === 1 ? "" : "s")
                color: Theme.verm
                font.family: Theme.font
                font.pixelSize: 10.5 * root.s
                font.weight: Font.DemiBold
                wrapMode: Text.WordWrap
            }

            Repeater {
                model: root.depFailures

                Row {
                    id: failRow
                    required property var modelData
                    width: parent.width
                    spacing: 9 * root.s

                    Rectangle {
                        anchors.top: parent.top
                        anchors.topMargin: 6 * root.s
                        width: 4 * root.s
                        height: 4 * root.s
                        radius: width / 2
                        color: Theme.verm
                    }

                    Column {
                        width: parent.width - 13 * root.s
                        spacing: 2 * root.s

                        Text {
                            text: root.prettyDep(failRow.modelData.id)
                            color: Theme.cream
                            font.family: Theme.font
                            font.pixelSize: 11.5 * root.s
                            font.weight: Font.DemiBold
                        }

                        Text {
                            width: parent.width
                            text: failRow.modelData.error
                            color: Theme.faint
                            font.family: Theme.font
                            font.pixelSize: 10 * root.s
                            font.weight: Font.Medium
                            wrapMode: Text.WordWrap
                            lineHeight: 1.15
                        }
                    }
                }
            }
        }

        Item { width: 1; height: root.depFailures.length > 0 ? 14 * root.s : 0 }

        Rectangle {
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.leftMargin: 12 * root.s
            anchors.rightMargin: 12 * root.s
            visible: root.behind || root.statusKind !== "devmode"
            height: visible ? 1 : 0
            color: Theme.hair
        }

        Item { width: 1; height: (root.behind || root.statusKind !== "devmode") ? 15 * root.s : 0 }

        Column {
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.leftMargin: 12 * root.s
            anchors.rightMargin: 12 * root.s
            spacing: 9 * root.s

            Rectangle {
                id: updateBtn
                width: parent.width
                height: 38 * root.s
                radius: 10 * root.s
                visible: root.behind
                color: Qt.alpha(Theme.vermLit, updateHover.hovered ? 0.30 : 0.20)
                border.width: 1
                border.color: Qt.alpha(Theme.vermLit, 0.55)
                opacity: root.applying ? 0.55 : 1
                Behavior on color { ColorAnimation { duration: Motion.fast } }
                Behavior on opacity { NumberAnimation { duration: Motion.fast } }

                HoverHandler {
                    id: updateHover
                    enabled: !root.applying
                }

                MouseArea {
                    anchors.fill: parent
                    enabled: !root.applying
                    cursorShape: Qt.PointingHandCursor
                    onClicked: root.startApply()
                }

                Text {
                    anchors.centerIn: parent
                    text: root.applying ? "Updating…" : "Update now"
                    color: Theme.bright
                    font.family: Theme.font
                    font.pixelSize: 12 * root.s
                    font.weight: Font.DemiBold
                }
            }

            Rectangle {
                id: checkBtn
                width: parent.width
                height: 38 * root.s
                radius: 10 * root.s
                visible: root.statusKind !== "devmode"
                color: checkHover.hovered ? Qt.alpha(Theme.onGlow, 0.34) : Qt.alpha(Theme.onGlow, 0.20)
                border.width: 1
                border.color: Qt.alpha(Theme.onGlow, checkHover.hovered ? 0.6 : 0.4)
                opacity: root.busy ? 0.55 : 1
                Behavior on color { ColorAnimation { duration: Motion.fast } }
                Behavior on opacity { NumberAnimation { duration: Motion.fast } }

                HoverHandler {
                    id: checkHover
                    enabled: !root.busy
                }

                MouseArea {
                    anchors.fill: parent
                    enabled: !root.busy
                    cursorShape: Qt.PointingHandCursor
                    onClicked: root.startCheck()
                }

                Text {
                    anchors.centerIn: parent
                    text: root.checking ? "Checking…"
                        : root.statusKind === "offline" ? "Retry"
                        : "Check for updates"
                    color: Theme.cream
                    font.family: Theme.font
                    font.pixelSize: 12 * root.s
                    font.weight: Font.DemiBold
                }
            }

            Text {
                width: parent.width
                visible: root.restartNeeded && root.depFailures.length === 0
                text: "Updated · restarting the shell"
                color: Theme.subtle
                font.family: Theme.font
                font.pixelSize: 10.5 * root.s
                font.weight: Font.Medium
                wrapMode: Text.WordWrap
                lineHeight: 1.2
            }
        }
    }
}

pragma ComponentBehavior: Bound

import QtQuick
import QtQuick.Controls
import Quickshell
import Quickshell.Io
import "../../utils/binds.js" as Binds
import "../../utils/keychord.js" as Chord
import qs.services
import qs.modules.pill.surfaces
import qs.components.icons

/**
 * 鍵 KEYBINDS surface: a searchable list of the keyboard shortcuts parsed from
 * ~/.config/hypr/modules/binds.lua, each row a combo chip on the left and its
 * name or derived action on the right; hovering a row reveals the underlying
 * command. Tapping a row opens a unified form prefilled in EDIT mode — a
 * key-binding field that arms chord capture, a name field and a command field
 * — with Save and Delete. A dashed bar at the bottom opens the same form EMPTY
 * in ADD mode. Save folds the minimal set of binds.js calls (rebind / editCmd /
 * editName, or add) into one text and writes it; the write reloads Hyprland and
 * re-parses. A command is only editable when it is a single string literal
 * (`exec_cmd("...")`); a non-exec dispatch or an env-prefixed exec path is shown
 * read-only as the raw action so it can never be clobbered.
 *
 * The capture path mirrors the wallpaper strip's search handoff: while
 * `listening`, an Item with focus swallows every keystroke; the captured combo
 * is held in form state and only applied on Save, so a mistaken chord can be
 * retried without touching the file.
 */
PillSurface {
    id: root

    mTop: 15
    mLeft: 19
    mRight: 19
    mBottom: 14

    implicitHeight: content.implicitHeight

    signal requestSurface(string name)

    readonly property string bindsPath: Quickshell.env("HOME") + "/.config/hypr/modules/binds.lua"

    property var binds: []
    property int focusIndex: 0
    property bool listening: false
    property string conflict: ""

    property string query: ""

    property bool formOpen: false
    property bool formAdd: false
    property int formLine: -1
    property bool formCmdEditable: true
    property string formAction: ""
    property string formCombo: ""
    property string formName: ""
    property string formCmd: ""
    property string origCombo: ""
    property string origName: ""
    property string origCmd: ""
    property string origAction: ""

    /**
     * Binds whose combo, label, name or inner command contains the current query
     * as a case-insensitive substring. An empty query passes every bind through.
     */
    readonly property var filtered: {
        if (root.query.length === 0)
            return root.binds;
        var q = root.query.toLowerCase();
        return root.binds.filter(function (b) {
            return (b.combo + " " + b.label + " " + b.name + " " + b.cmd).toLowerCase().indexOf(q) !== -1;
        });
    }

    /**
     * Display form of a combo: mouse tokens are spelled out so a scroll or button
     * gesture reads clearly. These binds are shown read-only.
     */
    function comboPretty(c) {
        return c.replace("mouse_up", "Scroll ↑")
                .replace("mouse_down", "Scroll ↓")
                .replace("mouse:272", "LMB")
                .replace("mouse:273", "RMB");
    }

    function refresh() {
        root.binds = Binds.parse(bindsFile.text());
        if (root.focusIndex >= root.filtered.length)
            root.focusIndex = Math.max(0, root.filtered.length - 1);
    }

    /**
     * Slide the focused row by `dir` (+1 down, -1 up), clamped over the filtered
     * list, and keep it in view. No-op while a chord capture is live so the arrow
     * keys feed the catcher instead.
     */
    function move(dir) {
        if (root.listening || root.formOpen)
            return;
        if (root.filtered.length === 0)
            return;
        root.focusIndex = Math.max(0, Math.min(root.filtered.length - 1, root.focusIndex + dir));
        list.positionViewAtIndex(root.focusIndex, ListView.Contain);
    }

    /**
     * Open the unified form in EDIT mode for the focused row, seeding form state
     * from the bind so Save can diff against the originals.
     */
    function activate() {
        if (root.listening || root.focusIndex < 0 || root.focusIndex >= root.filtered.length)
            return;
        openEdit(root.filtered[root.focusIndex]);
    }

    function openEdit(b) {
        if (b.isMouse)
            return;
        root.conflict = "";
        root.formAdd = false;
        root.formLine = b.lineIndex;
        root.formCmdEditable = b.isExec && b.cmd.length > 0;
        root.formAction = b.action;
        root.formCombo = b.combo;
        root.formName = b.name;
        root.formCmd = b.cmd;
        root.origCombo = b.combo;
        root.origName = b.name;
        root.origCmd = b.cmd;
        root.origAction = b.action;
        root.formOpen = true;
    }

    function openAdd() {
        root.conflict = "";
        root.listening = false;
        root.formAdd = true;
        root.formLine = -1;
        root.formCmdEditable = true;
        root.formAction = "";
        root.formCombo = "";
        root.formName = "";
        root.formCmd = "";
        root.origCombo = "";
        root.origName = "";
        root.origCmd = "";
        root.origAction = "";
        root.formOpen = true;
    }

    function closeForm() {
        root.formOpen = false;
        root.listening = false;
        root.conflict = "";
    }

    /**
     * Apply a captured chord to the form state (not the file). A bare modifier is
     * ignored so capture keeps waiting for the final key; Escape ends capture.
     */
    function capture(key, modifiers) {
        if (key === Qt.Key_Escape) {
            root.listening = false;
            return;
        }
        var combo = Chord.chord(key, modifiers);
        if (combo === null)
            return;
        root.formCombo = combo;
        root.conflict = "";
        root.listening = false;
        Qt.callLater(nameField.forceActiveFocus);
    }

    /**
     * Commit the form. ADD guards the combo against an existing bind, then writes
     * one appended exec line. EDIT folds only the changed facets — combo via
     * rebind, command via editCmd, name via editName — into a single text before
     * one write. A combo that collides with another bind is refused inline.
     */
    function save() {
        var text = bindsFile.text();
        if (root.formAdd) {
            if (root.formCombo.length === 0) { root.conflict = "pick a key"; return; }
            if (root.formCmd.length === 0) { root.conflict = "command empty"; return; }
            if (Binds.inUse(text, root.formCombo, -1)) {
                root.conflict = root.formCombo + " already bound";
                return;
            }
            var a = Binds.add(text, root.formCombo, root.formCmd, root.formName);
            if (!a.ok) { root.conflict = a.error || "add failed"; return; }
            writer.setText(a.text);
            return;
        }

        if (root.formCombo !== root.origCombo && Binds.inUse(text, root.formCombo, root.formLine)) {
            root.conflict = root.formCombo + " already bound";
            return;
        }

        var out = text;
        if (root.formCombo !== root.origCombo) {
            var r = Binds.rebind(out, root.formLine, root.formCombo);
            if (!r.ok) { root.conflict = r.error || "rebind failed"; return; }
            out = r.text;
        }
        if (root.formCmdEditable && root.formCmd !== root.origCmd) {
            if (root.formCmd.length === 0) { root.conflict = "command empty"; return; }
            var c = Binds.editCmd(out, root.formLine, root.formCmd);
            if (!c.ok) { root.conflict = c.error || "command edit failed"; return; }
            out = c.text;
        }
        if (!root.formCmdEditable && root.formAction !== root.origAction) {
            if (root.formAction.trim().length === 0) { root.conflict = "action empty"; return; }
            var a2 = Binds.editAction(out, root.formLine, root.formAction.trim());
            if (!a2.ok) { root.conflict = a2.error || "action edit failed"; return; }
            out = a2.text;
        }
        if (root.formName !== root.origName) {
            var n = Binds.editName(out, root.formLine, root.formName);
            if (!n.ok) { root.conflict = n.error || "name edit failed"; return; }
            out = n.text;
        }

        if (out === text) {
            closeForm();
            return;
        }
        writer.setText(out);
    }

    function removeBind() {
        if (root.formAdd || root.formLine < 0)
            return;
        var d = Binds.del(bindsFile.text(), root.formLine);
        if (!d.ok) { root.conflict = d.error || "delete failed"; return; }
        writer.setText(d.text);
    }

    onActiveChanged: {
        if (active) {
            bindsFile.reload();
            refresh();
            focusIndex = 0;
            listening = false;
            query = "";
            formOpen = false;
            conflict = "";
        } else {
            listening = false;
            formOpen = false;
            conflict = "";
        }
    }

    onFormOpenChanged: if (formOpen) Qt.callLater(nameField.forceActiveFocus)

    readonly property Item focusRowItem: list.focusRowItem

    readonly property bool rowFocused: focusRowItem !== null && active && !formOpen

    readonly property point rowPoint: {
        void root.width;
        void root.height;
        void root.focusIndex;
        void list.contentY;
        if (!focusRowItem)
            return Qt.point(4 * root.s, root.height / 2);
        return focusRowItem.mapToItem(root, 4 * root.s, focusRowItem.height / 2);
    }

    ameForm: rowFocused ? "rowseam" : "off"
    amePoint: rowPoint

    FileView {
        id: bindsFile
        path: root.bindsPath
        blockLoading: true
        watchChanges: true
        printErrors: false
        onLoaded: root.refresh()
        onFileChanged: reload()
    }

    FileView {
        id: writer
        path: root.bindsPath
        atomicWrites: true
        printErrors: false
        onSaved: {
            reloadProc.running = true;
            root.formOpen = false;
            root.listening = false;
            root.conflict = "";
            bindsFile.reload();
            root.refresh();
        }
        onSaveFailed: (err) => {
            root.conflict = "write failed";
            console.log("keybinds: write failed: " + err);
        }
    }

    Process {
        id: reloadProc
        command: ["setsid", "-f", "sh", "-c", "sleep 0.4; hyprctl reload"]
    }

    Item {
        id: keyCatcher
        focus: root.listening
        Keys.onPressed: (e) => {
            if (!root.listening)
                return;
            e.accepted = true;
            root.capture(e.key, e.modifiers);
        }
    }

    Column {
        id: content
        anchors.top: parent.top
        anchors.left: parent.left
        anchors.right: parent.right
        spacing: 0

        Item {
            width: parent.width
            height: 22 * root.s

            Row {
                anchors.left: parent.left
                anchors.verticalCenter: parent.verticalCenter
                spacing: 8 * root.s

                Text {
                    anchors.verticalCenter: parent.verticalCenter
                    visible: Flags.showGlyphs
                    text: "鍵"
                    color: Theme.cream
                    font.family: Theme.fontJp
                    font.weight: Font.Medium
                    font.pixelSize: 16 * root.s
                }
                Text {
                    anchors.verticalCenter: parent.verticalCenter
                    text: "KEYBINDS"
                    color: Theme.subtle
                    font.family: Theme.font
                    font.pixelSize: 10 * root.s
                    font.weight: Font.DemiBold
                    font.capitalization: Font.AllUppercase
                    font.letterSpacing: 1.6 * root.s
                }
            }

            GlyphIcon {
                anchors.right: parent.right
                anchors.verticalCenter: parent.verticalCenter
                width: 16 * root.s
                height: 16 * root.s
                name: "chevron-left"
                color: Theme.iconDim
                stroke: 2.2
            }
        }

        Item { width: 1; height: 8 * root.s }

        Item {
            width: parent.width
            height: 28 * root.s
            visible: !root.formOpen

            Text {
                id: searchGlyph
                anchors.left: parent.left
                anchors.verticalCenter: parent.verticalCenter
                visible: Flags.showGlyphs
                width: Flags.showGlyphs ? implicitWidth : 0
                text: "探"
                color: Theme.dim
                font.family: Theme.fontJp
                font.weight: Font.Medium
                font.pixelSize: 15 * root.s
            }

            TextField {
                id: searchField
                anchors.left: searchGlyph.right
                anchors.leftMargin: Flags.showGlyphs ? 9 * root.s : 0
                anchors.right: parent.right
                anchors.verticalCenter: parent.verticalCenter
                background: null
                padding: 0
                color: Theme.cream
                font.family: Theme.font
                font.pixelSize: 13 * root.s
                placeholderText: "search binds"
                placeholderTextColor: Theme.faint
                selectByMouse: true
                selectionColor: Theme.verm
                onTextChanged: {
                    root.query = text;
                    root.focusIndex = 0;
                }
                Keys.onPressed: (e) => {
                    if (e.key === Qt.Key_Down) {
                        root.move(1);
                        e.accepted = true;
                    } else if (e.key === Qt.Key_Up) {
                        root.move(-1);
                        e.accepted = true;
                    } else if (e.key === Qt.Key_Return || e.key === Qt.Key_Enter) {
                        root.activate();
                        e.accepted = true;
                    }
                }
            }

            Rectangle {
                anchors.left: searchField.left
                anchors.right: searchField.right
                anchors.top: searchField.bottom
                anchors.topMargin: 3 * root.s
                height: 1
                color: Theme.faint
                opacity: searchField.activeFocus ? 0.7 : 0.18
                Behavior on opacity { NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard } }
            }
        }

        Item { width: 1; height: 8 * root.s }

        ListView {
            id: list
            width: parent.width
            height: visible ? Math.min(contentHeight, 250 * root.s) : 0
            visible: !root.formOpen
            clip: true
            boundsBehavior: Flickable.StopAtBounds
            model: root.filtered

            property Item focusRowItem: null

            delegate: Item {
                id: brow
                required property int index
                required property var modelData

                readonly property bool focused: root.focusIndex === brow.index

                width: ListView.view.width
                height: 38 * root.s

                onFocusedChanged: if (focused) list.focusRowItem = brow

                HoverHandler {
                    id: rowHover
                    onHoveredChanged: if (hovered && !root.listening) root.focusIndex = brow.index
                }

                Rectangle {
                    anchors.fill: parent
                    anchors.topMargin: 3 * root.s
                    anchors.bottomMargin: 3 * root.s
                    radius: 9 * root.s
                    color: (rowHover.hovered || brow.focused) ? Theme.frameBg : "transparent"
                    Behavior on color { ColorAnimation { duration: Motion.fast } }
                }

                Rectangle {
                    id: comboChip
                    anchors.left: parent.left
                    anchors.leftMargin: 12 * root.s
                    anchors.verticalCenter: parent.verticalCenter
                    width: comboText.implicitWidth + 16 * root.s
                    height: comboText.implicitHeight + 8 * root.s
                    radius: 7 * root.s
                    color: brow.focused ? Qt.alpha(Theme.vermLit, 0.16) : Theme.frameBg
                    border.width: 1
                    border.color: brow.focused ? Qt.alpha(Theme.vermLit, 0.45) : Theme.hairSoft
                    Behavior on color { ColorAnimation { duration: Motion.fast } }

                    Text {
                        id: comboText
                        anchors.centerIn: parent
                        text: root.comboPretty(brow.modelData.combo)
                        color: brow.focused ? Theme.cream : Theme.subtle
                        font.family: Theme.font
                        font.pixelSize: 11 * root.s
                        font.weight: Font.Bold
                        font.letterSpacing: 0.3 * root.s
                    }
                }

                Column {
                    anchors.left: comboChip.right
                    anchors.leftMargin: 12 * root.s
                    anchors.right: parent.right
                    anchors.rightMargin: 14 * root.s
                    anchors.verticalCenter: parent.verticalCenter
                    spacing: 1 * root.s

                    Text {
                        anchors.right: parent.right
                        width: parent.width
                        horizontalAlignment: Text.AlignRight
                        text: brow.modelData.label
                        color: brow.focused ? Theme.subtle : Theme.faint
                        font.family: Theme.font
                        font.pixelSize: 11 * root.s
                        font.weight: Font.Medium
                        elide: Text.ElideRight
                    }

                    Text {
                        anchors.right: parent.right
                        width: parent.width
                        horizontalAlignment: Text.AlignRight
                        visible: rowHover.hovered && brow.modelData.cmd.length > 0
                        text: brow.modelData.cmd
                        color: Theme.dim
                        font.family: Theme.font
                        font.pixelSize: 9 * root.s
                        font.weight: Font.Normal
                        elide: Text.ElideLeft
                    }
                }

                MouseArea {
                    anchors.fill: parent
                    enabled: !root.listening
                    cursorShape: brow.modelData.isMouse ? Qt.ArrowCursor : Qt.PointingHandCursor
                    onClicked: {
                        root.focusIndex = brow.index;
                        root.openEdit(brow.modelData);
                    }
                }
            }
        }

        Item {
            width: parent.width
            height: 38 * root.s
            visible: !root.formOpen

            Rectangle {
                anchors.fill: parent
                anchors.topMargin: 5 * root.s
                anchors.bottomMargin: 5 * root.s
                radius: 9 * root.s
                color: addArea.containsMouse ? Qt.alpha(Theme.vermLit, 0.1) : "transparent"
                border.width: 1
                border.color: Qt.alpha(Theme.vermLit, addArea.containsMouse ? 0.6 : 0.32)

                Row {
                    anchors.centerIn: parent
                    spacing: 6 * root.s

                    Text {
                        anchors.verticalCenter: parent.verticalCenter
                        text: "+"
                        color: Theme.vermLit
                        font.family: Theme.font
                        font.pixelSize: 14 * root.s
                        font.weight: Font.Bold
                    }
                    Text {
                        anchors.verticalCenter: parent.verticalCenter
                        text: "add keybind"
                        color: Theme.vermLit
                        font.family: Theme.font
                        font.pixelSize: 11 * root.s
                        font.weight: Font.DemiBold
                        font.letterSpacing: 0.5 * root.s
                    }
                }

                MouseArea {
                    id: addArea
                    anchors.fill: parent
                    hoverEnabled: true
                    cursorShape: Qt.PointingHandCursor
                    onClicked: root.openAdd()
                }
            }
        }

        Column {
            id: form
            width: parent.width
            visible: root.formOpen
            spacing: 10 * root.s

            Item {
                width: parent.width
                height: 22 * root.s

                Row {
                    anchors.left: parent.left
                    anchors.verticalCenter: parent.verticalCenter
                    spacing: 7 * root.s

                    Item {
                        anchors.verticalCenter: parent.verticalCenter
                        width: 16 * root.s
                        height: 16 * root.s

                        GlyphIcon {
                            anchors.fill: parent
                            name: "chevron-left"
                            color: formBackArea.containsMouse ? Theme.cream : Theme.iconDim
                            stroke: 1.8
                        }

                        MouseArea {
                            id: formBackArea
                            anchors.fill: parent
                            anchors.margins: -6 * root.s
                            hoverEnabled: true
                            cursorShape: Qt.PointingHandCursor
                            onClicked: root.closeForm()
                        }
                    }

                    Text {
                        anchors.verticalCenter: parent.verticalCenter
                        text: root.formAdd ? "NEW BIND" : "EDIT BIND"
                        color: Theme.subtle
                        font.family: Theme.font
                        font.pixelSize: 9.5 * root.s
                        font.weight: Font.DemiBold
                        font.capitalization: Font.AllUppercase
                        font.letterSpacing: 1.4 * root.s
                    }
                }
            }

            Item {
                width: parent.width
                height: 40 * root.s

                Text {
                    id: keyLabel
                    anchors.left: parent.left
                    anchors.top: parent.top
                    text: "KEY"
                    color: Theme.faint
                    font.family: Theme.font
                    font.pixelSize: 8.5 * root.s
                    font.weight: Font.Medium
                    font.capitalization: Font.AllUppercase
                    font.letterSpacing: 1 * root.s
                }

                Rectangle {
                    anchors.left: parent.left
                    anchors.right: parent.right
                    anchors.bottom: parent.bottom
                    height: 26 * root.s
                    radius: 8 * root.s
                    color: root.listening ? Qt.alpha(Theme.vermLit, 0.12) : Theme.frameBg
                    border.width: 1
                    border.color: root.listening ? Qt.alpha(Theme.vermLit, 0.55) : Theme.hairSoft
                    Behavior on color { ColorAnimation { duration: Motion.fast } }

                    Text {
                        anchors.left: parent.left
                        anchors.leftMargin: 11 * root.s
                        anchors.verticalCenter: parent.verticalCenter
                        text: root.listening ? "press keys…  esc cancels"
                            : (root.formCombo.length ? root.formCombo : "tap to set a key")
                        color: root.listening ? Theme.flameGlow
                            : (root.formCombo.length ? Theme.cream : Theme.faint)
                        font.family: Theme.font
                        font.pixelSize: 11.5 * root.s
                        font.weight: root.formCombo.length ? Font.DemiBold : Font.Medium
                        elide: Text.ElideRight
                    }

                    MouseArea {
                        anchors.fill: parent
                        cursorShape: Qt.PointingHandCursor
                        onClicked: {
                            root.conflict = "";
                            root.listening = true;
                        }
                    }
                }
            }

            Item {
                width: parent.width
                height: 40 * root.s

                Text {
                    anchors.left: parent.left
                    anchors.top: parent.top
                    text: "NAME"
                    color: Theme.faint
                    font.family: Theme.font
                    font.pixelSize: 8.5 * root.s
                    font.weight: Font.Medium
                    font.capitalization: Font.AllUppercase
                    font.letterSpacing: 1 * root.s
                }

                Rectangle {
                    anchors.left: parent.left
                    anchors.right: parent.right
                    anchors.bottom: parent.bottom
                    height: 26 * root.s
                    radius: 8 * root.s
                    color: Theme.frameBg
                    border.width: 1
                    border.color: nameField.activeFocus ? Qt.alpha(Theme.vermLit, 0.45) : Theme.hairSoft

                    TextField {
                        id: nameField
                        anchors.left: parent.left
                        anchors.leftMargin: 11 * root.s
                        anchors.right: parent.right
                        anchors.rightMargin: 11 * root.s
                        anchors.verticalCenter: parent.verticalCenter
                        background: null
                        padding: 0
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 11.5 * root.s
                        placeholderText: "label (optional)"
                        placeholderTextColor: Theme.faint
                        selectByMouse: true
                        selectionColor: Theme.verm
                        text: root.formName
                        onTextEdited: root.formName = text
                        Keys.onPressed: (e) => {
                            if (e.key === Qt.Key_Escape) { root.closeForm(); e.accepted = true; }
                            else if (e.key === Qt.Key_Return || e.key === Qt.Key_Enter) { root.save(); e.accepted = true; }
                        }
                    }
                }
            }

            Item {
                width: parent.width
                height: 40 * root.s

                Text {
                    anchors.left: parent.left
                    anchors.top: parent.top
                    text: root.formCmdEditable ? "COMMAND" : "ACTION"
                    color: Theme.faint
                    font.family: Theme.font
                    font.pixelSize: 8.5 * root.s
                    font.weight: Font.Medium
                    font.capitalization: Font.AllUppercase
                    font.letterSpacing: 1 * root.s
                }

                Rectangle {
                    anchors.left: parent.left
                    anchors.right: parent.right
                    anchors.bottom: parent.bottom
                    height: 26 * root.s
                    radius: 8 * root.s
                    color: Theme.frameBg
                    border.width: 1
                    border.color: (cmdField.activeFocus || actionField.activeFocus) ? Qt.alpha(Theme.vermLit, 0.45) : Theme.hairSoft

                    TextField {
                        id: cmdField
                        visible: root.formCmdEditable
                        anchors.left: parent.left
                        anchors.leftMargin: 11 * root.s
                        anchors.right: parent.right
                        anchors.rightMargin: 11 * root.s
                        anchors.verticalCenter: parent.verticalCenter
                        background: null
                        padding: 0
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 11.5 * root.s
                        placeholderText: "shell command"
                        placeholderTextColor: Theme.faint
                        selectByMouse: true
                        selectionColor: Theme.verm
                        text: root.formCmd
                        onTextEdited: root.formCmd = text
                        Keys.onPressed: (e) => {
                            if (e.key === Qt.Key_Escape) { root.closeForm(); e.accepted = true; }
                            else if (e.key === Qt.Key_Return || e.key === Qt.Key_Enter) { root.save(); e.accepted = true; }
                        }
                    }

                    TextField {
                        id: actionField
                        visible: !root.formCmdEditable
                        anchors.left: parent.left
                        anchors.leftMargin: 11 * root.s
                        anchors.right: parent.right
                        anchors.rightMargin: 11 * root.s
                        anchors.verticalCenter: parent.verticalCenter
                        background: null
                        padding: 0
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 10.5 * root.s
                        placeholderText: "lua dispatch"
                        placeholderTextColor: Theme.faint
                        selectByMouse: true
                        selectionColor: Theme.verm
                        text: root.formAction
                        onTextEdited: root.formAction = text
                        Keys.onPressed: (e) => {
                            if (e.key === Qt.Key_Escape) { root.closeForm(); e.accepted = true; }
                            else if (e.key === Qt.Key_Return || e.key === Qt.Key_Enter) { root.save(); e.accepted = true; }
                        }
                    }
                }
            }

            Text {
                width: parent.width
                visible: root.conflict.length > 0
                text: root.conflict
                color: Theme.vermLit
                font.family: Theme.font
                font.pixelSize: 10 * root.s
                font.weight: Font.DemiBold
                elide: Text.ElideRight
            }

            Item {
                width: parent.width
                height: 30 * root.s

                Rectangle {
                    id: deleteBtn
                    anchors.left: parent.left
                    anchors.verticalCenter: parent.verticalCenter
                    visible: !root.formAdd
                    width: deleteLabel.implicitWidth + 24 * root.s
                    height: 28 * root.s
                    radius: 8 * root.s
                    color: deleteArea.containsMouse ? Qt.alpha(Theme.verm, 0.2) : Qt.alpha(Theme.verm, 0.1)
                    border.width: 1
                    border.color: Qt.alpha(Theme.vermLit, 0.45)

                    Text {
                        id: deleteLabel
                        anchors.centerIn: parent
                        text: "Delete"
                        color: Theme.vermLit
                        font.family: Theme.font
                        font.pixelSize: 10.5 * root.s
                        font.weight: Font.DemiBold
                        font.letterSpacing: 0.3 * root.s
                    }

                    MouseArea {
                        id: deleteArea
                        anchors.fill: parent
                        hoverEnabled: true
                        cursorShape: Qt.PointingHandCursor
                        onClicked: root.removeBind()
                    }
                }

                Rectangle {
                    id: saveBtn
                    anchors.right: parent.right
                    anchors.verticalCenter: parent.verticalCenter
                    width: saveLabel.implicitWidth + 30 * root.s
                    height: 28 * root.s
                    radius: 8 * root.s
                    color: saveArea.containsMouse ? Theme.vermLit : Theme.verm

                    Text {
                        id: saveLabel
                        anchors.centerIn: parent
                        text: "Save"
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 10.5 * root.s
                        font.weight: Font.Bold
                        font.letterSpacing: 0.4 * root.s
                    }

                    MouseArea {
                        id: saveArea
                        anchors.fill: parent
                        hoverEnabled: true
                        cursorShape: Qt.PointingHandCursor
                        onClicked: root.save()
                    }
                }
            }
        }

        Item { width: 1; height: 9 * root.s }

        Rectangle {
            width: parent.width
            height: 1
            color: Theme.hairSoft
        }

        Item {
            width: parent.width
            height: 20 * root.s

            Text {
                anchors.left: parent.left
                anchors.leftMargin: 4 * root.s
                anchors.verticalCenter: parent.verticalCenter
                text: root.formOpen ? "save · delete · esc back" : "tap edit · + add · esc close"
                color: Theme.faint
                font.family: Theme.font
                font.pixelSize: 9.5 * root.s
                font.weight: Font.DemiBold
                font.capitalization: Font.AllUppercase
                font.letterSpacing: 1 * root.s
            }
        }
    }
}

pragma ComponentBehavior: Bound

import QtQuick
import Quickshell
import Quickshell.Io
import "../../utils/monitors.js" as Mon
import qs.services
import qs.modules.controlcenter
import qs.components.icons

/**
 * 画 DISPLAY sub-surface. A proportional mini-map of the monitor layout sits on
 * top: one tile per output (scaled from logical size, placed by real x/y), the
 * main monitor wears a star, clicking a tile selects it and dragging one snaps
 * it left/right/above/below the other monitor as a pending move. Below the map
 * a single card edits the selected output: resolution, refresh and scale from
 * availableModes, plus a Set as main toggle on non-main outputs.
 *
 * Apply hands mode/position/scale to display-apply.sh, which snapshots the old
 * spec, evals the new one through `hl.monitor` and arms a detached 12s watchdog
 * that reverts if the change is not confirmed — so a mode that blanks the
 * screen heals itself even if the pill dies. A confirmed Keep clears the
 * watchdog and persists by rewriting only that output's block in monitors.lua.
 * A main swap needs no revert: on Apply it exchanges the two workspace_rule
 * loops' monitors in monitors.lua (ground truth for who is main: the loop that
 * carries workspace 1) and marks the output primary for XWayland via xrandr.
 *
 * monitors.lua is held as in-memory text after the first read and every rewrite
 * goes through it, so a main swap and a later Keep in the same session never
 * clobber each other through a stale FileView cache. The card rows join the
 * surface row registry, so hover, the soul seam and keyboard focus behave like
 * the other settings surfaces.
 */
SettingsSurface {
    id: root

    backSurface: "settings"
    implicitHeight: content.implicitHeight

    readonly property string monitorsPath: Quickshell.env("HOME") + "/.config/hypr/modules/monitors.lua"
    readonly property string helper: Quickshell.env("HOME") + "/.config/hypr/scripts/display-apply.sh"

    property var monitors: []
    property string pendingOut: ""
    property string openPicker: ""
    property int countdown: 0
    property string note: ""
    property bool quietRead: false

    property string selName: ""
    property string mainName: ""
    property string luaText: ""

    /** Pending arrangement from a map drag: `{ name, side }`, or null. */
    property var pendingMove: null

    readonly property var selMon: monitorByName(selName)
    readonly property bool selIsMain: selMon !== null && selMon.name === mainName

    readonly property var scaleOptions: [
        { label: "1.0", value: 1 },
        { label: "1.25", value: 1.25 },
        { label: "1.5", value: 1.5 },
        { label: "2.0", value: 2 }
    ]

    onActiveChanged: {
        if (active) {
            cancelCountdown();
            readProc.running = true;
        } else {
            cancelCountdown();
            openPicker = "";
            focusRowItem = null;
            kbIndex = -1;
        }
    }

    onSelMonChanged: if (selMon) card.syncToCurrent()

    rows: {
        void root.selMon;
        void root.mainName;
        var e = [
            { item: resRow, kind: "scrub", bump: function (d) { card.bumpRes(d); } },
            { item: rateRow, kind: "scrub", bump: function (d) { card.bumpRate(d); } },
            { item: scaleRow, kind: "seg", vals: root.scaleOptions.map(function (o) { return o.value; }), get: function () { return card.pickScale; }, set: function (v) { card.pickScale = v; } }
        ];
        if (root.selMon && !root.selIsMain)
            e.push({ item: mainRow, kind: "toggle", get: function () { return card.pendingMain; }, set: function (v) { card.pendingMain = v; } });
        return e;
    }

    /**
     * Reduces a monitor's parsed modes to the list of distinct WxH, each carrying
     * the descending list of whole-number Hz offered for that resolution. The
     * native (current width/height) resolution sorts first, then the rest by
     * pixel count descending, so the default selection lands on the panel's real
     * mode.
     */
    function resolutionsFor(mon) {
        var byRes = {};
        for (var i = 0; i < mon.modes.length; i++) {
            var m = mon.modes[i];
            var key = m.w + "x" + m.h;
            if (!byRes[key])
                byRes[key] = { w: m.w, h: m.h, key: key, rates: [] };
            if (byRes[key].rates.indexOf(m.hz) === -1)
                byRes[key].rates.push(m.hz);
        }
        var list = [];
        for (var k in byRes) {
            byRes[k].rates.sort(function (a, b) { return b - a; });
            list.push(byRes[k]);
        }
        list.sort(function (a, b) {
            if (a.w === mon.width && a.h === mon.height) return -1;
            if (b.w === mon.width && b.h === mon.height) return 1;
            return (b.w * b.h) - (a.w * a.h);
        });
        return list;
    }

    function monitorByName(name) {
        for (var i = 0; i < monitors.length; i++)
            if (monitors[i].name === name)
                return monitors[i];
        return null;
    }

    /** The first monitor that is not `name`; the anchor for placement moves. */
    function otherMonitor(name) {
        for (var i = 0; i < monitors.length; i++)
            if (monitors[i].name !== name)
                return monitors[i];
        return null;
    }

    /**
     * Logical x/y of a monitor of `myW`x`myH` placed on `side` of `other`, top
     * or left edge aligned with the anchor. Negative coordinates are fine for
     * Hyprland, so left/above of an origin monitor need no re-anchoring.
     */
    function placementXY(other, side, myW, myH) {
        var oW = Math.round(other.width / other.scale);
        var oH = Math.round(other.height / other.scale);
        if (side === "left")
            return { x: other.x - myW, y: other.y };
        if (side === "above")
            return { x: other.x, y: other.y - myH };
        if (side === "below")
            return { x: other.x, y: other.y + oH };
        return { x: other.x + oW, y: other.y };
    }

    /** The pending-move x/y for `mon` using the card's current size picks, or null. */
    function pendingXY(mon) {
        if (!pendingMove || pendingMove.name !== mon.name)
            return null;
        var other = otherMonitor(mon.name);
        if (!other || card.resolutions.length === 0)
            return null;
        var res = card.resolutions[Math.min(card.resIndex, card.resolutions.length - 1)];
        return placementXY(other, pendingMove.side,
            Math.round(res.w / card.pickScale), Math.round(res.h / card.pickScale));
    }

    /**
     * A dropped tile snaps to whichever side of the other monitor its centre
     * ended on, judged in tile-normalised offsets so flat and tall layouts bias
     * the same. A drop that lands the monitor back on its current x/y clears
     * the pending move instead of arming a no-op.
     */
    function dropTile(name, cx, cy) {
        var mon = monitorByName(name);
        var other = otherMonitor(name);
        if (!mon || !other)
            return;
        var oT = null;
        var tiles = mapLayout.tiles;
        for (var i = 0; i < tiles.length; i++)
            if (tiles[i].name !== name) { oT = tiles[i]; break; }
        if (!oT)
            return;
        var nx = (cx - (oT.x + oT.w / 2)) / oT.w;
        var ny = (cy - (oT.y + oT.h / 2)) / oT.h;
        var side = Math.abs(nx) >= Math.abs(ny) ? (nx < 0 ? "left" : "right") : (ny < 0 ? "above" : "below");
        var res = card.resolutions.length > 0 ? card.resolutions[Math.min(card.resIndex, card.resolutions.length - 1)] : null;
        var myW = res ? Math.round(res.w / card.pickScale) : Math.round(mon.width / mon.scale);
        var myH = res ? Math.round(res.h / card.pickScale) : Math.round(mon.height / mon.scale);
        var p = placementXY(other, side, myW, myH);
        pendingMove = (p.x === mon.x && p.y === mon.y) ? null : { name: name, side: side };
    }

    /**
     * Scaled tile geometry for the mini-map: logical rects (mode over scale,
     * pending move substituted for its monitor) fitted into the map width and a
     * capped height, centred horizontally. Selection and main state stay out of
     * the entries on purpose — they are read per-tile from root, so clicking a
     * tile never rebuilds the Repeater under an active press.
     */
    readonly property var mapLayout: {
        var mons = root.monitors;
        if (mons.length === 0 || mapBox.width <= 0)
            return { h: 0, tiles: [] };
        var rects = [];
        var minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
        for (var i = 0; i < mons.length; i++) {
            var m = mons[i];
            var r = { name: m.name, hz: m.refresh, x: m.x, y: m.y, w: Math.round(m.width / m.scale), h: Math.round(m.height / m.scale) };
            var p = root.pendingXY(m);
            if (p) {
                var res = card.resolutions[Math.min(card.resIndex, card.resolutions.length - 1)];
                r.x = p.x;
                r.y = p.y;
                r.w = Math.round(res.w / card.pickScale);
                r.h = Math.round(res.h / card.pickScale);
            }
            rects.push(r);
            minX = Math.min(minX, r.x);
            minY = Math.min(minY, r.y);
            maxX = Math.max(maxX, r.x + r.w);
            maxY = Math.max(maxY, r.y + r.h);
        }
        var k = Math.min(mapBox.width / (maxX - minX), (96 * root.s) / (maxY - minY));
        var ox = (mapBox.width - (maxX - minX) * k) / 2;
        var tiles = rects.map(function (t) {
            return { name: t.name, hz: t.hz, x: ox + (t.x - minX) * k, y: (t.y - minY) * k, w: t.w * k, h: t.h * k };
        });
        return { h: (maxY - minY) * k, tiles: tiles };
    }

    /**
     * monitors.lua as in-memory text: read once, then every rewrite updates it
     * before hitting disk, so back-to-back edits never read a stale file cache.
     */
    function luaNow() {
        if (luaText.length === 0)
            luaText = monitorsFile.text();
        return luaText;
    }

    /** The main monitor is whichever one the workspace-1 rule loop points at. */
    function mainFromLua(text) {
        var re = /for\s+i\s*=\s*(\d+)\s*,\s*(\d+)\s+do\s*\n\s*hl\.workspace_rule\(\{[^}]*monitor\s*=\s*"([^"]+)"/g;
        var m;
        while ((m = re.exec(text)) !== null)
            if (parseInt(m[1], 10) <= 1 && parseInt(m[2], 10) >= 1)
                return m[3];
        return "";
    }

    /**
     * Swaps the monitor names between the two workspace_rule loops, leaving
     * every other byte of the file untouched (loop style, ranges, whitespace).
     * The later name is replaced first so the earlier offset stays valid.
     */
    function swapWorkspaceLoops(text) {
        var re = /(for\s+i\s*=\s*\d+\s*,\s*\d+\s+do\s*\n\s*hl\.workspace_rule\(\{[^}]*monitor\s*=\s*")([^"]+)"/g;
        var hits = [];
        var m;
        while ((m = re.exec(text)) !== null)
            hits.push({ start: m.index + m[1].length, name: m[2] });
        if (hits.length !== 2)
            return { ok: false, text: text };
        var a = hits[0];
        var b = hits[1];
        return { ok: true, text: text.slice(0, a.start) + b.name
            + text.slice(a.start + a.name.length, b.start) + a.name
            + text.slice(b.start + b.name.length) };
    }

    Process {
        id: readProc
        command: ["hyprctl", "monitors", "-j"]
        stdout: StdioCollector {
            onStreamFinished: {
                root.monitors = Mon.parse(this.text);
                root.mainName = root.mainFromLua(root.luaNow());
                if (!root.monitorByName(root.selName)) {
                    var main = root.monitorByName(root.mainName);
                    root.selName = main ? main.name : (root.monitors.length > 0 ? root.monitors[0].name : "");
                }
                if (!root.quietRead)
                    root.note = "Changes apply live, no reload. If a mode looks wrong, it reverts on its own after 12s.";
                root.quietRead = false;
            }
        }
    }

    Process {
        id: applyProc
        property string out: ""
        property string mode: ""
        property string position: ""
        property real scale: 1
        command: ["sh", "-c",
            "sh \"$1\" apply \"$2\" \"$3\" \"$4\" \"$5\"",
            "sh", root.helper, out, mode, position, String(scale)]
        onExited: root.startCountdown()
    }

    Process {
        id: keepProc
        property string out: ""
        command: ["sh", "-c", "sh \"$1\" keep \"$2\"", "sh", root.helper, out]
    }

    /** XWayland primary flag; runs only when a main swap is applied. */
    Process {
        id: xrandrProc
        property string out: ""
        command: ["xrandr", "--output", out, "--primary"]
    }

    /**
     * Applies whatever is pending on the selected monitor. A main swap persists
     * at once (it is not a mode change, nothing to revert); mode, scale or a
     * dragged move go to the helper's apply verb and its 12s watchdog. Only
     * availableModes Hz reach the mode string, so an unsupported mode can never
     * be requested.
     */
    function apply() {
        var mon = root.selMon;
        if (!mon || root.pendingOut.length > 0)
            return;
        if (card.pendingMain && !root.selIsMain)
            applyMainSwap(mon.name);
        if (!card.dirty)
            return;
        var res = card.resolutions[Math.min(card.resIndex, card.resolutions.length - 1)];
        var hz = res.rates[Math.min(card.rateIndex, res.rates.length - 1)];
        var p = pendingXY(mon);
        applyProc.out = mon.name;
        applyProc.mode = res.w + "x" + res.h + "@" + hz;
        applyProc.position = p ? p.x + "x" + p.y : mon.x + "x" + mon.y;
        applyProc.scale = card.pickScale;
        root.pendingOut = mon.name;
        applyProc.running = true;
    }

    function applyMainSwap(name) {
        var res = swapWorkspaceLoops(luaNow());
        card.pendingMain = false;
        if (!res.ok) {
            note = "Could not rewrite the workspace rules in monitors.lua.";
            return;
        }
        luaText = res.text;
        writer.setText(res.text);
        mainName = mainFromLua(res.text);
        xrandrProc.out = name;
        xrandrProc.running = true;
        if (!card.dirty)
            note = "Saved. " + name + " is the main monitor now.";
    }

    function startCountdown() {
        root.countdown = 12;
        countTimer.start();
    }

    /**
     * Confirm the pending change: clear the helper's watchdog so it will not
     * revert, persist by rewriting that output's block in monitors.lua, then
     * quietly re-read the live layout so the map lands on ground truth.
     */
    function keep() {
        if (root.pendingOut.length === 0)
            return;
        keepProc.out = root.pendingOut;
        keepProc.running = true;
        var res = Mon.setMonitor(luaNow(), applyProc.out, applyProc.mode, applyProc.position, applyProc.scale);
        if (res.ok) {
            luaText = res.text;
            writer.setText(res.text);
        }
        cancelCountdown();
        root.quietRead = true;
        readProc.running = true;
        root.note = "Saved. " + applyProc.out + " set to " + applyProc.mode + " · scale " + applyProc.scale;
    }

    /**
     * Stop the countdown and forget the pending output. Called on Keep, on the
     * watchdog-driven timeout (the helper has already reverted the live mode), and
     * when the surface closes.
     */
    function cancelCountdown() {
        countTimer.stop();
        root.countdown = 0;
        root.pendingOut = "";
    }

    Timer {
        id: countTimer
        interval: 1000
        repeat: true
        onTriggered: {
            root.countdown -= 1;
            if (root.countdown <= 0) {
                root.cancelCountdown();
                root.quietRead = true;
                readProc.running = true;
                root.note = "Reverted — the change was not confirmed in time.";
            }
        }
    }

    FileView {
        id: monitorsFile
        path: root.monitorsPath
        blockLoading: true
        printErrors: false
    }

    FileView {
        id: writer
        path: root.monitorsPath
        atomicWrites: true
        printErrors: false
        onSaveFailed: (err) => {
            root.note = "Live mode kept, but writing monitors.lua failed.";
            console.log("display: write failed: " + err);
        }
    }

    /**
     * One registry row inside the monitor card: a leading line icon (or a text
     * glyph for the star), the shared hover/focus treatment, and hover and
     * clicks routed through reportRowHover/activateRow so the soul seam and
     * keyboard focus track these rows like SettingsRow lines. The highlight
     * hugs only the head line, so an open dropdown grows past it.
     */
    component CardRow: Item {
        id: crow

        property string icon: ""
        property string glyphText: ""
        default property alias content: crowInner.data

        readonly property bool focused: root.focusRowItem === crow

        width: parent ? parent.width : 0
        implicitHeight: crowInner.childrenRect.height

        HoverHandler {
            id: crowHover
            onHoveredChanged: root.reportRowHover(crow, hovered)
        }

        Rectangle {
            anchors.top: parent.top
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.topMargin: -3 * root.s
            anchors.leftMargin: -7 * root.s
            anchors.rightMargin: -7 * root.s
            height: 32 * root.s
            radius: 8 * root.s
            color: (crowHover.hovered || crow.focused) ? Theme.frameBg : "transparent"
            Behavior on color { ColorAnimation { duration: Motion.fast } }
        }

        MouseArea {
            anchors.fill: parent
            cursorShape: Qt.PointingHandCursor
            onClicked: root.activateRow(crow)
        }

        GlyphIcon {
            id: crowIcon
            anchors.left: parent.left
            anchors.top: parent.top
            anchors.topMargin: 5 * root.s
            width: 16 * root.s
            height: 16 * root.s
            name: crow.icon
            visible: crow.icon.length > 0
            color: crow.focused ? Theme.cream : Theme.subtle
            stroke: 1.8
        }

        Text {
            anchors.centerIn: crowIcon
            visible: crow.glyphText.length > 0
            text: crow.glyphText
            color: crow.focused ? Theme.cream : Theme.subtle
            font.family: Theme.fontJp
            font.pixelSize: 13 * root.s
        }

        Item {
            id: crowInner
            anchors.left: crowIcon.right
            anchors.leftMargin: 9 * root.s
            anchors.right: parent.right
            anchors.top: parent.top
            height: childrenRect.height
        }
    }

    Column {
        id: content
        z: 100
        anchors.top: parent.top
        anchors.left: parent.left
        anchors.right: parent.right
        spacing: 0
        height: root.height + root.mBottom * root.s
        clip: true

        SettingsHeader {
            s: root.s
            glyph: "画"
            title: "DISPLAY"
            showBack: true
        }

        Item { width: 1; height: 12 * root.s }

        Column {
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.leftMargin: 12 * root.s
            anchors.rightMargin: 12 * root.s
            spacing: 12 * root.s

            Item {
                id: mapBox
                width: parent.width
                height: root.mapLayout.h
                Behavior on height { NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard } }

                Repeater {
                    model: root.mapLayout.tiles

                    Rectangle {
                        id: tile
                        required property var modelData

                        readonly property bool sel: tile.modelData.name === root.selName
                        readonly property bool isMain: tile.modelData.name === root.mainName
                        readonly property bool moved: root.pendingMove !== null && root.pendingMove.name === tile.modelData.name
                        property real dx: 0
                        property real dy: 0

                        x: tile.modelData.x + 1.5 * root.s + dx
                        y: tile.modelData.y + 1.5 * root.s + dy
                        width: Math.max(2, tile.modelData.w - 3 * root.s)
                        height: Math.max(2, tile.modelData.h - 3 * root.s)
                        z: tileMA.pressed ? 10 : (tile.sel ? 5 : 0)
                        radius: 7 * root.s
                        color: tile.sel ? Qt.alpha(Theme.onGlow, 0.13) : Theme.cardTop
                        border.width: 1
                        border.color: tile.moved ? Qt.alpha(Theme.vermLit, 0.7) : (tile.sel ? Theme.cream : Theme.hairSoft)

                        Behavior on x { enabled: !tileMA.pressed; NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard } }
                        Behavior on y { enabled: !tileMA.pressed; NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard } }
                        Behavior on color { ColorAnimation { duration: Motion.fast } }
                        Behavior on border.color { ColorAnimation { duration: Motion.fast } }

                        Column {
                            anchors.centerIn: parent
                            spacing: 2 * root.s

                            Text {
                                anchors.horizontalCenter: parent.horizontalCenter
                                text: tile.modelData.name
                                color: tile.sel ? Theme.cream : Theme.subtle
                                font.family: Theme.font
                                font.pixelSize: 10 * root.s
                                font.weight: Font.DemiBold
                            }
                            Text {
                                anchors.horizontalCenter: parent.horizontalCenter
                                text: tile.modelData.hz + "Hz"
                                color: Theme.faint
                                font.family: Theme.font
                                font.pixelSize: 8.5 * root.s
                                font.weight: Font.Medium
                                font.features: { "tnum": 1 }
                            }
                        }

                        Text {
                            anchors.top: parent.top
                            anchors.right: parent.right
                            anchors.topMargin: 3 * root.s
                            anchors.rightMargin: 5 * root.s
                            visible: tile.isMain
                            text: "★"
                            color: Theme.vermLit
                            font.family: Theme.fontJp
                            font.pixelSize: 9.5 * root.s
                        }

                        /**
                         * Manual drag: local deltas accumulate onto the layout
                         * position, so the binding keeps owning x/y and the snap
                         * animation plays the moment the deltas reset on release.
                         */
                        MouseArea {
                            id: tileMA
                            anchors.fill: parent
                            hoverEnabled: true
                            cursorShape: pressed ? Qt.ClosedHandCursor : (root.monitors.length >= 2 ? Qt.OpenHandCursor : Qt.PointingHandCursor)
                            property real sx: 0
                            property real sy: 0
                            onPressed: (mouse) => {
                                if (root.pendingOut.length === 0)
                                    root.selName = tile.modelData.name;
                                sx = mouse.x;
                                sy = mouse.y;
                            }
                            onPositionChanged: (mouse) => {
                                if (!pressed || root.monitors.length < 2 || root.pendingOut.length > 0)
                                    return;
                                tile.dx += mouse.x - sx;
                                tile.dy += mouse.y - sy;
                            }
                            onReleased: {
                                if (tile.dx !== 0 || tile.dy !== 0)
                                    root.dropTile(tile.modelData.name, tile.x + tile.width / 2, tile.y + tile.height / 2);
                                tile.dx = 0;
                                tile.dy = 0;
                            }
                        }
                    }
                }
            }

            Rectangle {
                id: card
                visible: root.selMon !== null
                width: parent.width
                radius: Motion.rTile * root.s
                color: Theme.cardTop
                border.width: 1
                border.color: card.pending ? Qt.alpha(Theme.vermLit, 0.55) : Theme.hairSoft
                implicitHeight: cardCol.implicitHeight + 22 * root.s
                Behavior on border.color { ColorAnimation { duration: Motion.fast } }

                property int resIndex: 0
                property int rateIndex: 0
                property real pickScale: 1
                property bool pendingMain: false

                readonly property var resolutions: root.selMon ? root.resolutionsFor(root.selMon) : []
                readonly property var rates: resolutions.length > 0 ? resolutions[Math.min(resIndex, resolutions.length - 1)].rates : []
                readonly property bool pending: root.selMon !== null && root.pendingOut === root.selMon.name

                /** Anything the helper flow would change: mode, scale or a dragged move. */
                readonly property bool dirty: {
                    var mon = root.selMon;
                    if (!mon || card.resolutions.length === 0)
                        return false;
                    var res = card.resolutions[Math.min(card.resIndex, card.resolutions.length - 1)];
                    var hz = res.rates[Math.min(card.rateIndex, res.rates.length - 1)];
                    if (res.w !== mon.width || res.h !== mon.height || hz !== mon.refresh)
                        return true;
                    if (card.pickScale !== mon.scale)
                        return true;
                    var p = root.pendingXY(mon);
                    return p !== null && (p.x !== mon.x || p.y !== mon.y);
                }
                readonly property bool applyReady: dirty || (pendingMain && !root.selIsMain)

                /**
                 * Seed the pickers from the selected monitor's live mode: the
                 * resolution whose WxH matches the current width/height, then the
                 * Hz nearest the current refresh within that resolution. Switching
                 * selection lands here too, dropping any un-applied edits.
                 */
                /**
                 * Seeds from locally computed lists, never from `card.rates`: inside
                 * onSelMonChanged the dependent bindings can still hold the previous
                 * monitor's values (handler order vs binding invalidation), which
                 * seeded HDMI's rate index against DP-1's rate list.
                 */
                function syncToCurrent() {
                    var mon = root.selMon;
                    if (!mon)
                        return;
                    var resos = root.resolutionsFor(mon);
                    var ri = 0;
                    for (var i = 0; i < resos.length; i++) {
                        if (resos[i].w === mon.width && resos[i].h === mon.height) {
                            ri = i;
                            break;
                        }
                    }
                    card.resIndex = ri;
                    card.rateIndex = card.nearestIn(resos.length > 0 ? resos[ri].rates : [], mon.refresh);
                    card.pickScale = mon.scale;
                    card.pendingMain = false;
                    if (root.pendingMove)
                        root.pendingMove = null;
                    root.openPicker = "";
                }

                function nearestIn(rates, hz) {
                    var best = 0;
                    var bestDiff = 1e9;
                    for (var i = 0; i < rates.length; i++) {
                        var d = Math.abs(rates[i] - hz);
                        if (d < bestDiff) { bestDiff = d; best = i; }
                    }
                    return best;
                }

                function nearestRateIndex(hz) {
                    return nearestIn(card.rates, hz);
                }

                function bumpRes(d) {
                    var i = Math.max(0, Math.min(card.resolutions.length - 1, card.resIndex + d));
                    if (i === card.resIndex)
                        return;
                    card.resIndex = i;
                    card.rateIndex = card.nearestRateIndex(card.rates.length > 0 ? card.rates[0] : 60);
                }

                function bumpRate(d) {
                    var cur = Math.min(card.rateIndex, Math.max(0, card.rates.length - 1));
                    card.rateIndex = Math.max(0, Math.min(card.rates.length - 1, cur + d));
                }

                Column {
                    id: cardCol
                    anchors.left: parent.left
                    anchors.right: parent.right
                    anchors.top: parent.top
                    anchors.leftMargin: 13 * root.s
                    anchors.rightMargin: 13 * root.s
                    anchors.topMargin: 11 * root.s
                    spacing: 9 * root.s

                    Text {
                        text: root.selMon ? root.selMon.name + (root.selIsMain ? "  ·  Main" : "") : ""
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 12.5 * root.s
                        font.weight: Font.Bold
                        font.letterSpacing: 0.3 * root.s
                    }

                    CardRow {
                        id: resRow
                        icon: "monitor"

                        DisplayPicker {
                            width: parent.width
                            s: root.s
                            label: "Resolution"
                            options: card.resolutions.map(function (r, i) { return { label: r.w + "×" + r.h, value: i }; })
                            value: card.resIndex
                            open: root.openPicker === root.selName + ":res"
                            onRequestToggle: root.openPicker = (root.openPicker === root.selName + ":res" ? "" : root.selName + ":res")
                            onPicked: (v) => {
                                card.resIndex = v;
                                card.rateIndex = card.nearestRateIndex(card.rates.length > 0 ? card.rates[0] : 60);
                                root.openPicker = "";
                            }
                        }
                    }

                    CardRow {
                        id: rateRow
                        icon: "reboot"

                        DisplayPicker {
                            width: parent.width
                            s: root.s
                            label: "Refresh"
                            options: card.rates.map(function (hz, i) { return { label: hz + "Hz", value: i }; })
                            value: Math.min(card.rateIndex, Math.max(0, card.rates.length - 1))
                            open: root.openPicker === root.selName + ":rate"
                            onRequestToggle: root.openPicker = (root.openPicker === root.selName + ":rate" ? "" : root.selName + ":rate")
                            onPicked: (v) => {
                                card.rateIndex = v;
                                root.openPicker = "";
                            }
                        }
                    }

                    CardRow {
                        id: scaleRow
                        icon: "scaling"

                        Row {
                            width: parent.width
                            spacing: 8 * root.s

                            Text {
                                anchors.verticalCenter: parent.verticalCenter
                                width: 64 * root.s
                                text: "Scale"
                                color: Theme.faint
                                font.family: Theme.font
                                font.pixelSize: 10.5 * root.s
                                font.weight: Font.Medium
                            }

                            SettingsSeg {
                                anchors.verticalCenter: parent.verticalCenter
                                s: root.s
                                options: root.scaleOptions
                                value: card.pickScale
                                onPicked: (v) => card.pickScale = v
                            }
                        }
                    }

                    CardRow {
                        id: mainRow
                        glyphText: "★"
                        visible: root.selMon !== null && !root.selIsMain

                        Item {
                            width: parent.width
                            height: 26 * root.s

                            Text {
                                anchors.left: parent.left
                                anchors.verticalCenter: parent.verticalCenter
                                text: "Set as main"
                                color: Theme.cream
                                font.family: Theme.font
                                font.pixelSize: 11 * root.s
                                font.weight: Font.DemiBold
                            }

                            LinkToggle {
                                anchors.right: parent.right
                                anchors.verticalCenter: parent.verticalCenter
                                s: root.s
                                on: card.pendingMain
                                onToggled: card.pendingMain = !card.pendingMain
                            }
                        }
                    }

                    Item {
                        width: parent.width
                        height: 30 * root.s

                        Rectangle {
                            id: applyBtn
                            anchors.left: parent.left
                            anchors.verticalCenter: parent.verticalCenter
                            visible: !card.pending && root.pendingOut.length === 0
                            width: applyLabel.implicitWidth + 28 * root.s
                            height: 28 * root.s
                            radius: 9 * root.s
                            color: !card.applyReady ? Qt.alpha(Theme.onGlow, 0.10)
                                : (applyArea.containsMouse ? Qt.alpha(Theme.onGlow, 0.34) : Qt.alpha(Theme.onGlow, 0.20))
                            border.width: 1
                            border.color: Qt.alpha(Theme.onGlow, !card.applyReady ? 0.22 : (applyArea.containsMouse ? 0.6 : 0.4))
                            Behavior on color { ColorAnimation { duration: Motion.fast } }
                            Behavior on border.color { ColorAnimation { duration: Motion.fast } }

                            Text {
                                id: applyLabel
                                anchors.centerIn: parent
                                text: "Apply"
                                color: card.applyReady ? Theme.cream : Theme.faint
                                font.family: Theme.font
                                font.pixelSize: 10.5 * root.s
                                font.weight: Font.DemiBold
                                font.letterSpacing: 0.3 * root.s
                            }

                            MouseArea {
                                id: applyArea
                                anchors.fill: parent
                                hoverEnabled: true
                                cursorShape: card.applyReady ? Qt.PointingHandCursor : Qt.ArrowCursor
                                onClicked: if (card.applyReady) root.apply()
                            }
                        }

                        Row {
                            anchors.left: parent.left
                            anchors.right: parent.right
                            anchors.verticalCenter: parent.verticalCenter
                            visible: card.pending
                            spacing: 9 * root.s

                            Rectangle {
                                id: keepBtn
                                anchors.verticalCenter: parent.verticalCenter
                                width: keepLabel.implicitWidth + 28 * root.s
                                height: 28 * root.s
                                radius: 9 * root.s
                                color: keepArea.containsMouse ? Theme.vermLit : Theme.verm
                                Behavior on color { ColorAnimation { duration: Motion.fast } }

                                Text {
                                    id: keepLabel
                                    anchors.centerIn: parent
                                    text: "Keep (" + root.countdown + ")"
                                    color: Theme.cream
                                    font.family: Theme.font
                                    font.pixelSize: 10.5 * root.s
                                    font.weight: Font.Bold
                                    font.letterSpacing: 0.3 * root.s
                                }

                                MouseArea {
                                    id: keepArea
                                    anchors.fill: parent
                                    hoverEnabled: true
                                    cursorShape: Qt.PointingHandCursor
                                    onClicked: root.keep()
                                }
                            }

                            Text {
                                anchors.verticalCenter: parent.verticalCenter
                                text: "reverts automatically if not kept"
                                color: Theme.faint
                                font.family: Theme.font
                                font.pixelSize: 9.5 * root.s
                                font.weight: Font.Medium
                            }
                        }
                    }
                }
            }

            Text {
                width: parent.width
                visible: root.note.length > 0
                text: root.note
                color: Theme.subtle
                font.family: Theme.font
                font.pixelSize: 10 * root.s
                font.weight: Font.Medium
                wrapMode: Text.WordWrap
                lineHeight: 1.25
            }
        }

        Item { width: 1; height: 4 * root.s }
    }

    MouseArea {
        anchors.fill: parent
        enabled: root.pendingOut.length > 0
        z: 50
        onClicked: {}
    }
}

pragma ComponentBehavior: Bound

import QtQuick
import Quickshell
import Quickshell.Io
import "../../utils/setInput.js" as SetInput
import qs.services
import qs.modules.controlcenter
import qs.components.icons
import qs.components.controls

/**
 * 操 INPUT sub-surface: edits the pointer, keyboard and cursor settings that live
 * in the Hyprland Lua modules, writing each change straight back to its source so
 * the choice survives a restart. Pointer and keyboard fields rewrite input.lua
 * and reload Hyprland; the layout row cycles a curated list of common layouts.
 * Cursor size and theme apply live through `hyprctl setcursor` with no reload,
 * and persist by rewriting the XCURSOR/HYPRCURSOR env lines and the autostart
 * setcursor call. The theme list is scanned from the installed icon themes that
 * carry a `cursors/` folder. Reached from the settings index; morphs back on the
 * back chevron.
 */
SettingsSurface {
    id: root

    backSurface: "settings"
    implicitHeight: content.implicitHeight

    /**
     * Row registry; scrub rows expose a bump that steps their ScrubValue one
     * increment. The layout row's vals gain the current layout at the end when it
     * is not in the curated list, so an exotic layout shows as-is and a click
     * wraps around to the start of the list.
     */
    rows: [
        { item: sensRow, kind: "scrub", bump: function (d) { sensScrub.bump(d); } },
        { item: accelRow, kind: "seg", vals: ["flat", "adaptive"], get: function () { return root.accelProfile; }, set: function (v) { root.accelProfile = v; root.writeInputField("accel_profile", "\"" + v + "\""); } },
        { item: layoutRow, kind: "seg", vals: root.kbLayoutVals, get: function () { return root.kbLayout; }, set: function (v) { root.setKbLayout(v); } },
        { item: rateRow, kind: "scrub", bump: function (d) { rateScrub.bump(d); } },
        { item: delayRow, kind: "scrub", bump: function (d) { delayScrub.bump(d); } },
        { item: numlockRow, kind: "toggle", get: function () { return root.numlockOn; }, set: function (v) { root.numlockOn = v; root.writeInputField("numlock_by_default", v ? "true" : "false"); } },
        { item: sizeRow, kind: "scrub", bump: function (d) { sizeScrub.bump(d); } },
        { item: themeRow, kind: "toggle", get: function () { return root.themeOpen; }, set: function (v) { root.themeOpen = v; } }
    ]

    property string note: ""

    readonly property string inputPath: Quickshell.env("HOME") + "/.config/hypr/modules/input.lua"
    readonly property string envPath: Quickshell.env("HOME") + "/.config/hypr/modules/env.lua"
    readonly property string autostartPath: Quickshell.env("HOME") + "/.config/hypr/modules/autostart.lua"

    property real sensitivity: 0
    property string accelProfile: "flat"
    property string kbLayout: "de"
    property int repeatRate: 25
    property int repeatDelay: 600
    property bool numlockOn: false
    property int cursorSize: 24
    property string cursorTheme: "Bibata-Modern-Ice"
    property var cursorThemes: []
    property bool themeOpen: false

    property string inputText: ""
    property string envText: ""
    property string autostartText: ""

    /** Per-field values captured on each open; the ScrubValue undo glyphs revert to these. */
    property var base: ({})

    readonly property var accelOptions: [
        { label: "Flat", value: "flat" },
        { label: "Adaptive", value: "adaptive" }
    ]

    readonly property var kbLayouts: ["de", "us", "gb", "fr", "es", "it", "tr"]
    readonly property var kbLayoutVals: kbLayouts.indexOf(kbLayout) >= 0 ? kbLayouts : kbLayouts.concat([kbLayout])

    onActiveChanged: {
        if (active) {
            inputFile.reload();
            envFile.reload();
            autostartFile.reload();
            seed();
            themeProc.running = true;
        } else {
            themeOpen = false;
            focusRowItem = null;
            kbIndex = -1;
        }
    }

    /**
     * Seeds every control from the live source files. Numbers fall back to the
     * defaults when a field is missing so a partially hand-edited config never
     * leaves a control blank.
     */
    function seed() {
        root.inputText = inputFile.text();
        root.envText = envFile.text();
        root.autostartText = autostartFile.text();

        var inp = root.inputText;
        var sens = parseFloat(SetInput.getField(inp, "sensitivity"));
        root.sensitivity = isNaN(sens) ? 0 : sens;
        var ap = SetInput.getField(inp, "accel_profile");
        root.accelProfile = ap.length > 0 ? ap : "flat";
        var kl = SetInput.getField(inp, "kb_layout");
        root.kbLayout = kl.length > 0 ? kl : "de";
        var rr = parseInt(SetInput.getField(inp, "repeat_rate"), 10);
        root.repeatRate = isNaN(rr) ? 25 : rr;
        var rd = parseInt(SetInput.getField(inp, "repeat_delay"), 10);
        root.repeatDelay = isNaN(rd) ? 600 : rd;
        root.numlockOn = SetInput.getField(inp, "numlock_by_default") === "true";

        var env = root.envText;
        var cs = parseInt(SetInput.getField(env, "XCURSOR_SIZE"), 10);
        root.cursorSize = isNaN(cs) ? 24 : cs;
        var ct = SetInput.getField(env, "XCURSOR_THEME");
        root.cursorTheme = ct.length > 0 ? ct : "Bibata-Modern-Ice";

        root.base = {
            sensitivity: root.sensitivity,
            repeatRate: root.repeatRate,
            repeatDelay: root.repeatDelay,
            cursorSize: root.cursorSize
        };
    }

    /**
     * Rewrites one input.lua field to `literal` (already formatted by the caller)
     * and reloads Hyprland so the change takes effect at once.
     */
    function writeInputField(name, literal) {
        var res = SetInput.setField(root.inputText, name, literal);
        if (!res.ok)
            return;
        root.inputText = res.text;
        inputWriter.setText(res.text);
        reloadTimer.restart();
    }

    function setKbLayout(v) {
        root.kbLayout = v;
        root.writeInputField("kb_layout", "\"" + v + "\"");
    }

    /**
     * Applies a cursor theme/size pair live via `hyprctl setcursor`, then persists
     * it by rewriting the XCURSOR/HYPRCURSOR env lines and the autostart setcursor
     * call. No Hyprland reload is needed for the cursor.
     */
    function applyCursor(theme, size) {
        setcursorProc.theme = theme;
        setcursorProc.size = size;
        setcursorProc.running = true;

        var env = root.envText;
        var e1 = SetInput.setEnv(env, "XCURSOR_THEME", theme);
        var e2 = SetInput.setEnv(e1.ok ? e1.text : env, "XCURSOR_SIZE", String(size));
        var e3 = SetInput.setEnv(e2.ok ? e2.text : (e1.ok ? e1.text : env), "HYPRCURSOR_SIZE", String(size));
        if (e3.ok || e2.ok || e1.ok) {
            root.envText = e3.ok ? e3.text : (e2.ok ? e2.text : e1.text);
            envWriter.setText(root.envText);
        }

        var auto = SetInput.setCursorLine(root.autostartText, theme, size);
        if (auto.ok) {
            root.autostartText = auto.text;
            autostartWriter.setText(auto.text);
        }
    }

    function clampSensitivity(v) {
        return Math.max(-1, Math.min(1, Math.round(v * 10) / 10));
    }

    FileView {
        id: inputFile
        path: root.inputPath
        blockLoading: true
        printErrors: false
    }

    FileView {
        id: inputWriter
        path: root.inputPath
        atomicWrites: true
        printErrors: false
    }

    FileView {
        id: envFile
        path: root.envPath
        blockLoading: true
        printErrors: false
    }

    FileView {
        id: envWriter
        path: root.envPath
        atomicWrites: true
        printErrors: false
    }

    FileView {
        id: autostartFile
        path: root.autostartPath
        blockLoading: true
        printErrors: false
    }

    FileView {
        id: autostartWriter
        path: root.autostartPath
        atomicWrites: true
        printErrors: false
    }

    /**
     * Reload is debounced so a scrub drag writes the file per step but reloads
     * Hyprland once, and captured so a failed reload surfaces as the inline note
     * instead of vanishing with a detached process.
     */
    Timer {
        id: reloadTimer
        interval: 250
        repeat: false
        onTriggered: reloadProc.running = true
    }

    Process {
        id: reloadProc
        command: ["sh", "-c", "sleep 0.3; hyprctl reload"]
        onExited: function (exitCode) {
            root.note = exitCode === 0 ? "" : "Hyprland reload failed. The change is saved but not applied.";
        }
    }

    Process {
        id: setcursorProc
        property string theme: ""
        property int size: 24
        command: ["hyprctl", "setcursor", theme, String(size)]
    }

    Process {
        id: themeProc
        command: ["sh", "-c", "{ printf '%s\\n' \"$HOME/.icons\" \"$HOME/.local/share/icons\" /usr/share/icons; printf '%s' \"${XDG_DATA_DIRS:-/usr/local/share:/usr/share}\" | tr ':' '\\n' | sed 's#/*$#/icons#'; } | sort -u | while IFS= read -r d; do [ -d \"$d\" ] || continue; for t in \"$d\"/*/; do [ -d \"$t/cursors\" ] && basename \"$t\"; done; done | sort -u"]
        stdout: StdioCollector {
            onStreamFinished: {
                var lines = this.text.split("\n").filter(function (l) { return l.trim().length > 0; });
                root.cursorThemes = lines;
            }
        }
    }

    component GroupLabel: Text {
        topPadding: 16 * root.s
        bottomPadding: 6 * root.s
        color: Theme.faint
        font.family: Theme.font
        font.pixelSize: 8.5 * root.s
        font.weight: Font.Bold
        font.capitalization: Font.AllUppercase
        font.letterSpacing: 1.2 * root.s
    }

    /**
     * One settings line. At rest it is an icon + label + control row; hovering or
     * keyboard-focusing the row folds its grey caption open below the label so
     * the tab stays compact by default. The row feeds the surface registry: hover
     * moves the soul seam and a click anywhere on the line drives its control via
     * activateRow.
     */
    component FieldRow: Item {
        id: frow
        property string label: ""
        property string caption: ""
        property string icon: ""
        default property alias control: ctrl.data

        readonly property bool focused: root.focusRowItem === frow
        readonly property bool expanded: fhover.hovered || frow.focused
        readonly property real rowH: 30 * root.s
        readonly property real capH: 14 * root.s

        width: parent ? parent.width : 0
        height: frow.rowH + (frow.expanded ? frow.capH : 0)
        clip: true
        Behavior on height { NumberAnimation { duration: Motion.fast; easing.type: Easing.OutCubic } }

        HoverHandler {
            id: fhover
            onHoveredChanged: root.reportRowHover(frow, hovered)
        }

        Rectangle {
            anchors.fill: parent
            anchors.topMargin: 3 * root.s
            anchors.bottomMargin: 3 * root.s
            radius: 9 * root.s
            color: (fhover.hovered || frow.focused) ? Theme.frameBg : "transparent"
            Behavior on color { ColorAnimation { duration: Motion.fast } }
        }

        MouseArea {
            anchors.fill: parent
            cursorShape: Qt.PointingHandCursor
            onClicked: root.activateRow(frow)
        }

        GlyphIcon {
            id: rowIcon
            anchors.left: parent.left
            anchors.leftMargin: 9 * root.s
            anchors.verticalCenter: parent.verticalCenter
            visible: frow.icon.length > 0
            width: 15 * root.s
            height: 15 * root.s
            name: frow.icon
            color: frow.focused ? Theme.cream : Theme.subtle
            stroke: 1.8
        }

        Column {
            anchors.left: rowIcon.visible ? rowIcon.right : parent.left
            anchors.leftMargin: 9 * root.s
            anchors.verticalCenter: parent.verticalCenter
            spacing: 2 * root.s

            Text {
                text: frow.label
                color: Theme.cream
                font.family: Theme.font
                font.pixelSize: 12.5 * root.s
                font.weight: Font.Medium
            }

            Text {
                visible: frow.expanded && frow.caption.length > 0
                text: frow.caption
                color: Theme.faint
                font.family: Theme.font
                font.pixelSize: 9 * root.s
                font.weight: Font.Medium
            }
        }

        Item {
            id: ctrl
            anchors.right: parent.right
            anchors.rightMargin: 9 * root.s
            anchors.verticalCenter: parent.verticalCenter
            width: childrenRect.width
            height: childrenRect.height
        }
    }

    Column {
        id: content
        z: 100
        anchors.top: parent.top
        anchors.left: parent.left
        anchors.right: parent.right
        spacing: 0
        height: root.height + root.mBottom * root.s
        clip: true

        SettingsHeader {
            s: root.s
            glyph: "操"
            title: "INPUT"
            showBack: true
        }

        Column {
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.leftMargin: 12 * root.s
            anchors.rightMargin: 12 * root.s
            spacing: 0

            GroupLabel { text: "Pointer" }

            FieldRow {
                id: sensRow
                label: "Sensitivity"
                caption: "Pointer speed offset"
                icon: "mouse"
                ScrubValue {
                    id: sensScrub
