import QtQuick
import QtQuick.Controls
import Quickshell.Io
import qs.services
import qs.modules.controlcenter
import qs.components.icons

/**
 * 相 APPEARANCE sub-surface: the clock format and seconds, the Japanese-glyph
 * toggle that gates every surface header, the palette mode (static flame, dynamic
 * per-wallpaper, or a manually chosen hue), the UI scale and a reduce-motion
 * switch. Reached from the settings index and morphs back to it on an empty click
 * or the back chevron.
 *
 * Manual palette mode reveals a rainbow hue strip and a dark/light choice; moving
 * either rebuilds the rice colour set from that hue through wallcolors.py --hue
 * and reloads Hyprland and the terminal, debounced so a drag does not spawn a
 * build per pixel.
 */
SettingsSurface {
    id: root

    backSurface: "settings"
    implicitHeight: content.implicitHeight

    property string hueArg: String(Math.round(Flags.manualHue))
    property string modeArg: Flags.manualDark ? "dark" : "light"
    property string satArg: String(Flags.manualSat)

    readonly property color accentColor: Qt.hsla(Flags.manualHue / 360, Flags.manualSat, Flags.manualDark ? 0.5 : 0.62, 1)
    readonly property string currentHex: {
        var c = accentColor;
        function h(x) { return ("0" + Math.round(x * 255).toString(16)).slice(-2); }
        return ("#" + h(c.r) + h(c.g) + h(c.b)).toUpperCase();
    }

    function applyManual() {
        hueArg = String(Math.round(Flags.manualHue));
        modeArg = Flags.manualDark ? "dark" : "light";
        satArg = String(Flags.manualSat);
        applyTimer.restart();
    }

    function applyMode(v) {
        Flags.paletteMode = v;
        if (v === "manual")
            applyManual();
        else if (v === "dynamic")
            dynamicProc.running = true;
    }

    Timer {
        id: applyTimer
        interval: 260
        repeat: false
        onTriggered: paletteProc.running = true
    }

    Process {
        id: paletteProc
        command: ["sh", "-c",
            "python3 \"$HOME/.config/hypr/scripts/wallcolors.py\" --hue \"$1\" \"$2\" \"$3\" && hyprctl reload >/dev/null 2>&1; kitty @ load-config >/dev/null 2>&1 || true",
            "sh", root.hueArg, root.modeArg, root.satArg]
    }

    Process {
        id: dynamicProc
        command: ["sh", "-c",
            "f=\"${XDG_STATE_HOME:-$HOME/.local/state}/ricelin-wallpaper\"; pic=$(cat \"$f\" 2>/dev/null); [ -f \"$pic\" ] && python3 \"$HOME/.config/hypr/scripts/wallcolors.py\" \"$pic\" >/dev/null 2>&1; hyprctl reload >/dev/null 2>&1; kitty @ load-config >/dev/null 2>&1 || true"]
    }

    Connections {
        target: Flags
        function onManualHueChanged() {
            if (Flags.paletteMode === "manual")
                root.applyManual();
        }
        function onManualSatChanged() {
            if (Flags.paletteMode === "manual")
                root.applyManual();
        }
    }

    rows: [
        { item: timeRow, kind: "seg", vals: [false, true], get: function () { return Flags.time12h; }, set: function (v) { Flags.time12h = v; } },
        { item: secRow, kind: "toggle", get: function () { return Flags.clockSeconds; }, set: function (v) { Flags.clockSeconds = v; } },
        { item: glyphRow, kind: "toggle", get: function () { return Flags.showGlyphs; }, set: function (v) { Flags.showGlyphs = v; } },
        { item: vizRow, kind: "toggle", get: function () { return Flags.musicViz; }, set: function (v) { Flags.musicViz = v; } },
        { item: notchRow, kind: "toggle", get: function () { return Flags.notchStyle; }, set: function (v) { Flags.notchStyle = v; } },
        { item: paletteRow, kind: "seg", vals: ["static", "dynamic", "manual"], get: function () { return Flags.paletteMode; }, set: function (v) { root.applyMode(v); } },
        { item: scaleRow, kind: "seg", vals: [0.9, 1.0, 1.1, 1.25], get: function () { return Flags.uiScale; }, set: function (v) { Flags.uiScale = v; } },
        { item: motionRow, kind: "toggle", get: function () { return Flags.reduceMotion; }, set: function (v) { Flags.reduceMotion = v; } },
        { item: fontRow, kind: "nav", surface: "fontpicker" }
    ]

    Column {
        id: content
        anchors.top: parent.top
        anchors.left: parent.left
        anchors.right: parent.right
        spacing: 0

        SettingsHeader {
            s: root.s
            glyph: "相"
            title: "APPEARANCE"
            showBack: true
        }

        Item { width: 1; height: 12 * root.s }

        SettingsRow {
            id: timeRow
            surface: root
            name: "Time format"
            icon: "clock"

            SettingsSeg {
                s: root.s
                options: [{ label: "24H", value: false }, { label: "12H", value: true }]
                value: Flags.time12h
                onPicked: (v) => Flags.time12h = v
            }
        }

        SettingsRow {
            id: secRow
            surface: root
            name: "Clock seconds"
            icon: "stopwatch"

            LinkToggle {
                s: root.s
                on: Flags.clockSeconds
                onToggled: Flags.clockSeconds = !Flags.clockSeconds
            }
        }

        SettingsRow {
            id: glyphRow
            surface: root
            name: "Japanese glyphs"
            icon: "language"

            LinkToggle {
                s: root.s
                on: Flags.showGlyphs
                onToggled: Flags.showGlyphs = !Flags.showGlyphs
            }
        }

        SettingsRow {
            id: vizRow
            surface: root
            name: "Music visualizer"
            icon: "music"

            LinkToggle {
                s: root.s
                on: Flags.musicViz
                onToggled: Flags.musicViz = !Flags.musicViz
            }
        }

        SettingsRow {
            id: notchRow
            surface: root
            name: "Show as notch"
            icon: "dynamic-island"

            LinkToggle {
                s: root.s
                on: Flags.notchStyle
                onToggled: Flags.notchStyle = !Flags.notchStyle
            }
        }

        SettingsRow {
            id: paletteRow
            surface: root
            name: "Palette"
            icon: "palette"

            SettingsSeg {
                s: root.s
                options: [{ label: "Static", value: "static" }, { label: "Dynamic", value: "dynamic" }, { label: "Manual", value: "manual" }]
                value: Flags.paletteMode
                onPicked: (v) => root.applyMode(v)
            }
        }

        /**
         * Manual hue editor, folded shut unless the palette is on Manual. Holds a
         * rainbow strip with a draggable thumb, then a single line pairing a live
         * accent swatch and its hex caption with the dark/light choice, and a hex
         * input that drives both hue and saturation. The strip is mouse-driven and
         * stays out of the keyboard row registry.
         */
        Item {
            id: manualSection
            width: parent.width
            height: Flags.paletteMode === "manual" ? manualCol.implicitHeight : 0
            clip: true
            Behavior on height { NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard } }

            Column {
                id: manualCol
                anchors.top: parent.top
                anchors.left: parent.left
                anchors.right: parent.right
                anchors.leftMargin: 12 * root.s
                anchors.rightMargin: 12 * root.s
                topPadding: 4 * root.s
                bottomPadding: 16 * root.s
                spacing: 14 * root.s

                Item {
                    width: parent.width
                    height: 14 * root.s

                    Rectangle {
                        id: hueStrip
                        anchors.fill: parent
                        radius: 7 * root.s
                        gradient: Gradient {
                            orientation: Gradient.Horizontal
                            GradientStop { position: 0.0; color: Qt.hsla(0.0, 0.7, 0.5, 1) }
                            GradientStop { position: 1 / 6; color: Qt.hsla(1 / 6, 0.7, 0.5, 1) }
                            GradientStop { position: 2 / 6; color: Qt.hsla(2 / 6, 0.7, 0.5, 1) }
                            GradientStop { position: 3 / 6; color: Qt.hsla(3 / 6, 0.7, 0.5, 1) }
                            GradientStop { position: 4 / 6; color: Qt.hsla(4 / 6, 0.7, 0.5, 1) }
                            GradientStop { position: 5 / 6; color: Qt.hsla(5 / 6, 0.7, 0.5, 1) }
                            GradientStop { position: 1.0; color: Qt.hsla(1.0, 0.7, 0.5, 1) }
                        }

                        Rectangle {
                            id: hueThumb
                            width: 16 * root.s
                            height: 16 * root.s
                            radius: width / 2
                            anchors.verticalCenter: parent.verticalCenter
                            x: (Flags.manualHue / 359) * (hueStrip.width - width)
                            color: root.accentColor
                            border.width: 2.5 * root.s
                            border.color: Theme.cream
                        }

                        MouseArea {
                            anchors.fill: parent
                            cursorShape: Qt.PointingHandCursor
                            function setHue(mx) {
                                if (Flags.manualSat < 0.05)
                                    Flags.manualSat = 0.5;
                                Flags.manualHue = Math.round(Math.max(0, Math.min(1, mx / hueStrip.width)) * 359);
                            }
                            onPressed: (mouse) => setHue(mouse.x)
                            onPositionChanged: (mouse) => setHue(mouse.x)
                        }
                    }
                }

                Item {
                    width: parent.width
                    height: Math.max(34 * root.s, toneSeg.implicitHeight)

                    Rectangle {
                        id: accentSwatch
                        anchors.left: parent.left
                        anchors.verticalCenter: parent.verticalCenter
                        width: 34 * root.s
                        height: 34 * root.s
                        radius: 9 * root.s
                        color: root.accentColor
                        border.width: 1
                        border.color: Theme.border
                    }

                    Column {
                        anchors.left: accentSwatch.right
                        anchors.leftMargin: 12 * root.s
                        anchors.right: toneSeg.left
                        anchors.rightMargin: 12 * root.s
                        anchors.verticalCenter: parent.verticalCenter
                        spacing: 3 * root.s

                        Text {
                            text: "Accent hue"
                            color: Theme.cream
                            font.family: Theme.font
                            font.pixelSize: 12 * root.s
                            font.weight: Font.DemiBold
                        }
                        Text {
                            text: root.currentHex + " · " + (Flags.manualDark ? "dark" : "light")
                            color: Theme.faint
                            font.family: Theme.font
                            font.pixelSize: 10.5 * root.s
                            font.features: { "tnum": 1 }
                            elide: Text.ElideRight
                            width: parent.width
                        }
                    }

                    SettingsSeg {
                        id: toneSeg
                        anchors.right: parent.right
                        anchors.verticalCenter: parent.verticalCenter
                        s: root.s
                        options: [{ label: "Dark", value: true }, { label: "Light", value: false }]
                        value: Flags.manualDark
                        onPicked: (v) => { Flags.manualDark = v; root.applyManual(); }
                    }
                }

                Item {
                    width: parent.width
                    height: 30 * root.s

                    Text {
                        id: hexHint
                        anchors.left: parent.left
                        anchors.leftMargin: 12 * root.s
                        anchors.verticalCenter: parent.verticalCenter
                        text: "#"
                        color: Theme.faint
                        font.family: Theme.font
                        font.pixelSize: 14 * root.s
                        font.weight: Font.DemiBold
                    }

                    TextField {
                        id: hexField
                        anchors.left: hexHint.right
                        anchors.leftMargin: 6 * root.s
                        anchors.right: parent.right
                        anchors.rightMargin: 12 * root.s
                        anchors.verticalCenter: parent.verticalCenter
                        background: null
                        padding: 0
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 13 * root.s
                        font.features: { "tnum": 1 }
                        placeholderText: root.currentHex
                        placeholderTextColor: Theme.faint
                        selectByMouse: true
                        selectionColor: Theme.verm
                        maximumLength: 7

                        onActiveFocusChanged: if (!activeFocus) text = "";

                        function commit() {
                            var raw = text.trim();
                            var clean = raw.charAt(0) === "#" ? raw.slice(1) : raw;
                            if (/^[0-9a-fA-F]{6}$/.test(clean)) {
                                var c = Qt.color("#" + clean);
                                if (c.hslHue >= 0) {
                                    Flags.manualHue = Math.round(c.hslHue * 359);
                                    Flags.manualSat = c.hslSaturation;
                                } else {
                                    Flags.manualSat = 0;
                                }
                                root.applyManual();
                            }
                            text = "";
                            focus = false;
                        }

                        onAccepted: commit()
                        onEditingFinished: commit()
                    }

                    Rectangle {
                        anchors.left: hexField.left
                        anchors.right: hexField.right
                        anchors.top: hexField.bottom
                        anchors.topMargin: 3 * root.s
                        height: 1
                        color: Theme.faint
                        opacity: hexField.activeFocus ? 0.7 : 0.18
                        Behavior on opacity { NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard } }
                    }
                }
            }
        }

        SettingsRow {
            id: scaleRow
            surface: root
            name: "UI scale"
            icon: "scaling"

            SettingsSeg {
                s: root.s
                options: [{ label: "90%", value: 0.9 }, { label: "100%", value: 1.0 }, { label: "110%", value: 1.1 }, { label: "125%", value: 1.25 }]
                value: Flags.uiScale
                onPicked: (v) => Flags.uiScale = v
            }
        }

        SettingsRow {
            id: motionRow
            surface: root
            name: "Reduce motion"
            icon: "waves"

            LinkToggle {
                s: root.s
                on: Flags.reduceMotion
                onToggled: Flags.reduceMotion = !Flags.reduceMotion
            }
        }

        SettingsRow {
            id: fontRow
            surface: root
            name: "Font"
            icon: "type"
            sub: Flags.uiFont.length > 0 ? Flags.uiFont : "Inter"
            last: true

            GlyphIcon {
                width: 16 * root.s
                height: 16 * root.s
                name: "chevron-right"
                color: root.focusRowItem === fontRow ? Theme.cream : Theme.iconDim
                stroke: 1.9
            }
        }
    }
}

pragma ComponentBehavior: Bound

import QtQuick
import qs.services


/**
 * Rest-pill spectrum: one rounded ember bar per cava band, packed into the
 * clock-glyph slot so the cluster never widens the pill. Heights chase
 * Cava.levels with a short ease so the motion stays liquid instead of strobing
 * on every frame cava emits.
 */

Row {
    id: root

    property real s: 1.1
    property real span: 10
    property bool centeredVisualizer: false
    property bool stringVisualizer: false

    height: span * s
    width: stringVisualizer ? 80 * s : Cava.bars * (2.8 * s + 1.4 * s)
    spacing: stringVisualizer ? 0 : 1.8 * s
    y: 2 * s

    Loader {
        active: root.stringVisualizer
        width: root.width
        height: root.height
        visible: root.stringVisualizer
        sourceComponent: musicLineComponent
    }

    Component {
        id: musicLineComponent

        FastMusicLine {
            width: parent.width
            height: parent.height
            x: -18 * root.s
            y: -0.8 * root.s
            scale: 0.15 * root.s
            transformOrigin: Item.Center
        }
    }

    Repeater {
        model: root.stringVisualizer ? 0 : Cava.bars

        Rectangle {
            required property int index

            width: 1.8 * root.s
            radius: width / 2

            anchors.verticalCenter: root.centeredVisualizer ? parent.verticalCenter : undefined
            anchors.bottom: root.centeredVisualizer ? undefined : parent.bottom

            height: Math.max(
                2 * root.s,
                (Cava.levels[index] || 0) * root.span * root.s * 1.4
            )

            gradient: Gradient {
                GradientStop {
                    position: 0.0
                    color: Theme.flameGlow
                }

                GradientStop {
                    position: 1.0
                    color: Theme.vermLit
                }
            }

            Behavior on height {
                NumberAnimation {
                    duration: Motion.fast
                    easing.type: Easing.OutQuad
                }
            }
        }
    }
}

import QtQuick
import qs.services
import qs.components.icons

/**
 * Horizontal capture-level fader for the recorder's audio rows: a thin matte
 * track with a flame fill and a flat tick marker at the value, no knob. Mirrors
 * the mixer VFader look and contract (drag plus `step` for scroll-wheel and
 * arrow keys, 5% per notch) so the same focus and stepping logic drives it.
 * The host owns focus and feeds `focused`; `on` saturates the fill, off dims
 * it. Value is 0..1. A right-aligned percent readout trails the track.
 */
Item {
    id: root

    property real s: 1.1
    property real value: 0.5
    property bool focused: false
    property bool on: true

    signal moved(real v)
    signal committed(real v)
    signal focusRequested()

    implicitHeight: 16 * s

    /**
     * Nudge the value by a signed percentage (e.g. +5 / -5), clamped to 0..100%,
     * emitting `moved` and `committed` so the captured level updates on each step.
     */
    function step(deltaPct) {
        const v = Math.max(0, Math.min(1, root.value + deltaPct / 100));
        root.moved(v);
        root.committed(v);
    }

    readonly property real clamped: Math.max(0, Math.min(1, value))

    Rectangle {
        id: track
        anchors.left: parent.left
        anchors.right: pct.left
        anchors.rightMargin: 11 * root.s
        anchors.verticalCenter: parent.verticalCenter
        height: 3 * root.s
        radius: height / 2
        color: Theme.threadBg

        Rectangle {
            id: fill
            anchors.left: parent.left
            anchors.top: parent.top
            anchors.bottom: parent.bottom
            width: parent.width * root.clamped
            radius: parent.radius
            gradient: Gradient {
                orientation: Gradient.Horizontal
                GradientStop { position: 0.0; color: root.on ? Theme.vermBurn : Theme.vermDimDeep }
                GradientStop { position: 1.0; color: root.on ? Theme.vermLit : Theme.vermDim }
            }
            Behavior on width { enabled: !dragArea.pressed; NumberAnimation { duration: Motion.fast } }
        }

        Rectangle {
            id: tick
            x: Math.max(0, Math.min(track.width - width, track.width * root.clamped - width / 2))
            anchors.verticalCenter: parent.verticalCenter
            width: 2.5 * root.s
            height: 11 * root.s
            radius: 2 * root.s
            color: Theme.tickRest
            Behavior on x { enabled: !dragArea.pressed; NumberAnimation { duration: Motion.fast } }
        }

        MouseArea {
            id: dragArea
            anchors.fill: parent
            anchors.margins: -8 * root.s
            preventStealing: true
            enabled: root.on
            function setFromX(mx) {
                const v = Math.max(0, Math.min(1, (mx + 8 * root.s) / track.width));
                root.moved(v);
            }
            onPressed: (e) => { root.focusRequested(); setFromX(e.x); }
            onPositionChanged: (e) => { if (pressed) setFromX(e.x); }
            onReleased: root.committed(root.value)
        }
    }

    Text {
        id: pct
        anchors.right: parent.right
        anchors.verticalCenter: parent.verticalCenter
        width: 32 * root.s
        horizontalAlignment: Text.AlignRight
        text: Math.round(root.clamped * 100) + "%"
        color: root.focused ? Theme.cream : Theme.subtle
        font.family: Theme.font
        font.pixelSize: 10 * root.s
        font.weight: Font.DemiBold
        font.features: { "tnum": 1 }
    }
}

pragma Singleton
import QtQuick
import Quickshell
import Quickshell.Services.Notifications

Singleton {
    id: root

    property var seenIds: ({})
    property var arrivalMs: ({})
    property var popups: []
    property int tick: 0
    property var expandedApps: ({})
    property var history: []
    property var userDismissed: ({})
    property var expireAt: ({})
    property var hookedIds: ({})

    readonly property var tracked: server.trackedNotifications.values
    readonly property int count: tracked.length + history.length

    readonly property int unread: {
        var u = 0;
        for (var i = 0; i < tracked.length; i++)
            if (!seenIds[tracked[i].id]) u++;
        return u;
    }

    readonly property var groups: {
        var map = {};
        var order = [];
        for (var i = 0; i < tracked.length; i++) {
            var n = tracked[i];
            var app = (n.appName && n.appName.length) ? n.appName : "System";
            if (map[app] === undefined) { map[app] = []; order.push(app); }
            map[app].push({ live: true, n: n, t: arrivalMs[n.id] || 0 });
        }
        for (var j = 0; j < history.length; j++) {
            var h = history[j];
            if (map[h.app] === undefined) { map[h.app] = []; order.push(h.app); }
            map[h.app].push({ live: false, n: h, t: h.ts || 0 });
        }
        function coalesce(list, it) {
            var last = list.length > 0 ? list[list.length - 1] : null;
            if (last && last.n.summary === it.n.summary && last.n.body === it.n.body) {
                last.count++;
                last.items.push(it.n);
            } else {
                list.push({ live: it.live, n: it.n, count: 1, items: [it.n] });
            }
        }
        var gs = order.map(function(app) {
            var items = map[app];
            items.sort(function(a, b) { return b.t - a.t; });
            var criticals = [];
            var entries = [];
            for (var k = 0; k < items.length; k++)
                coalesce(items[k].n.urgency === NotificationUrgency.Critical ? criticals : entries, items[k]);
            var preview = items.find(function(it) { return it.n.urgency !== NotificationUrgency.Critical; });
            return {
                app: app,
                count: items.length,
                t: items[0].t,
                newest: items[0].n,
                preview: preview ? preview.n : items[0].n,
                criticals: criticals,
                entries: entries
            };
        });
        gs.sort(function(a, b) { return b.t - a.t; });
        return gs;
    }

    function iconFor(n) {
        if (!n) return "";
        var img = n.image || "";
        var names = [];
        if (img.indexOf("image://icon/") === 0) {
            names.push(img.substring(13));
        } else if (img.length && !/\.svg$/i.test(img)) {
            return img;
        }
        names.push(n.appIcon, n.desktopEntry, (n.appName || n.app || "").toLowerCase());
        for (var i = 0; i < names.length; i++) {
            var nm = names[i];
            if (!nm || !nm.length) continue;
            if (nm.indexOf("/") === 0 || nm.indexOf("file://") === 0) return nm;
            var p = Quickshell.iconPath(nm, true);
            if (p.length) return p;
        }
        return "";
    }

    function dismissEntry(e) {
        if (!e || !e.items) return;
        var d = Object.assign({}, userDismissed);
        var gone = {};
        var live = [];
        for (var i = 0; i < e.items.length; i++) {
            var n = e.items[i];
            if (typeof n.dismiss === "function") {
                d[n.id] = true;
                live.push(n);
            } else {
                gone[n.id] = true;
            }
        }
        root.userDismissed = d;
        for (var j = 0; j < live.length; j++) live[j].dismiss();
        root.history = root.history.filter(function(h) { return !gone[h.id]; });
    }

    /**
     * Focus the app's Hyprland window (workspace switch included) by matching the
     * notification's desktopEntry/appName against the live window classes.
     */
    function raiseWindow(n) {
        if (!n) return;
        var token = String(n.desktopEntry && n.desktopEntry.length ? n.desktopEntry : (n.appName || "")).toLowerCase();
        if (token.length === 0) return;
        Quickshell.execDetached(["sh", "-c",
            "addr=$(hyprctl clients -j | jq -r --arg q \"$1\" 'first(.[] | select(((.class | if . then ascii_downcase else \"\" end) | contains($q)) or ((.initialClass | if . then ascii_downcase else \"\" end) | contains($q))) | .address)'); [ -n \"$addr\" ] && hyprctl dispatch \"hl.dsp.focus({ window = \\\"address:$addr\\\" })\"",
            "sh", token]);
    }

    /**
     * Open the app behind a notification: invoke its default action when present,
     * then jump to the app's window, mirroring stock notification-center behavior.
     */
    function activateNotif(n) {
        if (!n) return;
        var acts = n.actions || [];
        for (var i = 0; i < acts.length; i++) {
            if (acts[i].identifier === "default") {
                acts[i].invoke();
                break;
            }
        }
        raiseWindow(n);
    }

    /** Inbox-row entry wrapper: activate the app, then dismiss the entry. */
    function activateEntry(e) {
        if (!e || !e.n) return;
        activateNotif(e.n);
        dismissEntry(e);
    }

    function dismissApp(app) {
        var doomed = tracked.filter(function(n) {
            return ((n.appName && n.appName.length) ? n.appName : "System") === app;
        });
        var d = Object.assign({}, userDismissed);
        for (var i = 0; i < doomed.length; i++) d[doomed[i].id] = true;
        root.userDismissed = d;
        for (var j = 0; j < doomed.length; j++) doomed[j].dismiss();
        root.history = root.history.filter(function(h) { return h.app !== app; });
    }

    function markAllSeen() {
        var m = {};
        for (var i = 0; i < tracked.length; i++) m[tracked[i].id] = true;
        root.seenIds = m;
    }

    function clearAll() {
        var l = tracked.slice();
        var d = Object.assign({}, userDismissed);
        for (var i = 0; i < l.length; i++) d[l[i].id] = true;
        root.userDismissed = d;
        for (var j = 0; j < l.length; j++) l[j].dismiss();
        root.history = [];
        root.popups = [];
    }

    function removePopup(n) {
        root.popups = root.popups.filter(function(p) { return p !== n; });
    }

    function toggleExpanded(app) {
        var e = Object.assign({}, expandedApps);
        e[app] = e[app] !== true;
        root.expandedApps = e;
    }

    /**
     * Bind the history-snapshot handler to a notification's `closed` signal once.
     * `keepOnReload` re-runs Component.onCompleted on every QS reload over the
     * still-tracked notifications, so the id set gates re-hooks: without it each
     * reload would stack another handler and a single close would push duplicate
     * history rows. The id is cleared inside the handler so a later notification
     * reusing the id re-hooks cleanly.
     */
    function hookClosed(n) {
        if (root.hookedIds[n.id])
            return;
        var hooked = Object.assign({}, root.hookedIds);
        hooked[n.id] = true;
        root.hookedIds = hooked;
        n.closed.connect(function(reason) {
            if (!root.userDismissed[n.id])
                root.history = [{
                    app: (n.appName && n.appName.length) ? n.appName : "System",
                    summary: n.summary,
                    body: n.body,
                    appIcon: n.appIcon,
                    desktopEntry: n.desktopEntry,
                    image: n.image,
                    urgency: n.urgency,
                    ts: root.arrivalMs[n.id] || Date.now(),
                    id: "h" + n.id + "-" + Date.now()
                }].concat(root.history).slice(0, 50);
            else {
                var du = Object.assign({}, root.userDismissed);
                delete du[n.id];
                root.userDismissed = du;
            }
            root.removePopup(n);
            var b = Object.assign({}, root.arrivalMs);
            delete b[n.id];
            root.arrivalMs = b;
            var c = Object.assign({}, root.expireAt);
            delete c[n.id];
            root.expireAt = c;
            var h = Object.assign({}, root.hookedIds);
            delete h[n.id];
            root.hookedIds = h;
        });
    }

    function ageLabel(n) {
        void root.tick;
        var t = arrivalMs[n.id] || n.ts;
        if (!t) return "";
        var m = Math.floor((Date.now() - t) / 60000);
        if (m < 1) return "now";
        if (m < 60) return m + "m";
        return Math.floor(m / 60) + "h";
    }

    Timer {
        interval: 30000
        running: root.count > 0
        repeat: true
        onTriggered: root.tick++
    }

    NotificationServer {
        id: server
        keepOnReload: true
        bodySupported: true
        actionsSupported: true
        imageSupported: true

        Component.onCompleted: {
            var l = trackedNotifications.values;
            var a = Object.assign({}, root.arrivalMs);
            for (var i = 0; i < l.length; i++) {
                if (!a[l[i].id]) a[l[i].id] = Date.now();
                root.hookClosed(l[i]);
            }
            root.arrivalMs = a;
        }

        onNotification: function(n) {
            var a = Object.assign({}, root.arrivalMs);
            a[n.id] = Date.now();
            root.arrivalMs = a;
            var e = Object.assign({}, root.expireAt);
            e[n.id] = Date.now() + (n.urgency === NotificationUrgency.Low ? 4000 : 6000);
            root.expireAt = e;
            n.tracked = true;
            root.hookClosed(n);
            var critical = n.urgency === NotificationUrgency.Critical;
            if (!Flags.dnd || critical)
                root.popups = root.popups.concat([n]).slice(-3);
        }
    }
}

pragma Singleton

import QtQuick
import Quickshell
import Quickshell.Services.Mpris
import Quickshell.Hyprland

/**
 * The one now-playing source the pill views read: the media surface, the source
 * switcher and the OSD. Selection is by player object so the
 * pick survives metadata churn and falls away when that player's process dies.
 * `active` is the player you last picked by hand, else the one auto-tracked by
 * playback, which holds against a background tab that autoplays.
 */
Singleton {
    id: root

    function isProxy(p) {
        return (p && p.dbusName ? p.dbusName : "").toLowerCase().indexOf("playerctld") >= 0;
    }

    function isIdle(p) {
        if (!p || isProxy(p))
            return true;
        return !p.isPlaying && (!p.trackTitle || p.trackTitle.length === 0);
    }

    function otherPlaying(self) {
        var l = root.list;
        for (var i = 0; i < l.length; i++)
            if (l[i] !== self && l[i].isPlaying)
                return true;
        return false;
    }

    readonly property var list: {
        var all = Mpris.players.values;
        var out = [];
        for (var i = 0; i < all.length; i++)
            if (all[i] && !isProxy(all[i]))
                out.push(all[i]);
        return out;
    }

    readonly property var pickable: {
        var l = root.list;
        var out = [];
        for (var i = 0; i < l.length; i++)
            if (!isIdle(l[i]))
                out.push(l[i]);
        return out;
    }

    property var manualActive: null
    property var preferred: null

    property bool ready: false
    Component.onCompleted: {
        ready = true;
        resolveTwitch();
        resolveNetflix();
    }

    onListChanged: {
        if (manualActive && list.indexOf(manualActive) < 0)
            manualActive = null;
        if (preferred && list.indexOf(preferred) < 0)
            preferred = null;
    }

    /**
     * A playing player always wins, with the recently-played one preferred while
     * it plays. Only when nothing is playing do we hold the paused preferred, so
     * pausing your music doesn't hand the surface to a paused background tab, yet
     * actually starting another player switches to it.
     */
    readonly property var autoPick: {
        var l = root.list;
        if (l.length === 0)
            return null;
        if (preferred && l.indexOf(preferred) >= 0 && preferred.isPlaying)
            return preferred;
        for (var i = 0; i < l.length; i++)
            if (l[i].isPlaying && !isIdle(l[i]))
                return l[i];
        if (preferred && l.indexOf(preferred) >= 0 && !isIdle(preferred))
            return preferred;
        for (var j = 0; j < l.length; j++)
            if (!isIdle(l[j]) && l[j].trackTitle)
                return l[j];
        return l[0];
    }

    readonly property var active: (manualActive && list.indexOf(manualActive) >= 0 && !isIdle(manualActive)) ? manualActive : autoPick

    function select(p) {
        root.manualActive = (p && list.indexOf(p) >= 0) ? p : null;
    }

    Instantiator {
        model: Mpris.players
        delegate: QtObject {
            required property var modelData
            readonly property bool real: modelData && !Players.isProxy(modelData)
            readonly property bool playing: real ? modelData.isPlaying : false
            readonly property string title: real && modelData.trackTitle ? modelData.trackTitle : ""

            onPlayingChanged: {
                if (!Players.ready)
                    return;
                if (playing) {
                    if (!Players.isIdle(modelData) && !Players.otherPlaying(modelData))
                        Players.preferred = modelData;
                    Players.announce(modelData);
                } else if (modelData === Players.active) {
                    Players.announce(modelData);
                }
            }
            /**
             * Browser DRM players (Netflix in Brave) often land their title while
             * isPlaying still reads false and never cleanly toggle it, so the
             * active player announces on any real title, not only mid-playback.
             */
            onTitleChanged: {
                if (Players.ready && title.length > 0 && (playing || modelData === Players.active))
                    Players.announce(modelData);
            }
        }
    }

    readonly property bool has: active !== null
    readonly property bool playing: has && active.isPlaying
    /** Falls back to the service label so a titleless DRM stream still reads as its site. */
    readonly property string title: has ? refineTitle(active, active.trackTitle || labelOf(active)) : ""
    readonly property string artist: has ? Theme.joinArtists(active.trackArtists, active.trackArtist) : ""
    readonly property string trackUrl: urlOf(active)
    readonly property string artUrl: artUrlFor(active)
    readonly property real lengthSec: has && active.length > 0 ? active.length : 0
    /** A bogus near-INT64 length is how live streams report "no end". */
    readonly property bool live: has && (lengthSec <= 0 || lengthSec > 86400)
    readonly property string source: serviceOf(active)
    readonly property string serviceLabel: source.length > 0
        ? source.charAt(0).toUpperCase() + source.slice(1) : ""

    /** Browsers reuse one art path per video, so fold player and title in to catch a new song. */
    function keyFor(p) {
        return p ? ((p.dbusName || "") + "|" + (p.trackTitle || "") + "|" + artUrlFor(p)) : "";
    }
    readonly property string trackKey: has ? keyFor(active) : ""

    /**
     * Fired when a player starts, pauses or changes track in a way worth a flash.
     * The OSD listens and announces that player, even one that is not the active
     * surface source, so starting a video over your music still tells you.
     */
    signal announce(var player)

    function urlOf(p) {
        return (p && p.metadata) ? (p.metadata["xesam:url"] || "") : "";
    }

    function serviceOf(p) {
        if (!p)
            return "";
        var site = siteName(urlOf(p));
        if (site.length === 0)
            site = siteFromTitle(p.trackTitle ? p.trackTitle : "");
        if (site.length > 0)
            return site;
        var n = p.identity ? p.identity : (p.desktopEntry ? p.desktopEntry : "");
        return n.toLowerCase();
    }

    function labelOf(p) {
        var s = serviceOf(p);
        if (s.length > 0)
            return s.charAt(0).toUpperCase() + s.slice(1);
        return p && p.identity ? p.identity : "";
    }

    function nowPlayingFor(p) {
        return p && p.trackTitle ? p.trackTitle : "";
    }

    /**
     * The player's own themed app icon, matched off its desktop entry so any
     * source carries its real logo. Matching is the same window-to-entry pass the
     * tray uses, with a direct icon-theme lookup as the fallback.
     */
    function appIconFor(p) {
        if (!p)
            return "";
        var id = (p.desktopEntry && p.desktopEntry.length > 0) ? p.desktopEntry : (p.identity || "");
        if (id.length === 0)
            return "";
        var apps = DesktopEntries.applications.values;
        for (var i = 0; i < apps.length; i++) {
            var e = apps[i];
            if (e && e.id && e.id.toLowerCase() === id.toLowerCase() && e.icon)
                return Quickshell.iconPath(e.icon, "application-x-executable");
        }
        return Quickshell.iconPath(id.toLowerCase(), "application-x-executable");
    }

    function artUrlFor(p) {
        if (!p)
            return "";
        if (p.trackArtUrl)
            return p.trackArtUrl;
        var u = urlOf(p);
        if (p === active && twitchAvatar.length > 0 && isTwitch(u))
            return twitchAvatar;
        var nid = netflixIdOf(u);
        if (nid.length > 0 && nid === netflixId && netflixArt.length > 0)
            return netflixArt;
        return derivedThumb(u);
    }

    function siteName(url) {
        var m = url.match(/^https?:\/\/(?:www\.)?([^\/]+)/);
        if (!m)
            return "";
        var host = m[1].toLowerCase();
        if (host === "youtu.be")
            return "youtube";
        var parts = host.split(".");
        return parts.length >= 2 ? parts[parts.length - 2] : parts[0];
    }

    /** Browsers with no page url tag the site onto the title ("... | Spotify"); trust only known sites. */
    function siteFromTitle(t) {
        var m = t.match(/[|\-–—]\s*([A-Za-z][A-Za-z0-9]+)\s*$/);
        if (!m)
            return "";
        var s = m[1].toLowerCase();
        var known = { youtube: 1, spotify: 1, twitch: 1, soundcloud: 1, bandcamp: 1 };
        return known[s] ? s : "";
    }

    function youtubeId(url) {
        var m = url.match(/^https?:\/\/(?:www\.|m\.|music\.)?youtube\.com\/watch\?(?:.*&)?v=([\w-]{11})/)
            || url.match(/^https?:\/\/youtu\.be\/([\w-]{11})/);
        return m ? m[1] : "";
    }

    function twitchChannelOf(url) {
        var m = url.match(/^https?:\/\/(?:www\.)?twitch\.tv\/([^\/?#]+)/);
        if (!m)
            return "";
        var ch = m[1].toLowerCase();
        var reserved = { videos: 1, directory: 1, u: 1, p: 1, settings: 1, subscriptions: 1, following: 1, downloads: 1 };
        return reserved[ch] ? "" : ch;
    }

    function isTwitch(url) {
        return twitchChannelOf(url).length > 0;
    }

    function derivedThumb(url) {
        var yid = youtubeId(url);
        if (yid)
            return "https://img.youtube.com/vi/" + yid + "/mqdefault.jpg";
        var ch = twitchChannelOf(url);
        if (ch)
            return "https://static-cdn.jtvnw.net/previews-ttv/live_user_" + ch + "-320x180.jpg";
        return "";
    }

    /**
     * Netflix MPRIS is a stub: xesam:title is the literal page title "Netflix"
     * and there is no art. The public title page still ships og:title/og:image
     * for any video id, so resolve the real show name and its cover async and
     * swap them in wherever the raw metadata would just say "Netflix".
     */
    property string netflixName: ""
    property string netflixArt: ""
    property string netflixId: ""

    function netflixIdOf(url) {
        var m = url.match(/^https?:\/\/(?:www\.)?netflix\.com\/(?:watch|title)\/(\d+)/);
        return m ? m[1] : "";
    }

    function resolveNetflix() {
        var id = netflixIdOf(trackUrl);
        if (id === netflixId)
            return;
        netflixId = id;
        netflixName = "";
        netflixArt = "";
        if (id.length === 0)
            return;
        var xhr = new XMLHttpRequest();
        xhr.timeout = 8000;
        xhr.onreadystatechange = function() {
            if (xhr.readyState !== XMLHttpRequest.DONE || xhr.status !== 200 || root.netflixId !== id)
                return;
            var t = xhr.responseText.match(/property="og:title"\s+content="([^"]+)"|og:title"\s+content="([^"]+)"/);
            var i = xhr.responseText.match(/property="og:image"\s+content="([^"]+)"|og:image"\s+content="([^"]+)"/);
            var name = t ? (t[1] || t[2] || "") : "";
            name = name.replace(/^Watch\s+/i, "").replace(/\s*\|\s*Netflix\s*$/i, "");
            if (name.length > 0)
                root.netflixName = name;
            var img = i ? (i[1] || i[2] || "") : "";
            if (img.indexOf("https:") === 0)
                root.netflixArt = img;
        };
        xhr.open("GET", "https://www.netflix.com/title/" + id);
        xhr.send();
    }

    /** Swaps a stub browser title for the resolved show name where one exists. */
    function refineTitle(p, raw) {
        if (p && netflixId.length > 0 && netflixName.length > 0
            && netflixIdOf(urlOf(p)) === netflixId
            && (!raw || raw === "Netflix"))
            return netflixName;
        return raw;
    }

    /** Twitch exposes no MPRIS art; resolve the streamer avatar async, live preview stands in. */
    property string twitchAvatar: ""
    property string twitchChannel: ""
    onTrackUrlChanged: {
        resolveTwitch();
        resolveNetflix();
    }

    function resolveTwitch() {
        var ch = twitchChannelOf(trackUrl);
        if (ch === twitchChannel)
            return;
        twitchChannel = ch;
        twitchAvatar = "";
        if (ch.length === 0)
            return;
        var xhr = new XMLHttpRequest();
        xhr.onreadystatechange = function() {
            if (xhr.readyState === XMLHttpRequest.DONE && xhr.status === 200) {
                var r = xhr.responseText.trim();
                if (r.indexOf("https:") === 0 && r.length > 12 && root.twitchChannel === ch)
                    root.twitchAvatar = r;
            }
        };
        xhr.open("GET", "https://decapi.me/twitch/avatar/" + ch);
        xhr.send();
    }

    GlobalShortcut {
        appid: "quickshell"
        name: "mediaToggle"
        description: "Play or pause the active media player"
        onPressed: { var a = root.active; if (a && a.canTogglePlaying) a.togglePlaying(); }
    }
    GlobalShortcut {
        appid: "quickshell"
        name: "mediaNext"
        description: "Skip to the next track"
        onPressed: { var a = root.active; if (a && a.canGoNext) a.next(); }
    }
    GlobalShortcut {
        appid: "quickshell"
        name: "mediaPrev"
        description: "Skip to the previous track"
        onPressed: { var a = root.active; if (a && a.canGoPrevious) a.previous(); }
    }
}

pragma Singleton

import QtQuick
import Quickshell
import Quickshell.Io

/**
 * Game mode: one flag that strips Hyprland's eye-candy and quiets the desktop for
 * gaming or deep focus. Entering snapshots the focus flags, forces do-not-disturb
 * and keep-awake on, pauses the visualizer, and runs the visual strip; leaving
 * restores each to what it was before. The strip itself lives in gamemode.sh so
 * the original decoration values survive a pill restart. `Flags.gameMode` is the
 * single source of truth, flipped by the mixer chip, the keybind, or IPC.
 */
Singleton {
    id: root

    readonly property bool active: Flags.gameMode
    readonly property string script: Quickshell.env("HOME") + "/.config/hypr/scripts/gamemode.sh"
    property string pending: ""

    onActiveChanged: active ? root.enter() : root.leave()

    function enter() {
        Flags.gamePrevDnd = Flags.dnd;
        Flags.gamePrevViz = Flags.musicViz;
        Flags.gamePrevAwake = Flags.keepAwake;
        Flags.dnd = true;
        Flags.musicViz = false;
        Flags.keepAwake = true;
        root.run("on");
    }

    function leave() {
        root.run("off");
        Flags.dnd = Flags.gamePrevDnd;
        Flags.musicViz = Flags.gamePrevViz;
        Flags.keepAwake = Flags.gamePrevAwake;
    }

    function run(arg) {
        if (proc.running) {
            root.pending = arg;
            return;
        }
        proc.command = ["bash", root.script, arg];
        proc.running = true;
    }

    Process {
        id: proc
        onExited: {
            if (root.pending.length === 0)
                return;
            var a = root.pending;
            root.pending = "";
            proc.command = ["bash", root.script, a];
            proc.running = true;
        }
    }
}

pragma Singleton
import QtQuick
import Quickshell
import Quickshell.Io

/**
 * Screen-recorder backend, shared by the 録 RECORD surface, the pill's hover
 * cluster record indicator and the record OSD. gpu-screen-recorder is the
 * encoder (cross-vendor nvenc/vaapi/cpu); this singleton owns the capture
 * settings, builds the argv from them, starts and stops the recorder and keeps
 * a live `recording` flag polled from the real process so an externally started
 * or stopped recorder is reflected too.
 *
 * The capture target is chosen at leisure BEFORE any countdown, so the user
 * picks WHAT to record with no recording running yet. The surface calls one of
 * two resolvers, each emitting `targetReady(token)` on a valid pick or
 * `targetAborted()` on cancel: `prepareScreen(name)` resolves synchronously to a
 * monitor connector name (`-w DP-1`, falling back to `-w screen`);
 * `prepareWindow()` feeds the Hyprland client rectangles to `slurp` for one
 * combined Window / Region pick — clicking a window snaps to it, dragging draws
 * a freeform region — and resolves to that `WxH+X+Y` geometry. Only after
 * `targetReady` does the surface run its countdown and call `start(token)`, so
 * the order is pick → countdown → record. Audio uses gsr's device aliases (`default_output` for desktop,
 * `default_input` for the mic) so no device id is ever hardcoded; the surface's
 * faders set the captured level by driving the default sink/source through
 * Pipewire. Stop sends SIGINT, which makes gsr finalise and save the file, then
 * notify-send announces the saved file; a recorder that exits non-zero before it
 * ever started reports its stderr and resets. The on-pill record OSD shows the
 * started/stopped state, so the start is not also pushed as a notification.
 *
 * The output directory is the Flags-persisted `recordDir`, falling back to
 * `$HOME/Videos/Recordings`; `pickDir()` runs a native folder picker (kdialog
 * or zenity) and writes the chosen path back to Flags so the displayed path,
 * Open action and recent list all follow it. A `recording` poll reconciles an
 * externally started or stopped recorder so the state is never stale.
 *
 * The recent list carries a cover thumbnail per clip: `refreshRecent()` first
 * runs the thumb script (ffmpeg extracts a single frame into a cache dir under
 * `$XDG_CACHE_HOME/ricelin/rec-thumbs`, skipping clips already cached) and only
 * then re-reads the list, so each entry's `thumb` path is on disk by the time
 * the filmstrip binds to it. Entries are `{ path, name, mtime, sizeLabel,
 * thumb }`.
 */
Singleton {
    id: root

    readonly property string home: Quickshell.env("HOME")
    readonly property string defaultDir: home + "/Videos/Recordings"
    readonly property string thumbDir: (Quickshell.env("XDG_CACHE_HOME") || (home + "/.cache")) + "/ricelin/rec-thumbs/"
    readonly property string thumbScript: home + "/.config/hypr/scripts/rec-thumbs.sh"
    readonly property string outDir: {
        var d = Flags.recordDir;
        return d && d.length > 0 ? d : defaultDir;
    }

    onOutDirChanged: refreshRecent()

    property int fps: Flags.recordFps
    onFpsChanged: Flags.recordFps = fps
    property string quality: Flags.recordQuality
    onQualityChanged: Flags.recordQuality = quality
    property bool captureCursor: Flags.recordCursor
    onCaptureCursorChanged: Flags.recordCursor = captureCursor
    property bool micOn: Flags.recordMic
    onMicOnChanged: Flags.recordMic = micOn
    property bool desktopOn: Flags.recordDesktop
    onDesktopOnChanged: Flags.recordDesktop = desktopOn

    property bool recording: false
    property bool recorderOpen: false
    property string currentFile: ""
    property var recent: []
    readonly property int recentCount: recent.length

    /**
     * Pre-roll countdown, owned here rather than in the surface so the quick-record
     * keybind flow gets it for free with no surface open. `beginCountdown(token)`
     * runs after any target resolves; at zero the recorder starts. `pendingTarget`
     * holds the resolved capture token across the tick-down. `counting` gates the
     * countdown UI in both the surface action bar and the standalone top toast.
     */
    property int countdown: 0
    readonly property bool counting: countdown > 0
    property string pendingTarget: ""

    /**
     * Standalone quick-capture state, read by both pills. `quickMon` is the focused
     * monitor's connector name the keybind targeted, so only that pill renders the
     * chooser and the countdown toast. `quickChoosing` shows the source chooser;
     * `quickScreenChoosing` the monitor sub-choice. The recorder surface stays out
     * of this entirely.
     */
    property bool quickChoosing: false
    property bool quickScreenChoosing: false
    property string quickMon: ""

    signal targetReady(string token)
    signal targetAborted()

    /**
     * Run the pre-roll for a freshly resolved capture token. Zero countdown starts
     * gsr at once; otherwise the token is parked and the timer ticks it down to the
     * start. Fired from this singleton's own `targetReady`, so every caller — the
     * recorder surface or the quick-record keybind — counts down the same way.
     */
    function beginCountdown(token) {
        pendingTarget = token;
        var n = Flags.recordCountdown;
        if (n > 0) {
            countdown = n;
            cdTimer.restart();
        } else {
            countdown = 0;
            cdTimer.stop();
            start(token);
            pendingTarget = "";
        }
    }

    /**
     * Abort an in-flight pre-roll: stop the timer, clear the countdown and the
     * parked token. Used by a cancelled pick and the surface's tap-to-cancel.
     */
    function cancel() {
        cdTimer.stop();
        countdown = 0;
        pendingTarget = "";
    }

    Timer {
        id: cdTimer
        interval: 1000
        repeat: true
        running: false
        onTriggered: {
            root.countdown -= 1;
            if (root.countdown <= 0) {
                cdTimer.stop();
                root.start(root.pendingTarget);
                root.pendingTarget = "";
            }
        }
    }

    Connections {
        target: root
        function onTargetReady(token) {
            root.beginCountdown(token);
        }
        function onTargetAborted() {
            root.cancel();
        }
    }

    onRecordingChanged: if (recording) {
        cancel();
        quickChoosing = false;
        quickScreenChoosing = false;
    }

    /**
     * Connected monitors as `{ name, w, h, label }` for the Screen sub-chooser.
     * gsr's `-w <name>` records a monitor by its connector name, so the chooser
     * passes the chosen `name` straight into `prepareScreen()`. A single screen
     * needs no chooser; the surface uses the lone entry directly.
     */
    readonly property var monitors: {
        var out = [];
        var sc = Quickshell.screens;
        for (var i = 0; i < sc.length; i++) {
            var s = sc[i];
            out.push({ name: s.name, w: s.width, h: s.height, label: s.name + " · " + s.width + "×" + s.height });
        }
        return out;
    }

    /**
     * gsr quality preset for the surface's quality value. The UI labels Ultra and
     * Lossless above gsr's named presets, so Ultra maps to gsr `very_high` and
     * Lossless to gsr `ultra` (its highest QP quality); gsr has no literal
     * lossless preset.
     */
    readonly property var qualityPreset: ({
        medium: "medium",
        high: "high",
        ultra: "very_high",
        lossless: "ultra"
    })

    function timestamp() {
        return Qt.formatDateTime(new Date(), "yyyy-MM-dd_HH-mm-ss");
    }

    function audioArg() {
        var sources = [];
        if (desktopOn)
            sources.push("default_output");
        if (micOn)
            sources.push("default_input");
        return sources.join("|");
    }

    /**
     * True while a recording is live or a region/window picker is still up, so
     * the surface and the resolvers never stack a second pick on a busy backend.
     */
    readonly property bool picking: windowProc.running
    readonly property bool busy: recording || recProc.running || picking

    /**
     * Resolve a whole-screen target synchronously to a monitor connector name
     * (or `screen` when none was passed) and announce it. No picker runs; the
     * surface chose the screen at leisure already, so the countdown follows.
     */
    function prepareScreen(name) {
        if (busy)
            return;
        targetReady(name && name.length > 0 ? name : "screen");
    }

    /**
     * Feed the Hyprland client rectangles to `slurp` so the user picks at
     * leisure with nothing recording yet: clicking a window snaps to that
     * window, dragging draws a freeform region (one combined Window / Region
     * pick, like a screenshot tool). Announces the chosen `WxH+X+Y` geometry, or
     * aborts on cancel / non-zero exit (the user pressed Escape).
     */
    function prepareWindow() {
        if (busy)
            return;
        windowProc.running = true;
    }

    function buildArgs(captureToken, file) {
        var args = ["gpu-screen-recorder", "-w", captureToken,
                    "-f", String(fps), "-q", qualityPreset[quality] || "high",
                    "-cursor", captureCursor ? "yes" : "no"];
        var a = audioArg();
        if (a.length > 0)
            args = args.concat(["-a", a]);
        args = args.concat(["-o", file]);
        return args;
    }

    /**
     * Begin recording the already-resolved capture token (a monitor name,
     * `screen` or a WxH+X+Y geometry). Builds the output path, ensures the
     * directory exists, then launches gsr.
     */
    function start(captureToken) {
        if (recording || recProc.running)
            return;
        var file = outDir + "/recording_" + timestamp() + ".mp4";
        mkdirProc.command = ["mkdir", "-p", outDir];
        mkdirProc.pendingToken = captureToken;
        mkdirProc.pendingFile = file;
        mkdirProc.running = true;
    }

    function stop() {
        if (!recording)
            return;
        stopProc.command = ["pkill", "-SIGINT", "-f", "(^|/)gpu-screen-recorder"];
        stopProc.running = true;
    }

    /**
     * Re-read the recent list, regenerating any missing cover thumbnails first.
     * The thumb script extracts a frame per clip with ffmpeg into the cache dir
     * (skipping clips whose thumb already exists and is newer) and only then does
     * the list land, so filmstrip delegates never bind to a not-yet-written jpg;
     * a thumb run already in flight is left to finish rather than stacked.
     */
    function refreshRecent() {
        if (thumbProc.running)
            return;
        thumbProc.running = true;
    }

    /**
     * Hide every current clip from the recent list without touching the files:
     * the newest clip's mtime is parked as a persisted watermark and the list is
     * emptied, so refreshes filter out anything at or before it while later
     * recordings still surface. The clips stay on disk in the save folder.
     */
    function clearRecent() {
        var newest = 0;
        for (var i = 0; i < recent.length; i++)
            newest = Math.max(newest, recent[i].mtime);
        Flags.recordClearedBefore = newest;
        recent = [];
    }

    function openFile(path) {
        openProc.command = ["xdg-open", path];
        openProc.running = true;
    }

    function openDir() {
        openProc.command = ["xdg-open", outDir];
        openProc.running = true;
    }

    /**
     * Run a native folder picker (kdialog, else zenity) seeded at the current
     * directory and write the chosen path to Flags so the surface, Open action
     * and recent list all follow it. A cancelled pick prints nothing and leaves
     * the directory unchanged.
     */
    function pickDir() {
        pickProc.command = ["sh", "-c",
            "d=\"$1\"; if command -v kdialog >/dev/null 2>&1; then kdialog --getexistingdirectory \"$d\"; else zenity --file-selection --directory --filename=\"$d/\"; fi",
            "_", outDir];
        pickProc.running = true;
    }

    Process {
        id: openProc
    }

    Process {
        id: pickProc
        stdout: StdioCollector {
            onStreamFinished: {
                var dir = this.text.trim();
                if (dir.length > 0)
                    Flags.recordDir = dir;
            }
        }
    }

    /**
     * Combined Window / Region picker: feeds each Hyprland client's current
     * rectangle to `slurp`, so clicking a window snaps to its `WxH+X+Y` geometry
     * while dragging draws a freeform region. The rectangle is captured
     * statically, so a window moved or resized after the pick is not followed.
     * Empty pick or non-zero exit (Escape) aborts.
     */
    Process {
        id: windowProc
        command: ["sh", "-c", "hyprctl clients -j | jq -r '.[] | \"\\(.at[0]),\\(.at[1]) \\(.size[0])x\\(.size[1])\"' | slurp -f \"%wx%h+%x+%y\""]
        stdout: StdioCollector {
            onStreamFinished: {
                var geom = this.text.trim();
                if (geom.length > 0)
                    root.targetReady(geom);
                else
                    root.targetAborted();
            }
        }
        onExited: function(exitCode) {
            if (exitCode !== 0)
                root.targetAborted();
        }
    }

    Process {
        id: mkdirProc
        property string pendingToken: ""
        property string pendingFile: ""
        onExited: {
            root.currentFile = pendingFile;
            recProc.command = root.buildArgs(pendingToken, pendingFile);
            recProc.running = true;
        }
    }

    /**
     * The live recorder. Its own lifecycle drives `recording` so start/stop UI is
     * immediate instead of waiting up to a poll cycle: onStarted marks running,
     * onExited marks stopped. The poll stays an external reconciler. A clean stop
     * (SIGINT) finalises and exits zero and the saved file is announced; a
     * non-zero exit before it ever reached the recording state means gsr failed to
     * start, so its stderr is surfaced and no save is announced.
     */
    Process {
        id: recProc
        stderr: StdioCollector { id: recErr }
        onStarted: {
            root.recording = true;
        }
        onExited: function(exitCode) {
            root.recording = false;
            if (exitCode !== 0) {
                var msg = recErr.text.trim();
                failProc.command = ["notify-send", "-a", "Ricelin", "-u", "critical",
                    "Recording failed", msg.length > 0 ? msg : "gpu-screen-recorder exited " + exitCode];
                failProc.running = true;
            } else {
                savedProc.running = true;
                Qt.callLater(root.refreshRecent);
            }
        }
    }

    Process {
        id: failProc
    }

    Process {
        id: stopProc
    }

    Process {
        id: savedProc
        command: ["notify-send", "-a", "Ricelin", "Recording saved",
            root.currentFile.substring(root.currentFile.lastIndexOf("/") + 1)]
    }

    Process {
        id: thumbProc
        command: ["sh", root.thumbScript, root.outDir]
        onExited: listProc.running = true
    }

    Process {
        id: listProc
        command: ["sh", "-c",
            "d=\"$1\"; [ -d \"$d\" ] || exit 0; find \"$d\" -maxdepth 1 -type f -name 'recording_*.mp4' -printf '%T@\\t%s\\t%p\\n' | sort -rn | head -n 40",
            "_", root.outDir]
        stdout: StdioCollector {
            onStreamFinished: {
                var lines = this.text.split("\n");
                var out = [];
                for (var i = 0; i < lines.length; i++) {
                    var cols = lines[i].split("\t");
                    if (cols.length < 3)
                        continue;
                    var mtime = parseFloat(cols[0]);
                    if (mtime <= Flags.recordClearedBefore)
                        continue;
                    var path = cols[2];
                    var name = path.substring(path.lastIndexOf("/") + 1);
                    out.push({
                        path: path,
                        name: name,
                        mtime: mtime,
                        sizeLabel: root.humanSize(parseFloat(cols[1])),
                        thumb: root.thumbDir + name.replace(/\.mp4$/, "") + ".jpg"
                    });
                }
                root.recent = out;
            }
        }
    }

    function humanSize(bytes) {
        if (bytes >= 1073741824)
            return (bytes / 1073741824).toFixed(1) + " GB";
        if (bytes >= 1048576)
            return Math.round(bytes / 1048576) + " MB";
        if (bytes >= 1024)
            return Math.round(bytes / 1024) + " KB";
        return bytes + " B";
    }

    /**
     * Poll the real recorder process so the flag tracks gsr started or stopped
     * from anywhere, not just this surface. On a save the recent list re-reads so
     * the new file appears.
     */
    Process {
        id: pollProc
        command: ["pgrep", "-f", "(^|/)gpu-screen-recorder"]
        stdout: StdioCollector {
            onStreamFinished: {
                var running = this.text.trim().length > 0;
                if (running !== root.recording) {
                    root.recording = running;
                    if (!running)
                        Qt.callLater(root.refreshRecent);
                }
            }
        }
    }

    Timer {
        interval: 1000
        running: root.recording || root.recorderOpen
        repeat: true
        onTriggered: if (!pollProc.running) pollProc.running = true
    }

    Component.onCompleted: refreshRecent()
}

pragma Singleton

import QtQuick
import Quickshell
import Quickshell.Io

/**
 * Live audio spectrum service for the rest-pill visualizer.
 * CAVA captures the default sink monitor and outputs normalized 0..1 levels.
 *
 * This service only handles audio data. The visual component is responsible
 * for rendering the centered pill bars.
 */
Singleton {
    id: root

    readonly property int bars: 4 // 5, 7

    property var levels: [0, 0, 0, 0, 0]
    property bool active: false

    property bool available: false
    readonly property bool wanted: Flags.musicViz && available

    readonly property string config:
        "[general]\n"
        + "bars = " + bars + "\n"
        + "framerate = 60\n"
        + "autosens = 0\n"
        + "sensitivity = 3500\n"
        + "[input]\n"
        + "method = pulse\n"
        + "source = auto\n"
        + "[output]\n"
        + "method = raw\n"
        + "raw_target = /dev/stdout\n"
        + "data_format = ascii\n"
        + "ascii_max_range = 1000\n"
        + "bar_delimiter = 59\n"
        + "frame_delimiter = 10\n"
        + "channels = mono\n"
        + "mono_option = average\n"
        + "[smoothing]\n"
        + "noise_reduction = 0.77\n"


    onWantedChanged: {
        cavaProc.running = wanted

        if (!wanted) {
            levels = [0, 0, 0, 0, 0]
            active = false
        }
    }

    onAvailableChanged:
        cavaProc.running = wanted

    Component.onCompleted:
        cavaProc.running = wanted


    Process {
        running: true

        command: [
            "sh",
            "-c",
            "command -v cava >/dev/null 2>&1"
        ]

        onExited: (code) => {
            root.available = code === 0
        }
    }


    Process {
        id: cavaProc

        command: [
            "sh",
            "-c",
            "printf '%s' \"$1\" | cava -p /dev/stdin",
            "_",
            root.config
        ]


        stdout: SplitParser {
            onRead: (line) => {
                if (!line)
                    return

                const parts = line.split(";")
                const frame = []
                let peak = 0

                for (let i = 0; i < root.bars; i++) {
                    const value = Math.max(
                        0,
                        Math.min(
                            1,
                            Number(parseInt(parts[i])) / 1000 || 0
                        )
                    )

                    frame.push(value)

                    if (value > peak)
                        peak = value
                }


                root.levels = frame


                if (peak > 0.02) {
                    root.active = true
                    idle.restart()
                }
            }
        }


        onExited:
            if (root.wanted)
                relaunch.restart()
    }


    Timer {
        id: relaunch

        interval: 1500

        onTriggered:
            if (root.wanted)
                cavaProc.running = true
    }


    Timer {
        id: idle

        interval: 450

        onTriggered: {
            root.active = false
            root.levels = [0, 0, 0, 0, 0]
        }
    }
}

pragma Singleton
import QtQuick
import Quickshell
import Quickshell.Io

/**
 * 灯 Night-light controller over hyprsunset, the Hyprland blue-light filter.
 * Off and On push straight to the running daemon over its IPC, so the screen
 * warms or clears at once with no service flicker. Scheduled mode writes a
 * two-profile hyprsunset.conf and restarts the service, handing the clock to the
 * daemon so the tint flips at the set times on its own and survives a logout.
 * The mode, warmth and the two times all live in Flags, so the pill and a fresh
 * login restore the same state. The service is enabled once at install, which is
 * why nothing here ever starts it; it is already up under the graphical session.
 */
Singleton {
    id: root

    readonly property string confPath: Quickshell.env("HOME") + "/.config/hypr/hyprsunset.conf"

    function clampTemp(t) {
        return Math.max(2200, Math.min(6000, Math.round(t)));
    }

    function nowMin() {
        var d = clock.date;
        return d.getHours() * 60 + d.getMinutes();
    }

    /** True while the clock sits inside the on→off window, with the wrap past midnight handled. */
    function windowOpen() {
        var on = Flags.nightLightOnMin;
        var off = Flags.nightLightOffMin;
        var n = root.nowMin();
        return on <= off ? (n >= on && n < off) : (n >= on || n < off);
    }

    function hhmm(min) {
        var h = Math.floor(min / 60);
        var m = min % 60;
        return h + ":" + (m < 10 ? "0" + m : m);
    }

    /** hyprsunset.conf for the current Flags. Off and On are one all-day profile, Scheduled is two. */
    function buildConf() {
        var out = "max-gamma = 150\n\n";
        if (Flags.nightLightMode === "scheduled") {
            out += "profile {\n    time = " + root.hhmm(Flags.nightLightOnMin)
                + "\n    temperature = " + root.clampTemp(Flags.nightLightTemp) + "\n}\n\n"
                + "profile {\n    time = " + root.hhmm(Flags.nightLightOffMin)
                + "\n    identity = true\n}\n";
        } else if (Flags.nightLightMode === "on") {
            out += "profile {\n    time = 0:00\n    temperature = "
                + root.clampTemp(Flags.nightLightTemp) + "\n}\n";
        } else {
            out += "profile {\n    time = 0:00\n    identity = true\n}\n";
        }
        return out;
    }

    /** The IPC command the current mode and clock resolve to. */
    function desiredCmd() {
        var warm = Flags.nightLightMode === "on"
            || (Flags.nightLightMode === "scheduled" && root.windowOpen());
        return warm
            ? ["hyprctl", "hyprsunset", "temperature", String(root.clampTemp(Flags.nightLightTemp))]
            : ["hyprctl", "hyprsunset", "identity"];
    }

    /**
     * Pushes the resolved state to the live daemon at once. A scrub tick that
     * lands while the prior hyprctl is still running is folded into the trailing
     * re-push in the process exit handler, so the final value always arrives.
     */
    function pushLive() {
        if (ipc.running)
            return;
        ipc.command = root.desiredCmd();
        ipc.running = true;
    }

    property bool pendingRestart: false

    /**
     * Persists conf for the next login and pushes live now. The conf write and
     * the daemon re-arm are both debounced, so a scrub flurry collapses into one
     * write and one restart.
     */
    function commit(restart) {
        if (restart)
            root.pendingRestart = true;
        confTimer.restart();
        root.pushLive();
    }

    /**
     * Re-arm is needed whenever scheduled sits on either side of the change, so
     * the daemon never holds stale profiles that would override the new choice at
     * the next clock boundary. Pure off↔on rides the IPC push alone, since its
     * conf is a single all-day profile that only fires at 0:00.
     */
    function setMode(m) {
        var was = Flags.nightLightMode;
        Flags.nightLightMode = m;
        root.commit(was === "scheduled" || m === "scheduled");
    }

    function setTemp(t) {
        Flags.nightLightTemp = root.clampTemp(t);
        root.commit(Flags.nightLightMode === "scheduled");
    }

    function setOnMin(v) {
        Flags.nightLightOnMin = v;
        root.commit(Flags.nightLightMode === "scheduled");
    }

    function setOffMin(v) {
        Flags.nightLightOffMin = v;
        root.commit(Flags.nightLightMode === "scheduled");
    }

    SystemClock {
        id: clock
        precision: SystemClock.Minutes
    }

    FileView {
        id: writer
        path: root.confPath
        atomicWrites: true
        printErrors: false
    }

    Process {
        id: ipc
        command: []
        onExited: {
            var want = root.desiredCmd();
            if (want.join(" ") !== ipc.command.join(" ")) {
                ipc.command = want;
                ipc.running = true;
            }
        }
    }

    /** Debounced conf write, then a re-arm restart when a scheduled change asked for one. */
    Timer {
        id: confTimer
        interval: 250
        onTriggered: {
            writer.setText(root.buildConf());
            if (root.pendingRestart) {
                root.pendingRestart = false;
                restartProc.running = true;
            }
        }
    }

    Process {
        id: restartProc
        command: ["systemctl", "--user", "restart", "hyprsunset"]
    }
}

pragma Singleton
import QtQuick
import Quickshell
import Quickshell.Io

/**
 * Local calendar events, persisted as a plain JSON array beside the session
 * flags (~/.local/state/ricelin/events.json). The in-memory `events` is the
 * source of truth: add/remove mutate it and write the file, which is read back
 * only at startup. The file is deliberately NOT watched — re-reading our own
 * write races the FileView's cached text and dropped the just-added event (it
 * flashed in, then vanished until the next write). The file holds an array
 * of { id, date, endDate, time, endTime, text, recur } with date/endDate as
 * "YYYY-MM-DD". endDate is "" for a single-day entry, otherwise the last day a
 * multi-day span covers. time and endTime may be "" for an all-day or open-ended
 * entry. Because the keys are zero-padded "YYYY-MM-DD", a plain string compare
 * orders and spans dates correctly, so coverage tests need no Date parsing.
 *
 * recur is "" for a one-off, "year" for a yearly entry (a birthday: shows on its
 * month and day in every year, matched on the "MM-DD" tail) or "month" (shows on
 * its day in every month, matched on the "DD" tail). A recurring entry ignores its
 * endDate. Day 31 monthly and Feb 29 yearly only land where the day exists, which
 * is fine for now. On load, entries written before this field are classified once:
 * a birthday-looking title becomes yearly, the legacy yearly flag folds into recur,
 * the rest stay one-off, and the healed list is persisted so it sticks.
 *
 * A bare array is simpler than a JsonAdapter for a growing list: read the text,
 * JSON.parse, mutate the array, JSON.stringify back through setText. Every parse
 * is guarded so a truncated or corrupt file never throws and never wipes the
 * singleton — a bad read just leaves the last good `events` in place.
 *
 * Ids come from a monotonic counter seeded past the highest id already on disk,
 * never Date.now() or Math.random() (both throw in this engine), so every add is
 * uniquely addressable for remove() even within the same minute.
 */
Singleton {
    id: root

    readonly property string stateDir: (Quickshell.env("XDG_STATE_HOME") || (Quickshell.env("HOME") + "/.local/state")) + "/ricelin"

    property var events: []
    property int nextId: 1

    /**
     * Birthday-looking titles across the languages Erik's contacts use, so a new
     * entry can suggest yearly and old ones get classified on load. Plain substring
     * alternation, case-insensitive; accented forms are caught by a safe stem.
     */
    readonly property var birthdayRe: /geburtstag|geb\.|birthday|b-?day|🎂|cumplea|anniversaire|compleanno|anivers|verjaardag|рожд|誕生|생일|urodziny|do[ğg]um/i

    function isBirthday(t) {
        return root.birthdayRe.test(t || "");
    }

    /**
     * Re-read the file text into `events` and advance the id counter past every
     * id present, so a freshly added event can never collide with one loaded
     * from disk. A FileNotFound or malformed body is treated as an empty list.
     * Entries that predate the recurrence field get classified once and the healed
     * list is written back, so existing birthdays become yearly without a re-entry.
     */
    function reloadEvents() {
        var arr = [];
        try {
            var t = file.text();
            if (t && t.trim().length > 0) {
                var parsed = JSON.parse(t);
                if (Array.isArray(parsed))
                    arr = parsed;
            }
        } catch (e) {
            arr = [];
        }
        var maxId = 0;
        var healed = false;
        for (var i = 0; i < arr.length; i++) {
            var n = Number(arr[i].id);
            if (n > maxId)
                maxId = n;
            var e = arr[i];
            if (e.recur === undefined) {
                e.recur = e.yearly === true ? "year" : (root.isBirthday(e.text) ? "year" : "");
                delete e.yearly;
                healed = true;
            }
        }
        root.nextId = maxId + 1;
        root.events = arr;
        if (healed)
            root.persist();
    }

    function persist() {
        file.setText(JSON.stringify(root.events));
    }

    /** Last day an event covers: its endDate, or its start when single-day. */
    function lastDay(e) {
        return e.endDate && e.endDate.length > 0 ? e.endDate : e.date;
    }

    function covers(e, dateStr) {
        if (e.recur === "year")
            return dateStr.slice(5) === e.date.slice(5);
        if (e.recur === "month")
            return dateStr.slice(8) === e.date.slice(8);
        return dateStr >= e.date && dateStr <= root.lastDay(e);
    }

    /** Events covering `dateStr`, sorted by start time; an empty time sorts first. */
    function forDate(dateStr) {
        var out = root.events.filter(function (e) { return root.covers(e, dateStr); });
        out.sort(function (a, b) {
            var at = a.time || "";
            var bt = b.time || "";
            if (at === bt)
                return 0;
            if (at === "")
                return -1;
            if (bt === "")
                return 1;
            return at < bt ? -1 : 1;
        });
        return out;
    }

    function hasEvents(dateStr) {
        for (var i = 0; i < root.events.length; i++) {
            if (root.covers(root.events[i], dateStr))
                return true;
        }
        return false;
    }

    /** Append an event and persist; reassigns `events` so bindings refresh. */
    function add(dateStr, endDate, time, endTime, text, recur) {
        var next = root.events.slice();
        next.push({
            id: root.nextId,
            date: dateStr,
            endDate: endDate || "",
            time: time || "",
            endTime: endTime || "",
            text: text || "",
            recur: recur || ""
        });
        root.nextId += 1;
        root.events = next;
        root.persist();
    }

    function remove(id) {
        root.events = root.events.filter(function (e) { return e.id !== id; });
        root.persist();
    }

    Component.onCompleted: reloadEvents()

    FileView {
        id: file
        path: root.stateDir + "/events.json"
        blockLoading: true
        printErrors: false

        onLoadFailed: function (error) {
            if (error === FileViewError.FileNotFound)
                file.setText("[]");
        }
    }
}

pragma Singleton
import QtQuick
import Quickshell
import Quickshell.Io

/**
 * Live weather for the pill's hover glance, served by Open-Meteo with no API key.
 * Location resolves once and is cached so a restart never re-hits the network for
 * coordinates: by default the city, latitude and longitude come from a keyless IP
 * lookup (ip-api), but a non-empty `Flags.weatherCity` override geocodes that name
 * via Open-Meteo's geocoder instead. Once coordinates are known the forecast runs
 * immediately and then every 20 minutes, exposing the current conditions plus a
 * 24-hour hourly strip.
 *
 * Everything is async through `Process` + `curl`, mirroring how Sysmon and Devices
 * fetch, so startup never blocks on a slow or absent connection. Every JSON parse
 * is guarded: a partial body or network blip leaves the last good values in place
 * and `ready` simply stays false until the first clean fetch lands.
 *
 * Conditions render as on-brand kanji rather than icons — 晴 clear, 曇 cloud,
 * 雨 rain, 雪 snow, 霧 fog, 雷 thunder, 月 a clear night — keyed off the WMO weather
 * code via `glyphFor`, with `labelFor` giving the short english word.
 */
Singleton {
    id: root

    readonly property string cacheDir: (Quickshell.env("XDG_CACHE_HOME") || (Quickshell.env("HOME") + "/.cache")) + "/ricelin"

    property int tempNow: 0
    property int codeNow: 0
    property int humidity: 0
    property bool isDay: true
    property string city: ""
    property var hourly: []
    property var daily: []
    property bool ready: false

    property real lat: 0
    property real lon: 0
    property bool located: false

    /**
     * Maps a WMO weather code to its on-brand kanji. Clear skies show 月 at night
     * so the glance reads day-versus-night at a glance; every other condition is
     * the same glyph round the clock.
     */
    function glyphFor(code, day) {
        if (code === 0)
            return day ? "sun" : "moon";
        if (code <= 3)
            return "cloud";
        if (code === 45 || code === 48)
            return "cloud-fog";
        if (code >= 95)
            return "cloud-lightning";
        if ((code >= 71 && code <= 77) || code === 85 || code === 86)
            return "cloud-snow";
        if ((code >= 51 && code <= 67) || (code >= 80 && code <= 82))
            return "cloud-rain";
        return "cloud";
    }

    /** Short english word for a WMO weather code, for labels and accessibility. */
    function labelFor(code) {
        if (code === 0)
            return "Clear";
        if (code <= 3)
            return "Cloudy";
        if (code === 45 || code === 48)
            return "Fog";
        if (code >= 95)
            return "Thunder";
        if ((code >= 71 && code <= 77) || code === 85 || code === 86)
            return "Snow";
        if ((code >= 51 && code <= 67) || (code >= 80 && code <= 82))
            return "Rain";
        return "Cloudy";
    }

    /** Persist resolved coordinates so a restart skips the location round-trip. */
    function writeLoc() {
        locCache.setText(JSON.stringify({ city: root.city, lat: root.lat, lon: root.lon }));
    }

    function fetchWeather() {
        if (!located || wxProc.running)
            return;
        wxProc.running = true;
    }

    /**
     * Loads cached coordinates synchronously (blockLoading) and fetches at once;
     * an absent or malformed cache falls through to a fresh location lookup.
     */
    Component.onCompleted: {
        try {
            var c = JSON.parse(locCache.text());
            if (c && typeof c.lat === "number" && typeof c.lon === "number") {
                root.city = c.city || "";
                root.lat = c.lat;
                root.lon = c.lon;
                root.located = true;
                root.fetchWeather();
                return;
            }
        } catch (e) {}
        root.locate();
    }

    FileView {
        id: locCache
        path: root.cacheDir + "/weather-loc.json"
        blockLoading: true
        printErrors: false
    }

    /** Resolve coordinates: geocode the manual city override, else fall back to IP. */
    function locate() {
        if (Flags.weatherCity && Flags.weatherCity.trim().length > 0)
            geoProc.running = true;
        else
            ipProc.running = true;
    }

    Connections {
        target: Flags
        function onWeatherCityChanged() { root.locate(); }
    }

    Process {
        id: ipProc
        command: ["curl", "-s", "--max-time", "8", "http://ip-api.com/json?fields=lat,lon,city"]
        stdout: StdioCollector {
            onStreamFinished: {
                try {
                    var d = JSON.parse(this.text);
                    if (typeof d.lat === "number" && typeof d.lon === "number") {
                        root.city = d.city || "";
                        root.lat = d.lat;
                        root.lon = d.lon;
                        root.located = true;
                        root.writeLoc();
                        root.fetchWeather();
                    }
                } catch (e) {}
            }
        }
    }

    Process {
        id: geoProc
        command: ["curl", "-s", "--max-time", "8", "-G",
            "https://geocoding-api.open-meteo.com/v1/search",
            "--data-urlencode", "name=" + (Flags.weatherCity || ""),
            "--data-urlencode", "count=1"]
        stdout: StdioCollector {
            onStreamFinished: {
                try {
                    var d = JSON.parse(this.text);
                    var r = d.results && d.results[0];
                    if (r && typeof r.latitude === "number" && typeof r.longitude === "number") {
                        root.city = r.name || "";
                        root.lat = r.latitude;
                        root.lon = r.longitude;
                        root.located = true;
                        root.writeLoc();
                        root.fetchWeather();
                    }
                } catch (e) {}
            }
        }
    }

    Process {
        id: wxProc
        command: ["curl", "-s", "--max-time", "10",
            "https://api.open-meteo.com/v1/forecast?latitude=" + root.lat
            + "&longitude=" + root.lon
            + "&current=temperature_2m,weather_code,is_day,relative_humidity_2m"
            + "&hourly=temperature_2m,weather_code&forecast_hours=24"
            + "&daily=weather_code,temperature_2m_max,relative_humidity_2m_mean&forecast_days=5&timezone=auto"]
        stdout: StdioCollector {
            onStreamFinished: {
                try {
                    var d = JSON.parse(this.text);
                    var cur = d.current;
                    if (!cur)
                        return;
                    var rows = [];
                    var h = d.hourly;
                    if (h && h.time && h.temperature_2m && h.weather_code) {
                        var n = Math.min(h.time.length, h.temperature_2m.length, h.weather_code.length);
                        for (var i = 0; i < n; i++) {
                            rows.push({
                                hour: h.time[i].slice(11, 13),
                                temp: Math.round(h.temperature_2m[i]),
                                code: h.weather_code[i]
                            });
                        }
                    }
                    var days = [];
                    var dd = d.daily;
                    if (dd && dd.time && dd.weather_code && dd.temperature_2m_max && dd.relative_humidity_2m_mean) {
                        var dn = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
                        var m = Math.min(dd.time.length, dd.weather_code.length, dd.temperature_2m_max.length, dd.relative_humidity_2m_mean.length);
                        for (var j = 0; j < m; j++) {
                            days.push({
                                day: dn[new Date(dd.time[j]).getDay()],
                                code: dd.weather_code[j],
                                temp: Math.round(dd.temperature_2m_max[j]),
                                rh: Math.round(dd.relative_humidity_2m_mean[j])
                            });
                        }
                    }
                    root.tempNow = Math.round(cur.temperature_2m);
                    root.codeNow = cur.weather_code;
                    root.humidity = Math.round(cur.relative_humidity_2m);
                    root.isDay = cur.is_day === 1;
                    root.hourly = rows;
                    root.daily = days;
                    root.ready = true;
                } catch (e) {}
            }
        }
    }

    Timer {
        interval: 1200000
        running: true
        repeat: true
        onTriggered: root.fetchWeather()
    }
}

