                            cursorShape: Qt.PointingHandCursor
                            onClicked: root.shiftMonth(nav.modelData)
                        }
                    }
                }
            }
        }

        Rectangle {
            id: divider
            anchors.top: header.bottom
            anchors.topMargin: 9 * root.s
            anchors.left: parent.left
            anchors.right: parent.right
            height: 1
            color: Theme.hair
        }

        Row {
            id: weekdays
            anchors.top: divider.bottom
            anchors.topMargin: 8 * root.s
            anchors.left: parent.left
            anchors.right: parent.right

            Repeater {
                model: 7

                Item {
                    id: wd
                    required property int index
                    readonly property bool weekend: index >= 5
                    width: weekdays.width / 7
                    height: 16 * root.s

                    Text {
                        anchors.centerIn: parent
                        text: root.loc.standaloneDayName((wd.index + 1) % 7, Locale.NarrowFormat)
                        color: wd.weekend ? Theme.faint : Theme.dim
                        font.family: Theme.font
                        font.pixelSize: 9 * root.s
                        font.weight: Font.Medium
                        font.letterSpacing: 0.5 * root.s
                    }
                }
            }
        }

        Grid {
            id: grid
            y: weekdays.y + weekdays.height + 4 * root.s
            anchors.left: parent.left
            anchors.right: parent.right
            columns: 7
            rowSpacing: root.rowGap
            columnSpacing: 0

            Repeater {
                model: root.rows * 7

                Item {
                    id: cell
                    required property int index
                    readonly property int weekday: index % 7
                    readonly property bool weekend: weekday >= 5
                    width: grid.width / 7
                    height: root.cellH

                    readonly property int dayNum: index - root.offset + 1
                    readonly property bool inMonth: dayNum >= 1 && dayNum <= root.monthLen
                    readonly property bool current: inMonth && root.isToday(dayNum)
                    readonly property string dayKey: inMonth ? root.dateKey(dayNum) : ""
                    readonly property bool hasEvent: inMonth && Events.hasEvents(cell.dayKey)
                    readonly property bool sel: inMonth && root.inRange(cell.dayKey)
                    readonly property bool selEdge: cell.sel
                        && (cell.dayKey === root.rangeLo || cell.dayKey === root.rangeHi)
                    readonly property int ghostNum: dayNum < 1
                        ? root.daysInMonth(root.viewYear, root.viewMonth - 1) + dayNum
                        : dayNum - root.monthLen

                    Rectangle {
                        anchors.centerIn: parent
                        width: 22 * root.s
                        height: 22 * root.s
                        radius: Motion.rSmall * root.s
                        color: cellArea.containsMouse && cell.inMonth && !cell.current
                            ? Qt.rgba(0.94, 0.88, 0.84, 0.04) : "transparent"
                    }

                    Rectangle {
                        anchors.centerIn: parent
                        width: 24 * root.s
                        height: 24 * root.s
                        radius: Motion.rSmall * root.s
                        visible: cell.current || cell.sel
                        color: cell.sel && !cell.current ? Qt.alpha(Theme.vermLit, 0.12) : Theme.frameBg
                        border.width: 1
                        border.color: cell.selEdge ? Qt.alpha(Theme.vermLit, 0.55)
                            : (cell.sel ? Qt.alpha(Theme.vermLit, 0.22) : Theme.frameBorder)
                    }

                    Text {
                        anchors.centerIn: parent
                        text: cell.inMonth ? cell.dayNum : cell.ghostNum
                        color: cell.inMonth
                            ? (cell.current ? Theme.todayWarm
                                : (cell.hasEvent ? Theme.flameGlow
                                    : (cell.weekend ? Theme.subtle : Theme.cream)))
                            : Theme.ghost
                        opacity: cell.inMonth && !cell.current && !cell.weekend && !cell.hasEvent ? 0.85 : 1.0
                        font.family: Theme.font
                        font.pixelSize: 11 * root.s
                        font.weight: cell.current || cell.hasEvent ? Font.DemiBold : Font.Normal
                        font.features: { "tnum": 1 }
                    }

                    Rectangle {
                        anchors.horizontalCenter: parent.horizontalCenter
                        anchors.top: parent.verticalCenter
                        anchors.topMargin: 9 * root.s
                        visible: cell.hasEvent && !cell.current
                        width: 3 * root.s
                        height: 3 * root.s
                        radius: width / 2
                        color: Theme.flameGlow
                    }

                    MouseArea {
                        id: cellArea
                        anchors.fill: parent
                        hoverEnabled: true
                        enabled: cell.inMonth
                        cursorShape: cell.inMonth ? Qt.PointingHandCursor : Qt.ArrowCursor
                        onClicked: if (cell.inMonth) root.selectDay(cell.dayNum)
                        onContainsMouseChanged: if (root.pickingEnd && cell.inMonth && containsMouse)
                            root.hoverDay = cell.dayNum
                    }
                }
            }
        }

        Text {
            anchors.horizontalCenter: grid.horizontalCenter
            anchors.top: grid.bottom
            anchors.topMargin: 6 * root.s
            visible: root.pickingEnd
            text: "click the end day"
            color: Theme.flameGlow
            font.family: Theme.font
            font.pixelSize: 9 * root.s
            font.weight: Font.DemiBold
            font.letterSpacing: 0.4 * root.s
        }

        MouseArea {
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.top: grid.bottom
            anchors.bottom: parent.bottom
            enabled: root.editorShown && !root.pickingEnd
            onClicked: {
                root.selectedDate = "";
                root.selEndDate = "";
                root.pickingEnd = false;
            }
        }
    }

    Rectangle {
        id: editorSeam
        anchors.left: gridPane.right
        anchors.leftMargin: root.gutter / 2
        anchors.top: parent.top
        anchors.bottom: parent.bottom
        width: 1
        color: Theme.hair
        visible: root.editorShown
        opacity: editor.opacity
    }

    Item {
        id: editor
        anchors.left: gridPane.right
        anchors.leftMargin: root.gutter
        anchors.top: parent.top
        anchors.bottom: parent.bottom
        width: root.editorShown ? root.editorW : 0
        clip: true
        visible: width > 1
        opacity: root.editorShown ? 1 : 0
        Behavior on opacity { NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard } }

        /** Events covering the picked day (a span's start), empty until a day is picked. */
        readonly property var dayEvents: root.selectedDate.length > 0
            ? Events.forDate(root.selectedDate) : []

        /** Single day reads "Mon 9 Jun"; a span reads its range. */
        readonly property string heading: {
            if (root.selectedDate.length === 0)
                return "";
            if (root.selEndDate.length === 0)
                return root.fmtDay(root.selectedDate, true);
            return root.fmtSpan(root.rangeLo, root.rangeHi);
        }

        readonly property string spanLabel: root.selEndDate.length === 0
            ? root.fmtDay(root.selectedDate, false)
            : root.fmtSpan(root.rangeLo, root.rangeHi)

        /** "allday" (default) hides the time fields; "timed" reveals start/end. */
        property string mode: "allday"
        property string startVal: ""
        property string endVal: ""
        property string titleVal: ""

        /**
         * recur is "" / "month" / "year". It suggests yearly by itself once the
         * title reads like a birthday and then stays as the user left it after they
         * work the Repeat toggle by hand (recurManual).
         */
        property string recur: ""
        property bool recurManual: false

        /** Suggest yearly for a birthday title, unless the user already chose. */
        function autoRecur() {
            if (!recurManual)
                recur = Events.isBirthday(titleVal) ? "year" : "";
        }

        function clearForm() {
            startVal = "";
            endVal = "";
            titleVal = "";
            recur = "";
            recurManual = false;
            startField.text = "";
            endField.text = "";
            titleField.text = "";
        }

        /** A time is kept only when it reads as HH:MM, otherwise it drops to an all-day blank. */
        function cleanTime(t) {
            var v = t.trim();
            return /^\d{1,2}:\d{2}$/.test(v) ? v : "";
        }

        /** Add the form's event when a title is set, then reset the inputs. */
        function commit() {
            if (titleVal.trim().length === 0)
                return;
            var t = editor.mode === "timed" ? editor.cleanTime(startVal) : "";
            var e = editor.mode === "timed" ? editor.cleanTime(endVal) : "";
            Events.add(root.selectedDate, editor.recur !== "" ? "" : root.selEndDate,
                       t, e, titleVal.trim(), editor.recur);
            clearForm();
            titleField.forceActiveFocus();
        }

        onWidthChanged: if (width < 1) { clearForm(); mode = "allday"; }

        Column {
            id: edCol
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.top: parent.top
            spacing: 8 * root.s

            Text {
                width: parent.width
                text: editor.heading
                color: Theme.cream
                font.family: Theme.font
                font.pixelSize: 12 * root.s
                font.weight: Font.DemiBold
                font.capitalization: Font.AllUppercase
                font.letterSpacing: 0.8 * root.s
                elide: Text.ElideRight
            }

            Rectangle {
                width: parent.width
                height: 1
                color: Theme.hair
            }

            /** Capped so a day stacked with events scrolls instead of growing the surface. */
            Item {
                width: parent.width
                height: edFlick.height

                Flickable {
                    id: edFlick
                    width: parent.width
                    height: Math.min(edList.implicitHeight, 230 * root.s)
                    contentHeight: edList.implicitHeight
                    clip: true
                    boundsBehavior: Flickable.StopAtBounds
                    onContentHeightChanged: returnToBounds()

                    Column {
                        id: edList
                        width: edFlick.width
                        spacing: 4 * root.s

                        Text {
                            visible: editor.dayEvents.length === 0
                            text: "Nothing yet"
                            color: Theme.faint
                            font.family: Theme.font
                            font.pixelSize: 11 * root.s
                            font.weight: Font.Medium
                            font.italic: true
                        }

                        Repeater {
                            model: editor.dayEvents

                            Rectangle {
                                id: evRow
                                required property var modelData
                                width: edList.width
                                height: evBody.implicitHeight + 12 * root.s
                                radius: Motion.rSmall * root.s
                                color: evArea.hovered ? Theme.frameBg : "transparent"

                                /** "all day" or "09:00–10:00", a date span when multi-day, "every year" when recurring. */
                                readonly property string meta: {
                                    var datePart = "";
                                    if (evRow.modelData.endDate && evRow.modelData.endDate.length > 0)
                                        datePart = root.fmtSpan(evRow.modelData.date, evRow.modelData.endDate);
                                    var t = evRow.modelData.time || "";
                                    var e = evRow.modelData.endTime || "";
                                    var timePart = t.length === 0 ? "all day"
                                        : (e.length > 0 ? t + "–" + e : t);
                                    var base = datePart.length > 0 ? datePart + " · " + timePart : timePart;
                                    var r = evRow.modelData.recur;
                                    if (r === "year") return "every year · " + base;
                                    if (r === "month") return "every month · " + base;
                                    return base;
                                }

                                HoverHandler { id: evArea }

                                Column {
                                    id: evBody
                                    anchors.left: parent.left
                                    anchors.leftMargin: 8 * root.s
                                    anchors.right: evDel.left
                                    anchors.rightMargin: 6 * root.s
                                    anchors.top: parent.top
                                    anchors.topMargin: 6 * root.s
                                    spacing: 2 * root.s

                                    Text {
                                        text: evRow.modelData.text
                                        width: parent.width
                                        color: Theme.cream
                                        font.family: Theme.font
                                        font.pixelSize: 11 * root.s
                                        font.weight: Font.Medium
                                        wrapMode: Text.Wrap
                                        maximumLineCount: 4
                                        elide: Text.ElideRight
                                    }
                                    Text {
                                        text: evRow.meta
                                        width: parent.width
                                        color: Theme.flameGlow
                                        font.family: Theme.font
                                        font.pixelSize: 9 * root.s
                                        font.weight: Font.DemiBold
                                        font.features: { "tnum": 1 }
                                        wrapMode: Text.Wrap
                                        elide: Text.ElideRight
                                    }
                                }

                                Item {
                                    id: evDel
                                    anchors.right: parent.right
                                    anchors.rightMargin: 7 * root.s
                                    anchors.top: parent.top
                                    anchors.topMargin: 7 * root.s
                                    width: 16 * root.s
                                    height: 16 * root.s
                                    opacity: evArea.hovered ? 1 : 0.32
                                    Behavior on opacity { NumberAnimation { duration: Motion.fast } }

                                    GlyphIcon {
                                        anchors.fill: parent
                                        name: "close"
                                        color: delArea.containsMouse ? Theme.vermLit : Theme.iconDim
                                        stroke: 1.6
                                    }

                                    MouseArea {
                                        id: delArea
                                        anchors.fill: parent
                                        anchors.margins: -5 * root.s
                                        hoverEnabled: true
                                        cursorShape: Qt.PointingHandCursor
                                        onClicked: Events.remove(evRow.modelData.id)
                                    }
                                }
                            }
                        }
                    }
                }

                WheelScroller {
                    anchors.fill: parent
                    s: root.s
                    flick: edFlick
                }
            }

            Rectangle {
                width: parent.width
                height: 1
                color: Theme.hair
            }

            Row {
                width: parent.width
                spacing: 8 * root.s

                Item {
                    width: parent.width - addBtn.width - 8 * root.s
                    height: 28 * root.s

                    TextField {
                        id: titleField
                        anchors.fill: parent
                        background: null
                        padding: 0
                        leftPadding: 2 * root.s
                        verticalAlignment: TextInput.AlignVCenter
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 13 * root.s
                        placeholderText: "what's on"
                        placeholderTextColor: Theme.faint
                        selectByMouse: true
                        selectionColor: Theme.verm
                        onTextChanged: { editor.titleVal = text; editor.autoRecur(); }
                        Keys.onReturnPressed: editor.commit()
                    }
                    Rectangle {
                        anchors.left: parent.left
                        anchors.right: parent.right
                        anchors.bottom: parent.bottom
                        height: 1
                        color: Theme.faint
                        opacity: titleField.activeFocus ? 0.7 : 0.2
                        Behavior on opacity { NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard } }
                    }
                }

                Rectangle {
                    id: addBtn
                    anchors.verticalCenter: parent.verticalCenter
                    width: 28 * root.s
                    height: 28 * root.s
                    radius: Motion.rSmall * root.s
                    readonly property bool armed: editor.titleVal.trim().length > 0
                    color: addArea.containsMouse && armed ? Qt.alpha(Theme.vermLit, 0.22)
                        : (armed ? Qt.alpha(Theme.vermLit, 0.12) : Theme.frameBg)
                    border.width: 1
                    border.color: armed ? Qt.alpha(Theme.vermLit, 0.5) : Theme.frameBorder
                    Behavior on color { ColorAnimation { duration: Motion.fast } }

                    Text {
                        anchors.centerIn: parent
                        text: "+"
                        color: addBtn.armed ? Theme.vermLit : Theme.iconDim
                        font.family: Theme.font
                        font.pixelSize: 18 * root.s
                        font.weight: Font.Medium
                    }

                    MouseArea {
                        id: addArea
                        anchors.fill: parent
                        hoverEnabled: true
                        cursorShape: Qt.PointingHandCursor
                        onClicked: editor.commit()
                    }
                }
            }

            SettingsSeg {
                s: root.s
                options: [
                    { label: "All day", value: "allday" },
                    { label: "Timed", value: "timed" }
                ]
                value: editor.mode
                onPicked: (v) => editor.mode = v
            }

            Row {
                width: parent.width
                spacing: 8 * root.s
                visible: editor.mode === "timed"

                Item {
                    width: (parent.width - 8 * root.s) / 2
                    height: 26 * root.s

                    TextField {
                        id: startField
                        anchors.fill: parent
                        background: null
                        padding: 0
                        leftPadding: 2 * root.s
                        verticalAlignment: TextInput.AlignVCenter
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 13 * root.s
                        font.features: { "tnum": 1 }
                        placeholderText: "09:00"
                        placeholderTextColor: Theme.faint
                        inputMethodHints: Qt.ImhPreferNumbers
                        selectByMouse: true
                        selectionColor: Theme.verm
                        onTextChanged: editor.startVal = text
                        Keys.onReturnPressed: editor.commit()
                    }
                    Rectangle {
                        anchors.left: parent.left
                        anchors.right: parent.right
                        anchors.bottom: parent.bottom
                        height: 1
                        color: Theme.faint
                        opacity: startField.activeFocus ? 0.7 : 0.2
                        Behavior on opacity { NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard } }
                    }
                }

                Item {
                    width: (parent.width - 8 * root.s) / 2
                    height: 26 * root.s

                    TextField {
                        id: endField
                        anchors.fill: parent
                        background: null
                        padding: 0
                        leftPadding: 2 * root.s
                        verticalAlignment: TextInput.AlignVCenter
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 13 * root.s
                        font.features: { "tnum": 1 }
                        placeholderText: "until"
                        placeholderTextColor: Theme.faint
                        inputMethodHints: Qt.ImhPreferNumbers
                        selectByMouse: true
                        selectionColor: Theme.verm
                        onTextChanged: editor.endVal = text
                        Keys.onReturnPressed: editor.commit()
                    }
                    Rectangle {
                        anchors.left: parent.left
                        anchors.right: parent.right
                        anchors.bottom: parent.bottom
                        height: 1
                        color: Theme.faint
                        opacity: endField.activeFocus ? 0.7 : 0.2
                        Behavior on opacity { NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard } }
                    }
                }
            }

            SettingsSeg {
                s: root.s
                options: [
                    { label: "Once", value: "" },
                    { label: "Monthly", value: "month" },
                    { label: "Yearly", value: "year" }
                ]
                value: editor.recur
                onPicked: (v) => {
                    editor.recurManual = true;
                    editor.recur = v;
                    if (v !== "") {
                        root.selEndDate = "";
                        root.pickingEnd = false;
                    }
                }
            }

            /**
             * Span control: the chip shows the day or range, the button arms the
             * grid so the next day click closes a span (the under-grid hint and
             * range tint guide it), and ✕ drops a set span back to a single day.
             * Hidden for a recurring entry, which is a single repeating day.
             */
            Row {
                width: parent.width
                spacing: 8 * root.s
                visible: editor.recur === ""

                Rectangle {
                    id: spanChip
                    anchors.verticalCenter: parent.verticalCenter
                    width: parent.width - extendBtn.width - clearSpan.width - 16 * root.s
                    height: 28 * root.s
                    radius: Motion.rSmall * root.s
                    color: Theme.frameBg
                    border.width: 1
                    border.color: Theme.frameBorder

                    Row {
                        anchors.left: parent.left
                        anchors.leftMargin: 9 * root.s
                        anchors.verticalCenter: parent.verticalCenter
                        spacing: 7 * root.s

                        Rectangle {
                            anchors.verticalCenter: parent.verticalCenter
                            width: 9 * root.s
                            height: 9 * root.s
                            radius: 3 * root.s
                            color: Theme.flameGlow
                        }
                        Text {
                            anchors.verticalCenter: parent.verticalCenter
                            text: editor.spanLabel
                            color: root.selEndDate.length > 0 ? Theme.cream : Theme.subtle
                            font.family: Theme.font
                            font.pixelSize: 11 * root.s
                            font.weight: Font.Medium
                            font.features: { "tnum": 1 }
                        }
                    }
                }

                Rectangle {
                    id: extendBtn
                    anchors.verticalCenter: parent.verticalCenter
                    readonly property bool armed: root.pickingEnd
                    width: extendLabel.implicitWidth + 18 * root.s
                    height: 28 * root.s
                    radius: Motion.rSmall * root.s
                    color: armed ? Qt.alpha(Theme.vermLit, 0.14) : Theme.frameBg
                    border.width: 1
                    border.color: armed ? Qt.alpha(Theme.vermLit, 0.5) : Theme.frameBorder
                    Behavior on color { ColorAnimation { duration: Motion.fast } }

                    Text {
                        id: extendLabel
                        anchors.centerIn: parent
                        text: root.pickingEnd ? "pick…" : (root.selEndDate.length > 0 ? "edit" : "+ days")
                        color: extendBtn.armed ? Theme.vermLit : Theme.dim
                        font.family: Theme.font
                        font.pixelSize: 10.5 * root.s
                        font.weight: Font.Bold
                        font.letterSpacing: 0.3 * root.s
                    }

                    MouseArea {
                        anchors.fill: parent
                        cursorShape: Qt.PointingHandCursor
                        onClicked: {
                            if (root.pickingEnd) {
                                root.pickingEnd = false;
                                root.hoverDay = 0;
                            } else {
                                root.selEndDate = "";
                                root.pickingEnd = true;
                            }
                        }
                    }
                }

                Item {
                    id: clearSpan
                    anchors.verticalCenter: parent.verticalCenter
                    width: visible ? 16 * root.s : 0
                    height: 16 * root.s
                    visible: root.selEndDate.length > 0 && !root.pickingEnd

                    GlyphIcon {
                        anchors.fill: parent
                        name: "close"
                        color: clearArea.containsMouse ? Theme.vermLit : Theme.iconDim
                        stroke: 1.6
                    }
                    MouseArea {
                        id: clearArea
                        anchors.fill: parent
                        anchors.margins: -5 * root.s
                        hoverEnabled: true
                        cursorShape: Qt.PointingHandCursor
                        onClicked: root.selEndDate = ""
                    }
                }
            }
        }
    }
}

import QtQuick
import Quickshell.Widgets
import Quickshell.Hyprland
import Quickshell.Services.Pipewire
import qs.services
import qs.components.icons

Item {
    id: root

    property real s: 1.1
    property string screenName: ""
    property bool suppressed: false
    property bool expanded: false
    property bool flashing: false
    property string kind: "volume"
    property bool armed: false
    property bool dirty: false
    property bool cooling: false
    property int holdExtends: 0

    /**
     * The player the current flash speaks for. Normally the active source, but an
     * announce can point it at another player that just started, so a video over
     * your music still gets its own flash without stealing the surface.
     */
    property var pendingSubject: null
    readonly property var subject: pendingSubject ? pendingSubject : Players.active
    readonly property bool subjectHas: subject !== null
    readonly property bool subjectPlaying: subjectHas && subject.isPlaying
    readonly property string subjectTitle: subjectHas ? Players.refineTitle(subject, subject.trackTitle || Players.labelOf(subject)) : ""
    readonly property string subjectArtist: subjectHas ? Theme.joinArtists(subject.trackArtists, subject.trackArtist) : ""
    readonly property string subjectIcon: subjectHas ? Players.appIconFor(subject) : ""

    /** Subject art, live so a cover that lands a beat after the title still resolves; the key forces a reload when a browser reuses one file path. */
    readonly property string liveArt: {
        if (!subjectHas)
            return "";
        var u = Players.artUrlFor(subject);
        if (!u)
            return "";
        return u.indexOf("file:") === 0 ? u + "#" + Players.keyFor(subject) : u;
    }

    readonly property real brightness: Backlight.brightness
    property bool recordStarted: false

    readonly property var sink: Pipewire.defaultAudioSink
    readonly property bool muted: sink && sink.audio ? sink.audio.muted : false
    readonly property real volume: sink && sink.audio ? Math.max(0, Math.min(1, sink.audio.volume)) : 0

    readonly property real desiredW: kind === "workspace" ? Math.max(120 * s, wsIndicator.implicitWidth + 40 * s)
        : (kind === "track" ? 344 * s : (kind === "record" ? 256 * s : 248 * s))
    readonly property real desiredH: kind === "track" ? 64 * s : 44 * s

    /**
     * Active workspace name on this monitor. Any switch (Super+arrow,
     * Super+wheel, clicking a dot) changes it, so flashing the workspace OSD
     * here briefly morphs the pill open to show where you landed. The arm timer
     * swallows the initial populate, so login doesn't flash. Skipped while the
     * pill is expanded: the hover/surface pill already shows the live dots with
     * the active one marked, so the OSD would only be a redundant morph.
     */
    readonly property string activeWsName: {
        var mons = Hyprland.monitors.values;
        for (var i = 0; i < mons.length; i++)
            if (mons[i].name === screenName)
                return mons[i].activeWorkspace ? mons[i].activeWorkspace.name : "";
        return "";
    }
    onActiveWsNameChanged: if (activeWsName.length > 0 && !expanded) flash("workspace");

    /**
     * Wait for the track to settle before flashing. Hovering the YouTube grid
     * autoplays a preview per thumbnail, so the active player's metadata churns
     * as the cursor moves; the settle timer collapses that storm into the one
     * track that actually sticks.
     */
    /**
     * Leading-edge throttle. The first change flashes at once so a real track
     * switch feels instant, then the cooldown mutes the burst that hovering the
     * YouTube grid throws off. Anything that lands during the cooldown, or while
     * the OSD is suppressed (a surface open, the pill pinned), stays `dirty` and
     * fires when the gate opens, so the stashed-player flash still replays.
     */
    function tryShow() {
        if (cooling)
            return;
        if (flash("track")) {
            dirty = false;
            cooling = true;
            cooldownTimer.restart();
        }
    }

    /**
     * Every pill carries its own Osd but the volume/track/battery signals are
     * global, so without this gate one keypress flashes every monitor at once.
     * Workspace flashes skip it: those are already keyed to this screen's own
     * active workspace.
     */
    readonly property bool onFocusedMonitor: !Hyprland.focusedMonitor || Hyprland.focusedMonitor.name === screenName

    function flash(which) {
        if (!armed || suppressed)
            return false;
        if (which !== "workspace" && !onFocusedMonitor)
            return false;
        if (which === "track" && flashing && (kind === "volume" || kind === "brightness"))
            return false;
        if (which === "track")
            holdExtends = 0;
        kind = which;
        flashing = true;
        hideTimer.interval = (which === "battery" || which === "record") ? 2000 : 1800;
        hideTimer.restart();
        return true;
    }

    onSuppressedChanged: {
        if (suppressed) {
            hideTimer.stop();
            flashing = false;
        } else if (dirty) {
            tryShow();
        }
    }

    /** A track announce that lost to live hardware feedback replays once the bar clears. */
    onFlashingChanged: if (!flashing && dirty) tryShow()

    Timer {
        interval: 1500
        running: true
        onTriggered: root.armed = true
    }

    Timer {
        id: cooldownTimer
        interval: 1500
        onTriggered: {
            root.cooling = false;
            if (root.dirty)
                root.tryShow();
        }
    }

    /**
     * Hold a track flash open until its cover decodes, so a cold remote thumbnail
     * that arrives after the base window still gets seen. Capped so a dead art url
     * never pins the OSD.
     */
    Timer {
        id: hideTimer
        interval: 1800
        onTriggered: {
            if (root.kind === "track" && cover.status !== Image.Ready && root.liveArt.length > 0 && root.holdExtends < 5) {
                root.holdExtends++;
                hideTimer.interval = 350;
                hideTimer.restart();
            } else {
                root.flashing = false;
            }
        }
    }

    PwObjectTracker {
        objects: [root.sink].filter(Boolean)
    }

    Connections {
        target: root.sink && root.sink.audio ? root.sink.audio : null
        function onVolumesChanged() { root.flash("volume"); }
        function onMutedChanged() { root.flash("volume"); }
    }

    Connections {
        target: Players
        function onAnnounce(player) {
            root.pendingSubject = player;
            root.dirty = true;
            root.tryShow();
        }
    }

    Connections {
        target: Battery
        enabled: Battery.present
        function onChargingChanged() {
            if (Battery.charging)
                root.flash("battery");
        }
    }

    Connections {
        target: ScreenRec
        function onRecordingChanged() {
            root.recordStarted = ScreenRec.recording;
            root.flash("record");
        }
    }

    Connections {
        target: Backlight
        function onChanged() {
            root.flash("brightness");
        }
    }

    Item {
        id: volRow
        anchors.fill: parent
        opacity: root.kind === "volume" ? 1 : 0
        visible: opacity > 0.01
        Behavior on opacity { NumberAnimation { duration: 150 } }

        GlyphIcon {
            id: volGlyph
            anchors.left: parent.left
            anchors.verticalCenter: parent.verticalCenter
            width: 17 * root.s
            height: 17 * root.s
            name: root.muted ? "speaker-off" : "speaker"
            color: root.muted ? Theme.dim : Theme.iconDim
            stroke: 1.7
        }

        Text {
            id: volPct
            anchors.right: parent.right
            anchors.verticalCenter: parent.verticalCenter
            width: 32 * root.s
            horizontalAlignment: Text.AlignRight
            text: Math.round(root.volume * 100) + "%"
            color: root.muted ? Theme.dim : Theme.cream
            font.family: Theme.font
            font.pixelSize: 11 * root.s
            font.weight: Font.DemiBold
            font.features: { "tnum": 1 }
        }

        Rectangle {
            anchors.left: volGlyph.right
            anchors.leftMargin: 12 * root.s
            anchors.right: volPct.left
            anchors.rightMargin: 12 * root.s
            anchors.verticalCenter: parent.verticalCenter
            height: 4 * root.s
            radius: 2 * root.s
            color: Theme.threadBg

            Rectangle {
                anchors.left: parent.left
                anchors.top: parent.top
                anchors.bottom: parent.bottom
                width: parent.width * root.volume
                radius: parent.radius
                color: root.muted ? Theme.vermDim : Theme.vermLit
                Behavior on width { NumberAnimation { duration: Motion.fast } }
                Behavior on color { ColorAnimation { duration: Motion.fast } }
            }
        }
    }

    Item {
        id: trackRow
        anchors.fill: parent
        opacity: root.kind === "track" ? 1 : 0
        visible: opacity > 0.01
        Behavior on opacity { NumberAnimation { duration: 150 } }

        ClippingRectangle {
            id: coverBox
            anchors.left: parent.left
            anchors.verticalCenter: parent.verticalCenter
            width: 44 * root.s
            height: 44 * root.s
            radius: 9 * root.s
            color: Theme.tileBg

            Image {
                id: cover
                anchors.fill: parent
                source: root.liveArt
                sourceSize: Qt.size(Math.ceil(width * 2), Math.ceil(height * 2))
                fillMode: Image.PreserveAspectCrop
                asynchronous: true
                cache: String(source).indexOf("file:") !== 0
                opacity: status === Image.Ready ? 1 : 0
                /** Art that arrives late still earns a moment on screen, so a cover
                 *  decoded near the end of the flash is actually seen. */
                onStatusChanged: if (status === Image.Ready && root.flashing && root.kind === "track") {
                    hideTimer.interval = 1300;
                    hideTimer.restart();
                }
            }
            GlyphIcon {
                anchors.centerIn: parent
                width: parent.width * 0.42
                height: width
                name: "music"
                color: Theme.subtle
                visible: cover.status !== Image.Ready
            }

            /** The source's own app icon, sat as a small badge on the art corner. */
            Rectangle {
                anchors.right: parent.right
                anchors.bottom: parent.bottom
                anchors.margins: 3 * root.s
                width: 18 * root.s
                height: 18 * root.s
                radius: width / 2
                color: Qt.alpha(Theme.cardBot, 0.8)
                visible: srcIcon.status === Image.Ready

                Image {
                    id: srcIcon
                    anchors.centerIn: parent
                    width: 12 * root.s
                    height: 12 * root.s
                    sourceSize: Qt.size(Math.ceil(width * 2), Math.ceil(height * 2))
                    fillMode: Image.PreserveAspectFit
                    asynchronous: true
                    smooth: true
                    source: root.subjectIcon
                }
            }
        }

        GlyphIcon {
            id: trackCtrl
            anchors.right: parent.right
            anchors.verticalCenter: parent.verticalCenter
            width: 18 * root.s
            height: 18 * root.s
            name: root.subjectPlaying ? "play" : "pause"
            color: root.subjectPlaying ? Theme.vermLit : Theme.iconDim
        }

        Column {
            anchors.left: coverBox.right
            anchors.leftMargin: 12 * root.s
            anchors.right: trackCtrl.left
            anchors.rightMargin: 12 * root.s
            anchors.verticalCenter: parent.verticalCenter
            spacing: 3 * root.s

            Text {
                width: parent.width
                text: root.subjectHas ? root.subjectTitle : "Nothing playing"
                color: Theme.cream
                font.family: Theme.font
                font.pixelSize: 14 * root.s
                font.weight: Font.DemiBold
                maximumLineCount: 1
                elide: Text.ElideRight
            }

            Text {
                width: parent.width
                text: root.subjectArtist
                color: Theme.dim
                font.family: Theme.font
                font.pixelSize: 11 * root.s
                maximumLineCount: 1
                elide: Text.ElideRight
                visible: text.length > 0
            }
        }
    }

    Item {
        id: brightRow
        anchors.fill: parent
        opacity: root.kind === "brightness" ? 1 : 0
        visible: opacity > 0.01
        Behavior on opacity { NumberAnimation { duration: 150 } }

        GlyphIcon {
            id: brightGlyph
            anchors.left: parent.left
            anchors.verticalCenter: parent.verticalCenter
            width: 17 * root.s
            height: 17 * root.s
            name: "sun"
            color: Theme.iconDim
            stroke: 1.7
        }

        Text {
            id: brightPct
            anchors.right: parent.right
            anchors.verticalCenter: parent.verticalCenter
            width: 32 * root.s
            horizontalAlignment: Text.AlignRight
            text: Math.round(root.brightness * 100) + "%"
            color: Theme.cream
            font.family: Theme.font
            font.pixelSize: 11 * root.s
            font.weight: Font.DemiBold
            font.features: { "tnum": 1 }
        }

        Rectangle {
            anchors.left: brightGlyph.right
            anchors.leftMargin: 12 * root.s
            anchors.right: brightPct.left
            anchors.rightMargin: 12 * root.s
            anchors.verticalCenter: parent.verticalCenter
            height: 4 * root.s
            radius: 2 * root.s
            color: Theme.threadBg

            Rectangle {
                anchors.left: parent.left
                anchors.top: parent.top
                anchors.bottom: parent.bottom
                width: parent.width * root.brightness
                radius: parent.radius
                color: Theme.vermLit
                Behavior on width { NumberAnimation { duration: Motion.fast } }
            }
        }
    }

    Item {
        id: batteryRow
        anchors.fill: parent
        opacity: root.kind === "battery" ? 1 : 0
        visible: opacity > 0.01
        Behavior on opacity { NumberAnimation { duration: 150 } }

        GlyphIcon {
            id: battGlyph
            anchors.left: parent.left
            anchors.verticalCenter: parent.verticalCenter
            width: 17 * root.s
            height: 17 * root.s
            name: "bolt"
            color: Theme.flameGlow
            stroke: 1.7
        }

        Text {
            id: battPct
            anchors.right: parent.right
            anchors.verticalCenter: parent.verticalCenter
            width: 40 * root.s
            horizontalAlignment: Text.AlignRight
            text: Battery.pct + "%"
            color: Theme.cream
            font.family: Theme.font
            font.pixelSize: 11 * root.s
            font.weight: Font.DemiBold
            font.features: { "tnum": 1 }
        }

        Rectangle {
            anchors.left: battGlyph.right
            anchors.leftMargin: 12 * root.s
            anchors.right: battPct.left
            anchors.rightMargin: 12 * root.s
            anchors.verticalCenter: parent.verticalCenter
            height: 4 * root.s
            radius: 2 * root.s
            color: Theme.threadBg
            clip: true

            Rectangle {
                id: battFill
                anchors.left: parent.left
                anchors.top: parent.top
                anchors.bottom: parent.bottom
                width: parent.width * Battery.frac
                radius: parent.radius
                gradient: Gradient {
                    orientation: Gradient.Horizontal
                    GradientStop { position: 0.0; color: Theme.vermDeep }
                    GradientStop { position: 1.0; color: Theme.flameGlow }
                }
                Behavior on width { NumberAnimation { duration: Motion.fast } }

                Rectangle {
                    anchors.top: parent.top
                    anchors.bottom: parent.bottom
                    width: 34 * root.s
                    color: "transparent"
                    gradient: Gradient {
                        orientation: Gradient.Horizontal
                        GradientStop { position: 0.0; color: "#00ffffff" }
                        GradientStop { position: 0.5; color: "#55ffe6d6" }
                        GradientStop { position: 1.0; color: "#00ffffff" }
                    }

                    NumberAnimation on x {
                        from: -34 * root.s
                        to: battFill.width
                        duration: 1200
                        loops: Animation.Infinite
                        running: root.kind === "battery" && Battery.charging
                    }
                }
            }
        }
    }

    Item {
        id: workspaceRow
        anchors.fill: parent
        opacity: root.kind === "workspace" ? 1 : 0
        visible: opacity > 0.01
        Behavior on opacity { NumberAnimation { duration: 150 } }

        Workspaces {
            id: wsIndicator
            anchors.centerIn: parent
            screenName: root.screenName
            s: root.s
            gap: 8 * root.s
            enabled: false
        }
    }

    Item {
        id: recordRow
        anchors.fill: parent
        opacity: root.kind === "record" ? 1 : 0
        visible: opacity > 0.01
        Behavior on opacity { NumberAnimation { duration: 150 } }

        Rectangle {
            id: recGlyph
            anchors.left: parent.left
            anchors.verticalCenter: parent.verticalCenter
            width: 13 * root.s
            height: 13 * root.s
            radius: width / 2
            color: root.recordStarted ? Theme.verm : Theme.dim

            SequentialAnimation on opacity {
                running: root.recordStarted && root.kind === "record"
                loops: Animation.Infinite
                NumberAnimation { to: 0.4; duration: 500; easing.type: Easing.InOutSine }
                NumberAnimation { to: 1; duration: 500; easing.type: Easing.InOutSine }
            }
        }

        Text {
            anchors.left: recGlyph.right
            anchors.leftMargin: 13 * root.s
            anchors.right: parent.right
            anchors.verticalCenter: parent.verticalCenter
            text: root.recordStarted ? "Recording started" : "Recording stopped"
            color: Theme.cream
            font.family: Theme.font
            font.pixelSize: 11.5 * root.s
            font.weight: Font.DemiBold
            elide: Text.ElideRight
            maximumLineCount: 1
        }
    }
}

pragma ComponentBehavior: Bound

import QtQuick
import QtQuick.Effects
import Quickshell.Widgets
import qs.services
import qs.modules.pill.surfaces
import qs.components.animation
import qs.components.icons
import qs.modules.pill.surfaces

/**
 * Now-playing card. Album art bleeds edge-to-edge on the left, faded into the
 * card; a blurred copy glows through a near-opaque warm wash behind everything.
 * Right of the cover: title, artist, a dim source/time line, the play/pause
 * seal (奏/休) flanked by 前/次 skips. Playback runs as a brush stroke along the
 * bottom, its painted head the dock for the pill's soul bead. All now-playing
 * data comes from [[Players]]; when two or more players run, the source token
 * glows into a bubble that opens a picker.
 */
PillSurface {
    id: root

    readonly property var player: Players.active
    readonly property bool hasPlayer: player !== null
    readonly property bool playing: Players.playing
    readonly property string title: Players.has && Players.title ? Players.title : "Nothing playing"
    readonly property string artist: Players.artist
    readonly property bool live: Players.live
    readonly property string serviceLabel: Players.serviceLabel

    /**
     * Art only decodes while this monitor's surface is open, keyed on the track
     * so a browser reusing one file path still reloads on a new song. The shared
     * url means every monitor shows the same cover, never a stale neighbour.
     */
    readonly property string coverSource: {
        if (!root.active)
            return "";
        var u = Players.artUrl;
        if (!u)
            return "";
        return u.indexOf("file:") === 0 ? u + "#" + Players.trackKey : u;
    }
    /** Latched on first decode so the fallback glyph doesn't flash back while a track change reloads behind the retained cover. */
    property bool everReady: false
    onCoverSourceChanged: if (coverSource.length === 0) everReady = false

    /** Source picker is open; only reachable when more than one player runs. */
    property bool picking: false
    readonly property bool canPick: Players.pickable.length > 1
    onActiveChanged: if (!active) picking = false
    onCanPickChanged: if (!canPick) picking = false
    onPickingChanged: if (picking) pickFlick.contentX = 0

    readonly property real textX: 144 * s
    readonly property real edgePad: 18 * s
    readonly property color washMid: mix(Theme.cardTop, Theme.cardBot, 0.5)
    property real sealPulse: 0

    function mix(a, b, t) {
        return Qt.rgba(a.r + (b.r - a.r) * t, a.g + (b.g - a.g) * t, a.b + (b.b - a.b) * t, 1);
    }

    onTitleChanged: if (playing && active) pulseAnim.restart()

    Timer {
        interval: 500
        running: root.active && root.playing
        repeat: true
        onTriggered: if (root.player) root.player.positionChanged();
    }

    SequentialAnimation {
        id: pulseAnim
        NumberAnimation { target: root; property: "sealPulse"; to: 1; duration: Motion.fast; easing.type: Motion.easeStandard }
        NumberAnimation { target: root; property: "sealPulse"; to: 0; duration: Motion.standard; easing.type: Motion.easeStandard }
    }

    component KanjiSkip: Item {
        id: skip

        property bool can: false
        property string kanjiText: ""
        property string icon: ""
        signal activated()

        anchors.verticalCenter: parent.verticalCenter
        implicitWidth: Flags.showGlyphs ? kanjiLabel.implicitWidth : 15 * root.s
        implicitHeight: Flags.showGlyphs ? kanjiLabel.implicitHeight : 15 * root.s
        opacity: skip.can ? 1 : 0.4
        Behavior on opacity { NumberAnimation { duration: Motion.fast } }

        Text {
            id: kanjiLabel
            visible: Flags.showGlyphs
            anchors.centerIn: parent
            text: skip.kanjiText
            font.family: Theme.fontJp
            font.pixelSize: 13 * root.s
            color: skipArea.containsMouse ? Theme.cream : Theme.dim
            Behavior on color { ColorAnimation { duration: Motion.fast } }
        }

        GlyphIcon {
            visible: !Flags.showGlyphs
            anchors.centerIn: parent
            width: 15 * root.s
            height: 15 * root.s
            name: skip.icon
            color: skipArea.containsMouse ? Theme.cream : Theme.dim
            Behavior on color { ColorAnimation { duration: Motion.fast } }
        }

        MouseArea {
            id: skipArea
            anchors.fill: parent
            anchors.margins: -6 * root.s
            hoverEnabled: true
            enabled: skip.can
            cursorShape: Qt.PointingHandCursor
            onClicked: skip.activated()
        }
    }

    /** Round album swatch that tags a source, falls back to a warm tile. */
    component ArtDot: ClippingRectangle {
        id: dot
        property string url: ""
        radius: width / 2
        color: Theme.tileBg
        Image {
            anchors.fill: parent
            source: dot.url
            sourceSize: Qt.size(Math.ceil(width * 2), Math.ceil(height * 2))
            fillMode: Image.PreserveAspectCrop
            asynchronous: true
            visible: status === Image.Ready
        }
    }

    ClippingRectangle {
        anchors.fill: parent
        topLeftRadius: Flags.notchStyle ? 0 : 22 * root.s
        topRightRadius: Flags.notchStyle ? 0 : 22 * root.s
        bottomLeftRadius: 22 * root.s
        bottomRightRadius: 22 * root.s

        color: "transparent"

        Image {
            id: bleedSrc
            anchors.fill: parent
            source: root.coverSource
            sourceSize: Qt.size(128, 128)
            fillMode: Image.PreserveAspectCrop
            asynchronous: true
            retainWhileLoading: true
            cache: String(source).indexOf("file:") !== 0
            visible: false
        }

        Rectangle {
            anchors.fill: parent
            gradient: Gradient {
                GradientStop { position: 0.0; color: Qt.alpha(Theme.cardTop, 0.88) }
                GradientStop { position: 1.0; color: Qt.alpha(Theme.cardBot, 0.93) }
            }
        }

        ClippingRectangle {
            id: coverBox

            anchors.left: parent.left
            anchors.verticalCenter: parent.verticalCenter
            anchors.leftMargin: 16 * root.s

            width: parent.height - 32 * root.s
            height: width

            radius: 16 * root.s
            color: Theme.tileBg

            Rectangle {
                anchors.fill: parent
                color: Theme.tileBg
                visible: !root.everReady
            }

            Image {
                id: cover
                anchors.fill: parent
                source: root.coverSource
                sourceSize: Qt.size(Math.ceil(width * 2), Math.ceil(height * 2))
                fillMode: Image.PreserveAspectCrop
                asynchronous: true
                retainWhileLoading: true
                cache: String(source).indexOf("file:") !== 0

                onStatusChanged: {
                    if (status === Image.Ready)
                        root.everReady = true
                }
            }

            GlyphIcon {
                anchors.centerIn: parent
                width: 40 * root.s
                height: width
                name: "music"
                color: Theme.subtle
                visible: !root.everReady
            }
        }
    }

    Column {
        anchors.left: parent.left
        anchors.leftMargin: root.textX
        anchors.right: parent.right
        anchors.rightMargin: root.edgePad
        anchors.top: parent.top
        anchors.topMargin: 24 * root.s
        spacing: 3 * root.s

        Marquee {
            anchors.left: parent.left
            anchors.right: parent.right
            text: root.title
            color: Theme.cream
            pixelSize: 21 * root.s
            weight: Font.DemiBold
            active: root.active
        }

        Marquee {
            anchors.left: parent.left
            anchors.right: parent.right
            text: root.artist
            color: Theme.dim
            pixelSize: 16 * root.s
            active: root.active
            visible: text.length > 0
        }
    }

    Row {
        id: transport
        anchors.right: parent.right
        anchors.rightMargin: root.edgePad
        anchors.bottom: parent.bottom
        anchors.bottomMargin: 24 * root.s
        spacing: 14 * root.s
        opacity: root.picking ? 0 : 1
        enabled: !root.picking
        Behavior on opacity { NumberAnimation { duration: Motion.fast } }

        transform: Translate {
            x: -136 * root.s
        }

        KanjiSkip {
            kanjiText: "前"
            icon: "prev"

            can: root.hasPlayer &&
                 root.player.canGoPrevious

            onActivated: {
                if (root.player)
                    root.player.previous()
            }
        }

        Rectangle {
            id: seal

            anchors.verticalCenter: parent.verticalCenter

            width: 30 * root.s
            height: 30 * root.s

            radius: 7 * root.s

            rotation: -1.5
            scale: 1 + 0.08 * root.sealPulse

            property real sat:
                root.playing ? 1 : 0

            Behavior on sat {
                NumberAnimation {
                    duration: Motion.fast
                    easing.type: Motion.easeStandard
                }
            }

            opacity:
                (sealArea.enabled ? 1 : 0.4) *
                (0.75 + 0.25 * sat)

            Behavior on opacity {
                NumberAnimation {
                    duration: Motion.fast
                }
            }

            border.width: 1

            border.color:
                Qt.alpha(
                    Theme.vermLit,
                    0.4 + 0.4 * root.sealPulse
                )

            gradient: Gradient {
                GradientStop {
                    position: 0.0
                    color: root.mix(
                        Theme.verm,
                        Theme.tileBg,
                        0.55 - 0.27 * seal.sat
                    )
                }

                GradientStop {
                    position: 1.0
                    color: root.mix(
                        Theme.vermDeep,
                        Theme.tileBg,
                        0.55 - 0.27 * seal.sat
                    )
                }
            }

            Text {
                visible: Flags.showGlyphs

                anchors.centerIn: parent

                text: root.playing
                      ? "奏"
                      : "休"

                color: "#ffffff"

                font.family: Theme.fontJp
                font.pixelSize: 16 * root.s
                font.weight: Font.Bold
            }

            GlyphIcon {
                visible: !Flags.showGlyphs

                anchors.centerIn: parent

                width: 15 * root.s
                height: 15 * root.s

                name: root.playing
                      ? "pause"
                      : "play"

                color: "#ffffff"
            }

            MouseArea {
                id: sealArea

                anchors.fill: parent
                anchors.margins: -4 * root.s

                hoverEnabled: true

                enabled: root.hasPlayer &&
                         root.player.canTogglePlaying

                cursorShape: Qt.PointingHandCursor

                onClicked: {
                    if (root.player)
                        root.player.togglePlaying()
                }
            }
        }

        KanjiSkip {
            kanjiText: "次"
            icon: "next"

            can: root.hasPlayer &&
                 root.player.canGoNext

            onActivated: {
                if (root.player)
                    root.player.next()
            }
        }
    }
}

