import QtQuick
import Quickshell
import Quickshell.Hyprland
import qs.services
import qs.components.controls
import qs.components.icons

/**
 * Row of icon buttons for windows parked on Hyprland's `special:minimized`
 * workspace (Super+M). Clicking one moves it back to the focused workspace.
 */
Row {
    id: root

    property real s: 1.1
    property string screenName: ""
    spacing: 8 * s

    /**
     * Resolve the workspace id to restore into: the active workspace of the
     * monitor this pill lives on, so a window reappears on the screen the user
     * clicked, falling back to the focused workspace.
     */
    function restoreWorkspace() {
        var ms = Hyprland.monitors.values;
        for (var i = 0; i < ms.length; i++)
            if (ms[i].name === root.screenName && ms[i].activeWorkspace)
                return ms[i].activeWorkspace.id;
        return Hyprland.focusedWorkspace ? Hyprland.focusedWorkspace.id : 1;
    }

    readonly property var items: {
        var out = [];
        var tl = Hyprland.toplevels.values;
        for (var i = 0; i < tl.length; i++) {
            var t = tl[i];
            if (t && t.workspace && t.workspace.name === "special:minimized")
                out.push(t);
        }
        return out;
    }
    readonly property int count: items.length

    /**
     * Resolve an icon path for a toplevel by matching its window class to a
     * desktop entry id (the class often differs from the icon-theme name), with
     * a direct icon-theme lookup as fallback.
     */
    function iconFor(t) {
        var cls = (t && t.lastIpcObject && t.lastIpcObject.class) ? t.lastIpcObject.class
            : (t && t.wayland && t.wayland.appId ? t.wayland.appId : "");
        if (!cls)
            return "";
        var apps = DesktopEntries.applications.values;
        for (var i = 0; i < apps.length; i++) {
            var e = apps[i];
            if (e && e.id && e.id.toLowerCase() === cls.toLowerCase() && e.icon)
                return Quickshell.iconPath(e.icon, "application-x-executable");
        }
        return Quickshell.iconPath(cls, "application-x-executable");
    }

    Repeater {
        model: root.items

        delegate: Item {
            id: chip
            required property var modelData
            width: 18 * root.s
            height: 18 * root.s

            readonly property string iconSrc: root.iconFor(chip.modelData)

            Image {
                anchors.fill: parent
                sourceSize.width: Math.round(36 * root.s)
                sourceSize.height: Math.round(36 * root.s)
                fillMode: Image.PreserveAspectFit
                asynchronous: true
                smooth: true
                source: chip.iconSrc
                opacity: area.containsMouse ? 1 : 0.78
                Behavior on opacity { NumberAnimation { duration: Motion.fast } }
            }

            MouseArea {
                id: area
                anchors.fill: parent
                anchors.margins: -3 * root.s
                hoverEnabled: true
                cursorShape: Qt.PointingHandCursor
                onClicked: {
                    var addr = chip.modelData.address;
                    if (addr.indexOf("0x") !== 0)
                        addr = "0x" + addr;
                    Hyprland.dispatch('hl.dsp.window.move({ workspace = ' + root.restoreWorkspace() + ', window = "address:' + addr + '" })');
                }
            }

            Tooltip {
                s: root.s
                placement: "below"
                title: chip.modelData.title
                show: area.containsMouse
            }
        }
    }
}

import QtQuick
import QtQuick.Controls
import qs.services
import qs.components.animation

Item {
    id: root

    width: 320
    height: 64

    property bool ameEnabled: false
    property var pillRef: null

    property int selectedIndex: 7
    property date selectedDate: new Date()

    ListModel {
        id: calendarModel

        Component.onCompleted: {
            const days = [
                "Sunday",
                "Monday",
                "Tuesday",
                "Wednesday",
                "Thursday",
                "Friday",
                "Saturday"
            ]

            let today = new Date()
            today.setHours(0, 0, 0, 0)

            for (let i = -7; i <= 14; ++i) {
                let d = new Date(today)
                d.setDate(today.getDate() + i)

                append({
                    timestamp: d.getTime(),
                    weekday: days[d.getDay()],
                    day: d.getDate(),
                    month: Qt.locale().monthName(
                        d.getMonth(),
                        Locale.ShortFormat
                    )
                })
            }

            root.selectedIndex = 7
            root.selectedDate = new Date(
                get(7).timestamp
            )

            wheel.currentIndex = 7
        }
    }

    Rectangle {
        anchors.left: parent.left
        width: 32
        height: parent.height
        z: 0

        gradient: Gradient {
            GradientStop {
                position: 0
                color: Theme.tileBg
            }

            GradientStop {
                position: 1
                color: Qt.alpha(Theme.tileBg, 0)
            }
        }
    }

    Rectangle {
        anchors.right: parent.right
        width: 32
        height: parent.height
        z: 0

        gradient: Gradient {
            GradientStop {
                position: 0
                color: Qt.alpha(Theme.tileBg, 0)
            }

            GradientStop {
                position: 1
                color: Theme.tileBg
            }
        }
    }

    ListView {
        id: wheel

        anchors.fill: parent
        z: 1

        orientation: ListView.Horizontal
        model: calendarModel

        spacing: 10

        readonly property real delegateWidth: 40
        readonly property real centerPadding: (width - delegateWidth) / 2

        leftMargin: centerPadding
        rightMargin: centerPadding

        snapMode: ListView.SnapOneItem
        highlightRangeMode: ListView.StrictlyEnforceRange

        preferredHighlightBegin: centerPadding
        preferredHighlightEnd: centerPadding

        Behavior on currentIndex {
            NumberAnimation {
                duration: 450
                easing.type: Easing.OutBack
                easing.overshoot: 0.8
            }
        }

        delegate: Item {
            id: dayDelegate

            width: wheel.delegateWidth
            height: wheel.height

            readonly property bool selected:
                index === wheel.currentIndex

            readonly property real distance:
                Math.abs(wheel.currentIndex - index)

            readonly property bool nextDay:
                index > wheel.currentIndex &&
                distance === 1

            scale: selected ? 1.0 : 0.9

            Behavior on scale {
                NumberAnimation {
                    duration: 150
                }
            }


            Column {
                anchors.centerIn: parent

                /**
                 * Current date stays centered.
                 * All side dates share the same lowered baseline.
                 */
                anchors.verticalCenterOffset: dayDelegate.selected ? 0 : 6
                spacing: 2

                Text {
                    anchors.horizontalCenter: parent.horizontalCenter
                    text: dayDelegate.selected ? model.weekday : model.weekday.charAt(0)

                    color: {
                        if (dayDelegate.selected)
                            return Theme.cream

                        if (dayDelegate.nextDay)
                            return Theme.vermLit

                        if (dayDelegate.distance === 1)
                            return Theme.subtle

                        return Theme.dim
                    }

                    font.family: Theme.font

                    font.pixelSize: dayDelegate.selected
                                     ? 11
                                     : 10

                    font.weight: dayDelegate.selected
                                  ? Font.Bold
                                  : Font.Medium

                    horizontalAlignment: Text.AlignHCenter
                }

                Text {
                    anchors.horizontalCenter: parent.horizontalCenter

                    text: model.day

                    color: {
                        if (dayDelegate.selected)
                            return Theme.bright

                        if (dayDelegate.nextDay)
                            return Theme.vermLit

                        if (dayDelegate.distance === 1)
                            return Theme.subtle

                        return Theme.dim
                    }

                    font.family: Theme.font

                    font.pixelSize: dayDelegate.selected
                                     ? 18
                                     : 15

                    font.weight: dayDelegate.selected
                                  ? Font.Black
                                  : Font.DemiBold

                    font.features: {
                        "tnum": 1
                    }

                    horizontalAlignment: Text.AlignHCenter
                }
            }

            MouseArea {
                anchors.fill: parent

                hoverEnabled: true

                onContainsMouseChanged: {
                    if (containsMouse && root.pillRef)
                        root.pillRef.soulTarget = "calendar"
                }

                onClicked: {
                    wheel.currentIndex = index
                }
            }
        }

        onCurrentIndexChanged: {
            if (currentIndex >= 0 &&
                currentIndex < calendarModel.count) {

                root.selectedIndex = currentIndex

                root.selectedDate =
                    new Date(
                        calendarModel.get(currentIndex).timestamp
                    )
            }
        }
    }
}

pragma ComponentBehavior: Bound

import QtQuick
import Quickshell
import Quickshell.Io
import qs.services


/**
 * 錠 IDLE / LOCK sub-surface: the three idle timeouts that drive hypridle, each
 * held in minutes (0 = off). Auto-lock runs the lock script, screen-off blanks
 * the display through DPMS, and suspend sleeps the machine. Any pick regenerates
 * the whole hypridle.conf from the current values and restarts hypridle, so the
 * change lands without a hand edit. Keep-awake in the mixer already inhibits the
 * Wayland idle notification, which pauses every listener while it is on, so this
 * surface never touches that wiring. Reached from the settings index and morphs
 * back to it on an empty click or the back chevron.
 */
SettingsSurface {
    id: root

    backSurface: "settings"
    implicitHeight: content.implicitHeight

    readonly property string confPath: Quickshell.env("HOME") + "/.config/hypr/hypridle.conf"
    readonly property string lockScript: Quickshell.env("HOME") + "/.config/hypr/scripts/lock.sh"

    readonly property var lockOptions: [
        { label: "Off", value: 0 }, { label: "1 min", value: 1 }, { label: "3 min", value: 3 },
        { label: "5 min", value: 5 }, { label: "10 min", value: 10 }, { label: "15 min", value: 15 }
    ]
    readonly property var screenOptions: [
        { label: "Off", value: 0 }, { label: "3 min", value: 3 }, { label: "5 min", value: 5 },
        { label: "10 min", value: 10 }, { label: "15 min", value: 15 }
    ]
    readonly property var suspendOptions: [
        { label: "Off", value: 0 }, { label: "15 min", value: 15 },
        { label: "30 min", value: 30 }, { label: "60 min", value: 60 }
    ]

    rows: [
        { item: lockRow, kind: "seg", vals: root.lockOptions.map(function (o) { return o.value; }), get: function () { return Flags.idleLockMin; }, set: function (v) { Flags.idleLockMin = v; root.apply(); } },
        { item: screenRow, kind: "seg", vals: root.screenOptions.map(function (o) { return o.value; }), get: function () { return Flags.idleScreenOffMin; }, set: function (v) { Flags.idleScreenOffMin = v; root.apply(); } },
        { item: suspendRow, kind: "seg", vals: root.suspendOptions.map(function (o) { return o.value; }), get: function () { return Flags.idleSuspendMin; }, set: function (v) { Flags.idleSuspendMin = v; root.apply(); } }
    ]

    /**
     * Builds the full hypridle.conf from the three flag values. The general block
     * is always present; a listener block is appended only for each non-zero
     * timeout, in the order lock, screen-off, suspend. Minutes are written out as
     * seconds.
     */
    function buildConf() {
        var out = "general {\n"
            + "    lock_cmd = " + root.lockScript + "\n"
            + "    before_sleep_cmd = loginctl lock-session\n"
            + "    after_sleep_cmd = hyprctl dispatch dpms on\n"
            + "}\n";

        if (Flags.idleLockMin > 0)
            out += "\nlistener {\n"
                + "    timeout = " + (Flags.idleLockMin * 60) + "\n"
                + "    on-timeout = " + root.lockScript + "\n"
                + "}\n";

        if (Flags.idleScreenOffMin > 0)
            out += "\nlistener {\n"
                + "    timeout = " + (Flags.idleScreenOffMin * 60) + "\n"
                + "    on-timeout = hyprctl dispatch dpms off\n"
                + "    on-resume = hyprctl dispatch dpms on\n"
                + "}\n";

        if (Flags.idleSuspendMin > 0)
            out += "\nlistener {\n"
                + "    timeout = " + (Flags.idleSuspendMin * 60) + "\n"
                + "    on-timeout = systemctl suspend\n"
                + "}\n";

        return out;
    }

    function apply() {
        confWriter.setText(buildConf());
        restartProc.running = true;
    }

    FileView {
        id: confWriter
        path: root.confPath
        atomicWrites: true
        printErrors: false
    }

    Process {
        id: restartProc
        command: ["systemctl", "--user", "restart", "hypridle"]
    }

    /**
     * One idle row: name and caption on their own full-width line with the
     * segmented control stacked below, so a six-option strip never squeezes the
     * caption into a narrow wrapping column. Hover lights the row and feeds the
     * soul seam, matching the rest of the settings rows.
     */
    component IdleRow: Item {
        id: irow
        property string name: ""
        property string caption: ""
        property bool last: false
        default property alias seg: segSlot.data
        readonly property real s: root.s

        width: parent ? parent.width : 0
        height: col.implicitHeight + 22 * irow.s

        HoverHandler {
            id: ih
            onHoveredChanged: root.reportRowHover(irow, hovered)
        }

        Rectangle {
            anchors.fill: parent
            anchors.topMargin: 3 * irow.s
            anchors.bottomMargin: 3 * irow.s
            radius: 9 * irow.s
            color: (ih.hovered || root.focusRowItem === irow) ? Theme.frameBg : "transparent"
            Behavior on color { ColorAnimation { duration: Motion.fast } }
        }

        Column {
            id: col
            anchors.left: parent.left
            anchors.right: parent.right
            anchors.leftMargin: 12 * irow.s
            anchors.rightMargin: 12 * irow.s
            anchors.verticalCenter: parent.verticalCenter
            spacing: 3 * irow.s

            Text {
                text: irow.name
                color: Theme.cream
                font.family: Theme.font
                font.pixelSize: 12.5 * irow.s
                font.weight: Font.DemiBold
            }
            Text {
                width: parent.width
                visible: irow.caption.length > 0
                text: irow.caption
                color: Theme.faint
                font.family: Theme.font
                font.pixelSize: 10.5 * irow.s
            }
            Item { width: 1; height: 7 * irow.s }
            Item {
                id: segSlot
                width: childrenRect.width
                height: childrenRect.height
            }
        }

        Rectangle {
            anchors.bottom: parent.bottom
            anchors.left: parent.left
            anchors.right: parent.right
            height: 1
            color: Theme.hairSoft
            visible: !irow.last
        }
    }

    Column {
        id: content
        anchors.top: parent.top
        anchors.left: parent.left
        anchors.right: parent.right
        spacing: 0

        SettingsHeader {
            s: root.s
            glyph: "錠"
            title: "IDLE / LOCK"
            showBack: true
        }

        Item { width: 1; height: 12 * root.s }

        IdleRow {
            id: lockRow
            name: "Auto-lock"
            caption: "Lock the screen after idle"

            SettingsSeg {
                s: root.s
                flushLeft: true
                options: root.lockOptions
                value: Flags.idleLockMin
                onPicked: (v) => { Flags.idleLockMin = v; root.apply(); }
            }
        }

        IdleRow {
            id: screenRow
            name: "Screen off"
            caption: "Blank the display after idle"

            SettingsSeg {
                s: root.s
                flushLeft: true
                options: root.screenOptions
                value: Flags.idleScreenOffMin
                onPicked: (v) => { Flags.idleScreenOffMin = v; root.apply(); }
            }
        }

        IdleRow {
            id: suspendRow
            name: "Suspend"
            caption: "Sleep the machine after idle"
            last: true

            SettingsSeg {
                s: root.s
                flushLeft: true
                options: root.suspendOptions
                value: Flags.idleSuspendMin
                onPicked: (v) => { Flags.idleSuspendMin = v; root.apply(); }
            }
        }

        Text {
            topPadding: 12 * root.s
            leftPadding: 12 * root.s
            rightPadding: 12 * root.s
            width: parent.width
            text: "Keep-awake (in the mixer) pauses all of this while it is on."
            color: Theme.faint
            font.family: Theme.font
            font.pixelSize: 9.5 * root.s
            font.weight: Font.Medium
            wrapMode: Text.WordWrap
        }

        Item { width: 1; height: 10 * root.s }
    }
}

data.initialContent:
pragma ComponentBehavior: Bound

import QtQuick
import QtQuick.Shapes
import Quickshell.Io
import Quickshell.Widgets
import Quickshell.Services.Pipewire
import qs.services
import qs.modules.controlcenter
import qs.modules.settings
import qs.components.animation
import qs.components.controls
import qs.components.icons
import qs.modules.pill.surfaces

/**
 * 録 RECORD surface: drives gpu-screen-recorder through the ScreenRec singleton,
 * built as a flat washi "capture card". The header carries the kanji, label and
 * a status slot (Idle / pulsing dot + elapsed m:ss / Get ready). A tappable
 * config stage shows the recording spec and folds open an options drawer (Frame
 * rate / Quality MiniSegs and a Capture-cursor toggle). A full-width flame action
 * bar starts, counts down and stops the capture; two compact audio rows expose
 * the captured mic and desktop levels on flat-tick faders; a horizontal filmstrip
 * lists recent clips.
 *
 * The flow is chill: the user picks WHAT to record at leisure with nothing
 * recording yet, THEN a pre-roll countdown runs, THEN gsr records. Pressing while
 * idle opens an in-surface source chooser with two choices — Screen and Window /
 * Region. Screen resolves to a monitor (a sub-chooser of the connected screens
 * when more than one) via ScreenRec.prepareScreen; Window / Region feeds the
 * Hyprland client rectangles to slurp (prepareWindow) so a click snaps to a
 * window and a drag draws a freeform region, captured as a static rectangle.
 * Either resolves to ScreenRec.targetReady(token), at which point the
 * Flags.recordCountdown countdown runs (the bar fills over it, tap cancels) and
 * then gsr starts. Zero countdown starts at once; a cancelled pick aborts
 * cleanly. Pressing while recording stops and saves. Audio faders drive the
 * default Pipewire sink and source levels, matching what gsr captures via its
 * default_output / default_input aliases.
 */
PillSurface {
    id: root

    mTop: 13
    mLeft: 16
    mRight: 16
    mBottom: 13

    implicitHeight: content.implicitHeight

    property string screenName: ""

    readonly property var sink: Pipewire.defaultAudioSink
    readonly property var source: Pipewire.defaultAudioSource

    readonly property int countdown: ScreenRec.countdown
    readonly property bool counting: ScreenRec.counting
    property int elapsed: 0

    property bool drawerOpen: false
    property bool chooserOpen: false
    property bool screenChooserOpen: false

    /**
     * Audio-fader keyboard focus index: 0 mic, 1 desktop, -1 none. Only an
     * enabled (toggled-on) fader accepts the focus; the host's hover and arrow
     * keys set it.
     */
    property int faderFocus: -1

    readonly property point recPoint: {
        void root.width;
        void root.height;
        return recDot.mapToItem(root, recDot.width / 2, recDot.height / 2);
    }

    ameForm: (open && !root.counting && !ScreenRec.recording) ? "dock" : "off"
    amePoint: recPoint

    readonly property string qualityLabel: {
        var q = ScreenRec.quality;
        return q.charAt(0).toUpperCase() + q.slice(1);
    }

    readonly property string stageTitle: ScreenRec.recording ? "Recording" : "Screen recorder"

    readonly property string stageSpec: ScreenRec.fps + " fps · " + root.qualityLabel

    /** Deletes one clip file (argv form, no shell), then re-reads the strip. */
    Process {
        id: rmClipProc
        onExited: ScreenRec.refreshRecent()
    }

    function fmtTime(sec) {
        var m = Math.floor(sec / 60);
        var s = sec % 60;
        return m + ":" + (s < 10 ? "0" + s : s);
    }

    function press() {
        if (ScreenRec.recording) {
            ScreenRec.stop();
            return;
        }
        if (counting) {
            ScreenRec.cancel();
            return;
        }
        if (chooserOpen) {
            chooserOpen = false;
            screenChooserOpen = false;
            return;
        }
        chooserOpen = true;
        screenChooserOpen = false;
    }

    /**
     * A source tile was picked in the chooser. Screen with several monitors opens
     * the monitor sub-chooser; otherwise each source kicks off its resolver
     * (which counts down once the target is ready), then the chooser closes.
     */
    function chooseSource(kind) {
        if (kind === "screen") {
            if (ScreenRec.monitors.length > 1) {
                screenChooserOpen = true;
                return;
            }
            ScreenRec.prepareScreen(root.screenName);
        } else if (kind === "window") {
            ScreenRec.prepareWindow();
        }
        chooserOpen = false;
        screenChooserOpen = false;
    }

    function pickMonitor(name) {
        chooserOpen = false;
        screenChooserOpen = false;
        ScreenRec.prepareScreen(name);
    }

    /**
     * Step the focused audio fader by `deltaPct`; returns true when an enabled
     * fader consumed it. Mirrors the mixer's stepFocused so the host can route
     * scroll-wheel and arrow keys here.
     */
    function stepFocused(deltaPct) {
        if (faderFocus === 0 && ScreenRec.micOn && root.source && root.source.audio) {
            root.source.audio.volume = Math.max(0, Math.min(1, root.source.audio.volume + deltaPct / 100));
            return true;
        }
        if (faderFocus === 1 && ScreenRec.desktopOn && root.sink && root.sink.audio) {
            root.sink.audio.volume = Math.max(0, Math.min(1, root.sink.audio.volume + deltaPct / 100));
            return true;
        }
        return false;
    }

    PwObjectTracker {
        objects: [root.sink, root.source].filter(Boolean)
    }

    onActiveChanged: {
        ScreenRec.recorderOpen = active;
        if (active) {
            ScreenRec.refreshRecent();
            faderFocus = -1;
            drawerOpen = false;
            chooserOpen = false;
            screenChooserOpen = false;
        } else {
            chooserOpen = false;
            screenChooserOpen = false;
        }
    }

    Timer {
        id: elapsedTimer
        interval: 1000
        repeat: true
        running: ScreenRec.recording
        onTriggered: root.elapsed += 1
    }

    Connections {
        target: ScreenRec
        function onRecordingChanged() {
            if (ScreenRec.recording) {
                root.elapsed = 0;
                root.drawerOpen = false;
                root.chooserOpen = false;
                root.screenChooserOpen = false;
            }
        }
    }

    /**
     * Mini-segmented choice control, copied from Settings: `options` is a list of
     * `{ label, value }`; the pill whose value equals `value` lights with a solid
     * card-top fill and cream text. Picking a pill emits `picked(value)`.
     */
    component MiniSeg: Rectangle {
        id: seg
        property var options: []
        property var value
        signal picked(var value)

        readonly property real pad: 2 * root.s

        width: pills.implicitWidth + 2 * pad
        height: pills.implicitHeight + 2 * pad
        radius: 9 * root.s
        color: "transparent"

        Row {
            id: pills
            anchors.centerIn: parent
            spacing: 2 * root.s

            Repeater {
                model: seg.options

                Rectangle {
                    id: opt
                    required property var modelData
                    readonly property bool current: seg.value === modelData.value

                    width: optLabel.implicitWidth + 18 * root.s
                    height: optLabel.implicitHeight + 12 * root.s
                    radius: 7 * root.s
                    color: opt.current ? Theme.cardTop : "transparent"
                    Behavior on color { ColorAnimation { duration: Motion.fast } }

                    Text {
                        id: optLabel
                        anchors.centerIn: parent
                        text: opt.modelData.label
                        color: opt.current ? Theme.cream : Theme.subtle
                        font.family: Theme.font
                        font.pixelSize: 10.5 * root.s
                        font.weight: Font.Bold
                        font.letterSpacing: 0.3 * root.s
                    }

                    MouseArea {
                        anchors.fill: parent
                        cursorShape: Qt.PointingHandCursor
                        onClicked: seg.picked(opt.modelData.value)
                    }
                }
            }
        }
    }

    /**
     * One options-drawer line: a cream label on the left and a control pushed to
     * the right, capped by a top hairline on every row but the first.
     */
    component ORow: Item {
        id: orow
        property string name: ""
        property bool first: false
        default property alias control: controlSlot.data

        width: parent ? parent.width : 0
        height: 35 * root.s

        Rectangle {
            anchors.top: parent.top
            anchors.left: parent.left
            anchors.right: parent.right
            height: 1
            color: Theme.hairSoft
            visible: !orow.first
        }

        Text {
            anchors.left: parent.left
            anchors.verticalCenter: parent.verticalCenter
            text: orow.name
            color: Theme.cream
            font.family: Theme.font
            font.pixelSize: 12 * root.s
            font.weight: Font.DemiBold
        }

        Item {
            id: controlSlot
            anchors.right: parent.right
            anchors.verticalCenter: parent.verticalCenter
            width: childrenRect.width
            height: childrenRect.height
        }
    }

    /**
     * Compact audio row: a glyph, a label, a flat-tick fader and a percent
     * readout. The fader dims and stops accepting input when its audio is off.
     */
    component AudioRow: Item {
        id: arow
        property string glyph: ""
        property string name: ""
        property bool on: false
        property int faderIndex: -1
        property real level: 0.5
        signal toggled()
        signal faderMoved(real v)

        width: parent ? parent.width : 0
        height: 27 * root.s

        GlyphIcon {
            id: rowGlyph
            anchors.left: parent.left
            anchors.verticalCenter: parent.verticalCenter
            width: 16 * root.s
            height: 16 * root.s
            name: arow.glyph
            color: arow.on ? Theme.vermLit : Theme.iconDim
            stroke: 1.7
        }

        Text {
            id: rowName
            anchors.left: rowGlyph.right
            anchors.leftMargin: 11 * root.s
            anchors.verticalCenter: parent.verticalCenter
            width: 76 * root.s
            text: arow.name
            color: arow.on ? Theme.cream : Theme.subtle
            font.family: Theme.font
            font.pixelSize: 11.5 * root.s
            font.weight: Font.DemiBold
            elide: Text.ElideRight
        }

        HFader {
            id: fader
            anchors.left: rowName.right
            anchors.leftMargin: 4 * root.s
            anchors.right: parent.right
            anchors.verticalCenter: parent.verticalCenter
            s: root.s
            on: arow.on
            value: arow.level
            focused: arow.on && root.faderFocus === arow.faderIndex
            onMoved: (v) => arow.faderMoved(v)
            onFocusRequested: root.faderFocus = arow.faderIndex

            HoverHandler {
                onHoveredChanged: if (hovered && arow.on) root.faderFocus = arow.faderIndex
            }

            MouseArea {
                anchors.fill: parent
                acceptedButtons: Qt.NoButton
                enabled: arow.on
                property real acc: 0
                onWheel: (event) => {
                    root.faderFocus = arow.faderIndex;
                    acc += event.angleDelta.y / 120;
                    const notches = Math.trunc(acc);
                    if (notches !== 0) {
                        root.stepFocused(notches * 5);
