                }

                GlyphIcon {
                    id: btGlyph
                    anchors.left: parent.left
                    anchors.leftMargin: 8 * root.s
                    anchors.verticalCenter: parent.verticalCenter
                    width: 17 * root.s
                    height: 17 * root.s
                    name: "bluetooth"
                    color: root.btConnected.length > 0 ? Theme.vermLit : Theme.iconDim
                    stroke: 1.7
                }

                Column {
                    anchors.left: btGlyph.right
                    anchors.leftMargin: 11 * root.s
                    anchors.right: btRight.left
                    anchors.rightMargin: 8 * root.s
                    anchors.verticalCenter: parent.verticalCenter
                    spacing: 2 * root.s

                    Text {
                        width: parent.width
                        text: "Bluetooth"
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 12.5 * root.s
                        font.weight: Font.DemiBold
                        elide: Text.ElideRight
                    }
                    Text {
                        width: parent.width
                        text: root.btSubText
                        color: root.btPrimary ? Theme.vermLit : Theme.dim
                        font.family: Theme.font
                        font.pixelSize: 10 * root.s
                        font.weight: root.btPrimary ? Font.DemiBold : Font.Medium
                        elide: Text.ElideRight
                    }
                }

                Row {
                    id: btRight
                    anchors.right: parent.right
                    anchors.rightMargin: 8 * root.s
                    anchors.verticalCenter: parent.verticalCenter
                    spacing: 9 * root.s

                    Filament {
                        anchors.verticalCenter: parent.verticalCenter
                        visible: root.btPrimary !== null && root.btBattery >= 0
                        s: root.s
                        kind: "battery"
                        level: Math.max(0, root.btBattery) / 100
                    }

                    LinkToggle {
                        s: root.s
                        anchors.verticalCenter: parent.verticalCenter
                        on: root.btOn
                        onToggled: if (root.btAdapter) root.btAdapter.enabled = !root.btAdapter.enabled
                    }

                    GlyphIcon {
                        anchors.verticalCenter: parent.verticalCenter
                        width: 14 * root.s
                        height: 14 * root.s
                        name: "chevron-right"
                        color: Theme.iconDim
                        stroke: 1.8
                    }
                }
            }

            Item {
                width: parent.width
                height: 20 * root.s

                Row {
                    anchors.left: parent.left
                    anchors.verticalCenter: parent.verticalCenter
                    spacing: 6 * root.s

                    Item {
                        anchors.verticalCenter: parent.verticalCenter
                        width: 10 * root.s
                        height: 10 * root.s
                    }

                    Text {
                        id: inboxKanji
                        anchors.verticalCenter: parent.verticalCenter
                        visible: Flags.showGlyphs
                        text: "報"
                        color: Theme.dim
                        font.family: Theme.fontJp
                        font.weight: Font.Medium
                        font.pixelSize: 11.5 * root.s
                    }
                    Text {
                        anchors.verticalCenter: parent.verticalCenter
                        text: Flags.showGlyphs ? "INBOX" : "Notifications"
                        color: Theme.faint
                        font.family: Theme.font
                        font.pixelSize: 9 * root.s
                        font.weight: Font.Bold
                        font.letterSpacing: Flags.showGlyphs ? 1.8 * root.s : 0.8 * root.s
                    }
                }

                Row {
                    id: clearRow
                    anchors.right: parent.right
                    anchors.verticalCenter: parent.verticalCenter
                    visible: Notifs.count > 0
                    spacing: 4 * root.s

                    Text {
                        anchors.verticalCenter: parent.verticalCenter
                        visible: Flags.showGlyphs
                        text: "払"
                        color: clearArea.containsMouse ? Theme.vermLit : Theme.vermDim
                        font.family: Theme.fontJp
                        font.pixelSize: 9 * root.s
                        font.weight: Font.Bold
                    }
                    GlyphIcon {
                        anchors.verticalCenter: parent.verticalCenter
                        visible: !Flags.showGlyphs
                        width: 11 * root.s
                        height: 11 * root.s
                        name: "trash"
                        color: clearArea.containsMouse ? Theme.vermLit : Theme.vermDim
                        stroke: 1.8
                    }
                    Text {
                        anchors.verticalCenter: parent.verticalCenter
                        text: "CLEAR"
                        color: clearArea.containsMouse ? Theme.vermLit : Theme.vermDim
                        font.family: Theme.font
                        font.pixelSize: 9 * root.s
                        font.weight: Font.Bold
                        font.letterSpacing: 1.4 * root.s
                    }
                }

                MouseArea {
                    id: clearArea
                    anchors.fill: clearRow
                    anchors.margins: -5 * root.s
                    visible: Notifs.count > 0
                    hoverEnabled: true
                    cursorShape: Qt.PointingHandCursor
                    onClicked: Notifs.clearAll()
                }
            }

            Item {
                visible: Notifs.count > 0
                width: parent.width
                height: notifFlick.height

                Flickable {
                    id: notifFlick
                    width: parent.width
                    height: Math.min(notifCol.implicitHeight, 320 * root.s)
                    contentHeight: notifCol.implicitHeight
                    clip: true
                    boundsBehavior: Flickable.StopAtBounds
                    onContentHeightChanged: returnToBounds()

                    Column {
                        id: notifCol
                        width: notifFlick.width
                        spacing: 6 * root.s

                        Repeater {
                            model: Notifs.groups

                            Column {
                                id: group
                                required property var modelData
                                readonly property bool expanded: Notifs.expandedApps[modelData.app] === true
                                width: notifCol.width
                                spacing: 2 * root.s

                                Repeater {
                                    model: group.modelData.criticals

                                    NotifRow {
                                        required property var modelData
                                        entry: modelData
                                        critical: true
                                    }
                                }

                                Rectangle {
                                    id: groupHead
                                    width: parent.width
                                    height: 32 * root.s
                                    radius: 8 * root.s
                                    color: headHover.hovered ? Theme.frameBg : "transparent"

                                    HoverHandler {
                                        id: headHover
                                        onHoveredChanged: root.reportRowHover(groupHead, hovered)
                                    }

                                    MouseArea {
                                        anchors.fill: parent
                                        cursorShape: Qt.PointingHandCursor
                                        onClicked: Notifs.toggleExpanded(group.modelData.app)
                                    }

                                    Rectangle {
                                        id: headTile
                                        anchors.left: parent.left
                                        anchors.leftMargin: 6 * root.s
                                        anchors.verticalCenter: parent.verticalCenter
                                        width: 20 * root.s
                                        height: 20 * root.s
                                        radius: 6 * root.s
                                        color: Theme.tileBg
                                        border.width: 1
                                        border.color: Theme.border

                                        Image {
                                            id: headImg
                                            anchors.fill: parent
