    Loader {
        id: ldDisplay
        active: false
        anchors.fill: parent
        sourceComponent: Display {
            s: pill.s
            open: pill.displayOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldInput
        active: false
        anchors.fill: parent
        sourceComponent: Input {
            s: pill.s
            open: pill.inputOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldLook
        active: false
        anchors.fill: parent
        sourceComponent: Look {
            s: pill.s
            open: pill.lookOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldIdlelock
        active: false
        anchors.fill: parent
        sourceComponent: IdleLock {
            s: pill.s
            open: pill.idlelockOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
