                height: 14 * pill.s
                name: osd.kind === "brightness" ? "sun" : (osd.muted ? "speaker-off" : "speaker")
                color: osd.kind === "volume" && osd.muted ? Theme.dim : Theme.iconDim
                stroke: 1.7
            }

            Rectangle {
                anchors.verticalCenter: parent.verticalCenter
                width: 64 * pill.s
                height: 3 * pill.s
                radius: 1.5 * pill.s
                color: Theme.threadBg

                Rectangle {
                    anchors.left: parent.left
                    anchors.top: parent.top
                    anchors.bottom: parent.bottom
                    width: parent.width * (osd.kind === "brightness" ? osd.brightness : osd.volume)
                    radius: parent.radius
                    color: osd.kind === "volume" && osd.muted ? Theme.vermDim : Theme.vermLit
                    Behavior on width { NumberAnimation { duration: Motion.fast } }
                }
            }

            Text {
                anchors.verticalCenter: parent.verticalCenter
                text: Math.round((osd.kind === "brightness" ? osd.brightness : osd.volume) * 100) + "%"
                color: osd.kind === "volume" && osd.muted ? Theme.dim : Theme.cream
                font.family: Theme.font
                font.pixelSize: 10.5 * pill.s
                font.weight: Font.DemiBold
                font.features: ({ "tnum": 1 })
            }
        }
    }

    Item {
        id: rest
        anchors.fill: parent
        opacity: (pill.expanded || pill.dragActive || pill.mode === "game" || pill.mode === "toast" || pill.mode === "osd" || pill.mode === "quickChoose" || pill.mode === "quickCount") ? 0 : Math.pow(pill.morphCloseness, 1.5)
        visible: opacity > 0.01
        Behavior on opacity { NumberAnimation { duration: pill.mode === "rest" ? Motion.fast : Math.round(260 * Motion.mult) } }

        Row {
            id: restRow
            anchors.centerIn: parent
            spacing: 9 * pill.s
            Item {
                id: restKanji
                visible: pill.specialView === ""

                /** Audio leaving the speakers flips the left slot into the live waveform. */
                readonly property bool barsOn: Flags.musicViz && Cava.active

                anchors.verticalCenter: parent.verticalCenter

                width: barsOn ? musicBars.implicitWidth : 0
                height: barsOn ? musicBars.implicitHeight : 0

                MusicBars {
                    id: musicBars
                    anchors.centerIn: parent
                    s: pill.s

                    opacity: restKanji.barsOn ? 1 : 0
                    scale: restKanji.barsOn ? 1 : 0.7

                    Behavior on opacity {
                        NumberAnimation {
                            duration: Motion.standard
                            easing.type: Motion.easeStandard
                        }
                    }

                    Behavior on scale {
                        NumberAnimation {
                            duration: Motion.standard
                            easing.type: Motion.easeStandard
                        }
                    }
                }
            }
            Text {
                id: restTime
                visible: pill.specialView === ""
                anchors.verticalCenter: parent.verticalCenter
                text: clock.hhmm
                color: Theme.cream
                font.family: Theme.font
                font.pixelSize: 18 * pill.s
                font.weight: Font.DemiBold
                font.features: { "tnum": 1 }
            }
            Text {
                visible: pill.specialView !== ""
                anchors.verticalCenter: parent.verticalCenter
                text: pill.specialView
                color: Theme.cream
                font.family: Theme.font
                font.pixelSize: 16 * pill.s
                font.weight: Font.DemiBold
            }
        }
    }

    Item {
        id: hover
        anchors.fill: parent

        readonly property bool live: pill.mode === "hover"

        readonly property real clockMorph: Math.min(1, pill.morphCloseness + 0.08)
        readonly property real clockTextMorph: Math.pow(Math.max(0, (pill.contentMorph - 0.12) / 0.88), 1.2)
        readonly property real mediaMorph: Math.max(0, (pill.contentMorph - 0.18) / 0.82)
        readonly property real calendarMorph: Math.max(0, (pill.contentMorph - 0.55) / 0.45)
        readonly property real trayMorph: Math.max(0, (pill.contentMorph - 0.45) / 0.55)

        readonly property real clockStartX: restTime.mapToItem(hover, restTime.width / 2, restTime.height / 2).x
        readonly property real clockStartY: restTime.mapToItem(hover, restTime.width / 2, restTime.height / 2).y

        readonly property real clockEndX: hoverTime.x + hoverTime.width / 2
        readonly property real clockEndY: hoverTime.y + hoverTime.height / 2

        opacity: live ? 1 : 0
        visible: opacity > 0.01

        Behavior on opacity {
            NumberAnimation {
                duration: pill.mode === "hover" ? Motion.fast : 40
                easing.type: Motion.easeStandard
            }
        }

        Row {
            id: hoverRow

            anchors.verticalCenter: parent.verticalCenter
            anchors.horizontalCenter: parent.horizontalCenter
            anchors.horizontalCenterOffset: -20 * pill.s

            spacing: 20 * pill.s

            Row {
                id: statusRow

                anchors.verticalCenter: parent.verticalCenter

                spacing: 12 * pill.s

                opacity: hover.mediaMorph

                transform: Translate {
                    x: 42 * pill.s * (1 - hover.mediaMorph)
                }

                Loader {
                    id: hoverMedia

                    anchors.verticalCenter: parent.verticalCenter

                    x: -64 * pill.s * (1 - hover.mediaMorph)

                    opacity: hover.mediaMorph
                    scale: 0.82 + 0.18 * hover.mediaMorph

                    active: pill.hasMedia
                    visible: active

                    width: pill.mediaW
                    height: pill.mediaH

                    sourceComponent: Media {
                        id: bud
                        s: pill.s
                        open: true
                        morphCloseness: hover.mediaMorph

                        onRequestClose: {
                            hoverMedia.active = false
                        }
                    }
                }

                Workspaces {
                    id: ws

                    anchors.verticalCenter: parent.verticalCenter

                    s: pill.s
                    screenName: pill.screenName

                    enabled: hover.live

                    opacity: hover.trayMorph
                    scale: 0.9 + 0.1 * hover.trayMorph
                }

                MinimizedTray {
                    id: minimized

                    anchors.verticalCenter: parent.verticalCenter

                    s: pill.s
                    screenName: pill.screenName

                    enabled: hover.live
                    visible: count > 0

                    opacity: hover.trayMorph
                    scale: 0.9 + 0.1 * hover.trayMorph
                }
            }

            Item {
                id: clockContainer

                anchors.verticalCenter: parent.verticalCenter

                implicitWidth: hoverClock.implicitWidth
                implicitHeight: hoverClock.implicitHeight

                Column {
                    id: hoverClock

                    anchors.centerIn: parent

                    spacing: 8 * pill.s

                    Text {
                        id: hoverTime

                        anchors.horizontalCenter: parent.horizontalCenter
                        anchors.horizontalCenterOffset: 20 * pill.s

                        text: clock.hhmm

                        color: Theme.cream

                        font.family: Theme.font
                        font.pixelSize: 28 * pill.s
                        font.weight: Font.DemiBold
                        font.features: { "tnum": 1 }

                        opacity: hover.clockTextMorph
                        scale: 0.92 + 0.08 * hover.clockTextMorph

                        transform: Translate {
                            x: (hover.clockStartX - hover.clockEndX) * (1 - hover.clockMorph)
                            y: (hover.clockStartY - hover.clockEndY) * (1 - hover.clockMorph)
                        }
                    }

                    CalendarStyle {
                        id: calendarStyle

                        anchors.horizontalCenter: parent.horizontalCenter
                        anchors.horizontalCenterOffset: 20 * pill.s

                        width: 220 * pill.s
                        height: 48 * pill.s

                        scale: pill.s
                        opacity: hover.calendarMorph
                    }
                }

                MouseArea {
                    anchors.centerIn: parent

                    width: hoverClock.implicitWidth + 22 * pill.s
                    height: hoverClock.implicitHeight + 10 * pill.s

                    enabled: hover.live

                    cursorShape: Qt.PointingHandCursor

                    onClicked: {
                        pill.requestSurface("calendar")
                    }
                }
            }
        }
    }

    /**
     * Morphing surfaces, one latch-once Loader each (see surfaceItem). Eager,
     * they dominated startup and per-monitor RAM; now a surface is built
     * synchronously on its first open and kept. Each loader fills the pill so
     * the PillSurface inside anchors exactly as it did as a direct child.
     *
     * The hot trio preloads shortly after startup: the mixer needs its Pipewire
     * trackers bound before it looks right, so a cold first open visibly popped
     * faders in. Startup itself stays light.
     */
    Timer {
        interval: 2500
        running: true
        onTriggered: {
            ldMixer.active = true;
            ldMedia.active = true;
            ldLink.active = true;
        }
    }

    Loader {
        id: ldMixer
        active: false
        anchors.fill: parent
        sourceComponent: Mixer {
            s: pill.s
            open: pill.mixerOpen
            morphCloseness: pill.morphCloseness
        }
    }

    Loader {
        id: ldCalendar
        active: false
        anchors.fill: parent
        sourceComponent: Calendar {
            s: pill.s
            open: pill.calendarOpen
            morphCloseness: pill.morphCloseness
        }
    }

    Loader {
        id: ldLauncher
        active: false
        anchors.fill: parent
        sourceComponent: Launcher {
            s: pill.s
            open: pill.launcherOpen
            morphCloseness: pill.morphCloseness
            onRequestClose: pill.requestClose()
        }
    }

    Loader {
        id: ldClip
        active: false
        anchors.fill: parent
        sourceComponent: Clipboard {
            s: pill.s
            open: pill.clipboardOpen
            morphCloseness: pill.morphCloseness
            onRequestClose: pill.requestClose()
        }
    }

    Loader {
        id: ldWall
        active: false
        anchors.fill: parent
        sourceComponent: Wallpaper {
            s: pill.s
            open: pill.wallpaperOpen
            morphCloseness: pill.morphCloseness
            onRequestClose: pill.requestClose()
        }
    }

    Loader {
        id: ldPower
        active: false
        anchors.fill: parent
        sourceComponent: Power {
            s: pill.s
            open: pill.powerOpen
            morphCloseness: pill.morphCloseness
            onRequestClose: pill.requestClose()
        }
    }

    Loader {
        id: ldMedia
        active: false
        anchors.fill: parent
        sourceComponent: Media {
            s: pill.s
            open: pill.mediaOpen
            morphCloseness: pill.morphCloseness

        }
    }

    Loader {
        id: ldLink
        active: false
        anchors.fill: parent
        sourceComponent: Link {
            s: pill.s
            open: pill.linkOpen
            initialView: pill.linkInitialView
            morphCloseness: pill.morphCloseness

        }
    }

    onLinkOpenChanged: if (!linkOpen) linkInitialView = "main"

    Loader {
        id: ldBattery
        active: false
        anchors.fill: parent
        sourceComponent: BatterySurface {
            s: pill.s
            open: pill.batteryOpen
            morphCloseness: pill.morphCloseness

        }
    }

    Loader {
        id: ldSettings
        active: false
        anchors.fill: parent
        sourceComponent: Settings {
            s: pill.s
            open: pill.settingsOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldKeybinds
        active: false
        anchors.fill: parent
        sourceComponent: Keybinds {
            s: pill.s
            open: pill.keybindsOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldWorkspaces
        active: false
        anchors.fill: parent
        sourceComponent: WorkspacesSurface {
            s: pill.s
            open: pill.workspacesOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldStash
        active: false
        anchors.fill: parent
        sourceComponent: Stash {
            s: pill.s
            open: pill.stashOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldSpaceapps
        active: false
        anchors.fill: parent
        sourceComponent: SpaceApps {
            s: pill.s
            open: pill.spaceappsOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldRecorder
        active: false
        anchors.fill: parent
        sourceComponent: Recorder {
            s: pill.s
            screenName: pill.screenName
            open: pill.recorderOpen
            morphCloseness: pill.morphCloseness

        }
    }

    Loader {
        id: ldSysmon
        active: false
        anchors.fill: parent
        sourceComponent: SysmonSurface {
            s: pill.s
            open: pill.sysmonOpen
            morphCloseness: pill.morphCloseness

        }
    }

    Loader {
        id: ldAppearance
        active: false
        anchors.fill: parent
        sourceComponent: Appearance {
            s: pill.s
            open: pill.appearanceOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldUpdates
        active: false
        anchors.fill: parent
        sourceComponent: Updates {
            s: pill.s
            open: pill.updatesOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldDisplay
        active: false
        anchors.fill: parent
        sourceComponent: Display {
            s: pill.s
            open: pill.displayOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldInput
        active: false
        anchors.fill: parent
        sourceComponent: Input {
            s: pill.s
            open: pill.inputOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldLook
        active: false
        anchors.fill: parent
        sourceComponent: Look {
            s: pill.s
            open: pill.lookOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldIdlelock
        active: false
        anchors.fill: parent
        sourceComponent: IdleLock {
            s: pill.s
            open: pill.idlelockOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldAnimation
        active: false
        anchors.fill: parent
        sourceComponent: AnimationSurface {
            s: pill.s
            open: pill.animationOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Loader {
        id: ldFontpicker
        active: false
        anchors.fill: parent
        sourceComponent: FontPicker {
            s: pill.s
            open: pill.fontpickerOpen
            morphCloseness: pill.morphCloseness

            onRequestSurface: (name) => pill.requestSurface(name)
        }
    }

    Osd {
        id: osd
        anchors.fill: parent
        anchors.topMargin: 12 * pill.s
        anchors.leftMargin: 18 * pill.s
        anchors.rightMargin: 18 * pill.s
        anchors.bottomMargin: 12 * pill.s
        s: pill.s
        screenName: pill.screenName
        suppressed: pill.surfaceOpen || pill.held
        expanded: pill.expanded
        enabled: pill.mode === "osd"
        opacity: pill.mode === "osd" ? 1 : 0
        visible: opacity > 0.01
        Behavior on opacity {
            NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard }
        }
    }

    Loader {
        id: toastLoader
        active: pill.toastActive
        anchors.fill: parent
        anchors.topMargin: 12 * pill.s
        anchors.leftMargin: 16 * pill.s
        anchors.rightMargin: 16 * pill.s
        anchors.bottomMargin: 12 * pill.s
        enabled: pill.mode === "toast"
        opacity: pill.mode === "toast" ? 1 : 0
        visible: opacity > 0.01
        Behavior on opacity {
            NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard }
        }

        sourceComponent: Item {
            implicitHeight: toastContent.implicitHeight

            Toast {
                id: toastContent
                anchors.left: parent.left
                anchors.right: parent.right
                anchors.top: parent.top
                s: pill.s
                live: pill.mode === "toast"
                notif: Notifs.popups.length > 0 ? Notifs.popups[Notifs.popups.length - 1] : null
            }

            Text {
                anchors.right: parent.right
                anchors.bottom: parent.bottom
                visible: Notifs.popups.length > 1
                text: "+" + (Notifs.popups.length - 1)
                color: Theme.dim
                font.family: Theme.font
                font.pixelSize: 9 * pill.s
                font.weight: Font.DemiBold
            }
        }
    }

    /**
     * Standalone quick-record source chooser. Driven by the SUPER+D keybind with
     * no recorder surface open: it grows the pill on the focused monitor only
     * (mode "quickChoose") and offers the same Screen and Window / Region picks as
     * the surface. Screen with one monitor resolves at once; several monitors flip
     * to the inline sub-choice. A pick fires ScreenRec.prepareScreen / prepareWindow
     * → targetReady → the central countdown, then closes.
     */
    Item {
        id: quickChooser
        anchors.fill: parent
        anchors.margins: 6 * pill.s
        enabled: pill.mode === "quickChoose"
        opacity: pill.mode === "quickChoose" ? Math.pow(pill.morphCloseness, 1.3) : 0
        visible: opacity > 0.01
        Behavior on opacity {
            NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard }
        }

        Row {
            id: quickSources
            anchors.fill: parent
            visible: !ScreenRec.quickScreenChoosing
            spacing: 6 * pill.s

            Repeater {
                model: [
                    { kind: "screen", label: "Screen", glyph: "monitor" },
                    { kind: "window", label: "Window / Region", glyph: "video" }
                ]

                Rectangle {
                    id: qSrcTile
                    required property var modelData
                    width: (quickSources.width - 6 * pill.s) / 2
                    height: parent.height
                    radius: 11 * pill.s
                    color: qSrcArea.containsMouse ? Qt.alpha(Theme.vermLit, 0.16) : Theme.tileBg
                    border.width: 1
                    border.color: qSrcArea.containsMouse ? Qt.alpha(Theme.vermLit, 0.5) : Theme.border
                    Behavior on color { ColorAnimation { duration: Motion.fast } }

                    Row {
                        anchors.centerIn: parent
                        spacing: 8 * pill.s

                        GlyphIcon {
                            width: 16 * pill.s
                            height: 16 * pill.s
                            name: qSrcTile.modelData.glyph
                            color: qSrcArea.containsMouse ? Theme.vermLit : Theme.iconDim
                            stroke: 1.7
                        }
                        Text {
                            height: 16 * pill.s
                            verticalAlignment: Text.AlignVCenter
                            text: qSrcTile.modelData.label
                            color: qSrcArea.containsMouse ? Theme.cream : Theme.subtle
                            font.family: Theme.font
                            font.pixelSize: 11 * pill.s
                            font.weight: Font.Bold
                        }
                    }

                    MouseArea {
                        id: qSrcArea
                        anchors.fill: parent
                        hoverEnabled: true
                        cursorShape: Qt.PointingHandCursor
                        onClicked: pill.quickChooseSource(qSrcTile.modelData.kind)
                    }
                }
            }
        }

        ListView {
            id: quickScreens
            anchors.fill: parent
            anchors.rightMargin: 22 * pill.s
            visible: ScreenRec.quickScreenChoosing
            orientation: ListView.Horizontal
            spacing: 6 * pill.s
            clip: true
            boundsBehavior: Flickable.StopAtBounds
            model: ScreenRec.monitors

            delegate: Rectangle {
                id: qMonTile
                required property var modelData
                width: 152 * pill.s
                height: quickScreens.height
                radius: 11 * pill.s
                color: qMonArea.containsMouse ? Qt.alpha(Theme.vermLit, 0.16) : Theme.tileBg
                border.width: 1
                border.color: qMonArea.containsMouse ? Qt.alpha(Theme.vermLit, 0.5) : Theme.border
                Behavior on color { ColorAnimation { duration: Motion.fast } }

                Column {
                    anchors.centerIn: parent
                    spacing: 2 * pill.s

                    Text {
                        anchors.horizontalCenter: parent.horizontalCenter
                        text: qMonTile.modelData.name
                        color: Theme.cream
                        font.family: Theme.font
                        font.pixelSize: 11.5 * pill.s
                        font.weight: Font.Bold
                    }
                    Text {
                        anchors.horizontalCenter: parent.horizontalCenter
                        text: qMonTile.modelData.w + " × " + qMonTile.modelData.h
                        color: Theme.subtle
                        font.family: Theme.font
                        font.pixelSize: 9.5 * pill.s
                        font.features: { "tnum": 1 }
                    }
                }

                MouseArea {
                    id: qMonArea
                    anchors.fill: parent
                    hoverEnabled: true
                    cursorShape: Qt.PointingHandCursor
                    onClicked: pill.quickPickMonitor(qMonTile.modelData.name)
                }
            }
        }

        WheelScroller {
            flick: quickScreens
            s: pill.s
            anchors.fill: quickScreens
            visible: ScreenRec.quickScreenChoosing
        }

        GlyphIcon {
            anchors.top: parent.top
            anchors.right: parent.right
            anchors.margins: 5 * pill.s
            visible: ScreenRec.quickScreenChoosing
            width: 12 * pill.s
            height: 12 * pill.s
            name: "chevron-left"
            color: qBackArea.containsMouse ? Theme.cream : Theme.faint
            stroke: 2

            MouseArea {
                id: qBackArea
                anchors.fill: parent
                anchors.margins: -7 * pill.s
                hoverEnabled: true
                cursorShape: Qt.PointingHandCursor
                onClicked: ScreenRec.quickScreenChoosing = false
            }
        }
    }

    /**
     * Standalone pre-roll countdown toast. Shown at the pill top on the focused
     * monitor when the central countdown runs and the recorder surface is closed
     * (mode "quickCount"): a big flame-glow numeral over a small "GET READY" label.
     * Tapping cancels. The surface's own in-bar countdown covers the surface case.
     */
    Item {
        id: quickCount
        anchors.fill: parent
        enabled: pill.mode === "quickCount"
        opacity: pill.mode === "quickCount" ? Math.pow(pill.morphCloseness, 1.3) : 0
        visible: opacity > 0.01
        Behavior on opacity {
            NumberAnimation { duration: Motion.standard; easing.type: Motion.easeStandard }
        }

        Column {
            anchors.centerIn: parent
            spacing: 1 * pill.s

            Text {
                anchors.horizontalCenter: parent.horizontalCenter
                text: ScreenRec.countdown
                color: Theme.flameGlow
                font.family: Theme.font
                font.pixelSize: 28 * pill.s
                font.weight: Font.ExtraBold
                font.features: { "tnum": 1 }
            }
            Text {
                anchors.horizontalCenter: parent.horizontalCenter
                text: "GET READY"
                color: Theme.dim
                font.family: Theme.font
                font.pixelSize: 8.5 * pill.s
                font.weight: Font.Bold
                font.capitalization: Font.AllUppercase
                font.letterSpacing: 1.6 * pill.s
            }
        }

        MouseArea {
            anchors.fill: parent
            cursorShape: Qt.PointingHandCursor
            onClicked: ScreenRec.cancel()
        }
    }
}

